import re

Postings = list[int]
Tokens = list[str]
InvertedIndex = dict[str, Postings]
WordCounts = dict[str, int]
TopWords = dict[int, str]


def tokenize(document: str) -> Tokens:
    """Split a document into lowercase words, dropping surrounding punctuation."""
    words: Tokens = []
    for chunk in document.lower().split(" "):
        cleaned = re.sub(r"^\W+|\W+$", "", chunk)
        if cleaned:
            words.append(cleaned)
    return words


def count_words(words: Tokens) -> WordCounts:
    """Count how often each word occurs in a token list."""
    counts: WordCounts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    return counts


def most_frequent_word(words: Tokens) -> str:
    """Return the most frequent word, breaking ties alphabetically."""
    counts = count_words(words)
    if not counts:
        return ""
    return min(counts, key=lambda word: (-counts[word], word))


def build_inverted_index(tokenized: list[Tokens]) -> InvertedIndex:
    """Map every word to the sorted list of document indices containing it."""
    inverted: InvertedIndex = {}
    for doc_id, words in enumerate(tokenized):
        for word in set(words):
            inverted.setdefault(word, []).append(doc_id)
    for postings in inverted.values():
        postings.sort()
    return inverted


def index(
    documents: list[str],
) -> tuple[InvertedIndex, TopWords]:
    """Return the inverted index and the top word of each document."""
    tokenized: list[Tokens] = [tokenize(doc) for doc in documents]
    inverted = build_inverted_index(tokenized)
    top_words: TopWords = {}
    for doc_id, words in enumerate(tokenized):
        top_words[doc_id] = most_frequent_word(words)
    return inverted, top_words


def format_report(inverted: InvertedIndex, top_words: TopWords) -> str:
    """Render a human readable summary of the index."""
    lines: list[str] = []
    for word in sorted(inverted):
        positions = ", ".join(str(doc_id) for doc_id in inverted[word])
        lines.append(f"{word}: [{positions}]")
    lines.append("--")
    for doc_id in sorted(top_words):
        lines.append(f"doc {doc_id} -> {top_words[doc_id]}")
    return "\n".join(lines)


def main() -> None:
    documents: list[str] = [
        "apple banana",
        "banana cherry",
        "cherry cherry apple pie",
    ]
    inverted, top_words = index(documents)
    print(format_report(inverted, top_words))
    shared = [word for word, docs in inverted.items() if len(docs) > 1]
    print("shared words:", ", ".join(sorted(shared)))


if __name__ == "__main__":
    main()

