DISCOUNT_RATE = 0.05
DISCOUNT_THRESHOLD = 5

Item = tuple[str, str, int, float]
Costs = dict[str, float]
Counts = dict[str, int]


def validate_cart(cart: list[Item]) -> None:
    """Reject malformed cart entries before any money is summed."""
    for index, entry in enumerate(cart):
        if len(entry) != 4:
            raise ValueError(f"cart entry {index} must hold four fields")
        name, category, quantity, unit_price = entry
        if not name or not category:
            raise ValueError(f"cart entry {index} has an empty name or category")
        if quantity <= 0:
            raise ValueError(f"quantity for {name!r} must be positive")
        if unit_price < 0:
            raise ValueError(f"unit price for {name!r} must not be negative")


def group_by_category(
    items: list[Item],
) -> tuple[Costs, Counts]:
    """Sum cost and quantity per category."""
    costs: dict[str, float] = {}
    counts: dict[str, int] = {}
    for item in items:
        _, category, quantity, unit_price = item
        costs[category] = costs.get(category, 0.0) + quantity * unit_price
        counts[category] = counts.get(category, 0) + quantity
    return costs, counts


def apply_discounts(costs: Costs, counts: Counts) -> dict[str, float]:
    """Knock five percent off categories holding five or more units."""
    final: dict[str, float] = {}
    for category, total in costs.items():
        if counts[category] >= DISCOUNT_THRESHOLD:
            final[category] = round(total * (1.0 - DISCOUNT_RATE), 2)
        else:
            final[category] = round(total, 2)
    return final


def checkout(
    cart: list[Item],
) -> dict[str, float]:
    validate_cart(cart)
    costs, counts = group_by_category(cart)
    return apply_discounts(costs, counts)


def format_report(
    totals: dict[str, float],
) -> list[str]:
    lines: list[str] = []
    for category in sorted(totals):
        lines.append(f"{category:<10}{totals[category]:>8.2f}")
    lines.append(f"{'TOTAL':<10}{sum(totals.values()):>8.2f}")
    return lines


def main() -> None:
    cart: list[Item] = [
        ("apple", "fruit", 2, 1.5),
        ("banana", "fruit", 3, 1.0),
        ("soap", "household", 1, 4.25),
        ("mug", "household", 2, 6.0),
        ("pen", "stationery", 4, 0.75),
    ]
    totals = checkout(cart)
    for line in format_report(totals):
        print(line)

    _, quantities = group_by_category(cart)
    discounted: list[str] = [c for c, q in quantities.items() if q >= DISCOUNT_THRESHOLD]
    print("discounted:", ", ".join(sorted(discounted)) if discounted else "none")


if __name__ == "__main__":
    main()

