from collections.abc import Iterator

Ballot = list[str]
Ballots = list[Ballot]


def clean_ballots(ballots: Ballots) -> Ballots:
    """Drop blank names, repeated rankings and fully empty ballots."""
    cleaned: Ballots = []
    for ballot in ballots:
        seen: list[str] = []
        for name in ballot:
            if name and name not in seen:
                seen.append(name)
        if seen:
            cleaned.append(seen)
    return cleaned


def count_first_choices(ballots: Ballots) -> dict[str, int]:
    """Count how many ballots currently rank each candidate first."""
    counts: dict[str, int] = {}
    for ballot in ballots:
        counts[ballot[0]] = counts.get(ballot[0], 0) + 1
    return counts


def remove_candidate(ballots: Ballots, name: str) -> Ballots:
    """Strip an eliminated candidate from every ballot."""
    reduced: Ballots = []
    for ballot in ballots:
        kept = [c for c in ballot if c != name]
        if kept:
            reduced.append(kept)
    return reduced


def majority_winner(counts: dict[str, int]) -> str | None:
    total = sum(counts.values())
    for name, votes in counts.items():
        if votes * 2 > total:
            return name
    return None


def fewest_votes(counts: dict[str, int]) -> str:
    lowest = min(counts.values())
    tied = sorted(name for name, votes in counts.items() if votes == lowest)
    return tied[0]


def rounds(ballots: Ballots) -> Iterator[dict[str, int]]:
    """Yield the first-choice counts of each successive elimination round."""
    current = clean_ballots(ballots)
    while current:
        counts = count_first_choices(current)
        yield counts
        if majority_winner(counts) is not None:
            return
        current = remove_candidate(current, fewest_votes(counts))


def format_round(round_no: int, counts: dict[str, int]) -> str:
    ordered = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    parts = [f"{name}: {votes}" for name, votes in ordered]
    return f"Round {round_no} -> " + ", ".join(parts)


def ballot_depths(ballots: Ballots) -> tuple[int, int]:
    """Return (number of ballots, deepest ranking)."""
    lengths: list[int] = [len(ballot) for ballot in ballots]
    if not lengths:
        return (0, 0)
    return (len(lengths), max(lengths))


def tally(ballots) -> tuple[str, int]:
    round_no = 0
    for counts in rounds(ballots):
        round_no += 1
        winner = majority_winner(counts)
        if winner is not None:
            return (winner, round_no)
    return ("", round_no)


def main() -> None:
    ballots: Ballots = [
        ["Alice", "Bob"],
        ["Bob", "Alice"],
        ["Alice", "Bob"],
    ]
    for round_no, counts in enumerate(rounds(ballots), start=1):
        print(format_round(round_no, counts))
    voters, depth = ballot_depths(ballots)
    print(f"{voters} ballots, up to {depth} ranked choices each")
    winner, rounds_taken = tally(ballots)
    print(f"Winner: {winner} after {rounds_taken} round(s)")


if __name__ == "__main__":
    main()

