Entry = tuple[str, str, int]
Hit = tuple[str, int]
Hits = list[Hit]
Grouped = dict[str, Hits]
Stats = tuple[int, int, int]
UserStats = dict[str, Stats]


def parse_line(line: str) -> Entry:
    """Split a log line into its IP address, user name and status code."""
    parts = line.split()
    if len(parts) != 3:
        raise ValueError(f"malformed log line: {line!r}")
    ip, user, raw_code = parts
    if not raw_code.isdigit():
        raise ValueError(f"status code is not an integer: {raw_code!r}")
    return ip, user, int(raw_code)


def group_by_user(logs: list[str]) -> Grouped:
    """Map every user name to the (ip, status) pairs recorded for them."""
    grouped: Grouped = {}
    for line in logs:
        ip, user, code = parse_line(line)
        grouped.setdefault(user, []).append((ip, code))
    return grouped


def summarize(hits: Hits) -> Stats:
    """Total requests, distinct source IPs and error responses for one user."""
    addresses: set[str] = set()
    errors = 0
    for ip, code in hits:
        addresses.add(ip)
        if code >= 400:
            errors += 1
    return len(hits), len(addresses), errors


def analyze(logs):
    """Return {user: (requests, unique_ips, errors)} for the given log lines."""
    stats: UserStats = {}
    for user, hits in group_by_user(logs).items():
        stats[user] = summarize(hits)
    return stats


def most_active(stats: UserStats, limit: int = 3) -> list[str]:
    """User names ordered by request count, ties broken alphabetically."""
    ranked = sorted(stats, key=lambda user: (-stats[user][0], user))
    return ranked[:limit]


def error_rates(stats: UserStats) -> dict[str, float]:
    rates: dict[str, float] = {}
    for user, (requests, _ips, errors) in stats.items():
        rates[user] = errors / requests
    return rates


def format_report(stats: UserStats) -> list[str]:
    rates = error_rates(stats)
    lines: list[str] = []
    for user in most_active(stats, limit=len(stats)):
        requests, unique_ips, errors = stats[user]
        lines.append(
            f"{user}: {requests} requests from {unique_ips} IP(s), "
            f"{errors} error(s) ({rates[user]:.0%})"
        )
    return lines


def main() -> None:
    logs: list[str] = [
        "10.0.0.1 alice 200",
        "10.0.0.2 alice 500",
        "10.0.0.3 bob 200",
        "10.0.0.3 bob 404",
        "10.0.0.3 bob 301",
        "192.168.1.7 carol 503",
    ]
    stats = analyze(logs)
    for line in format_report(stats):
        print(line)
    print("Most active:", ", ".join(most_active(stats)))


if __name__ == "__main__":
    main()

