from collections import deque

Row = list[int]
Coord = tuple[int, int]
Grid = list[Row]
Step = tuple[Coord, int]
Pair = tuple[Coord, Coord]


def parse_grid(lines: list[str]) -> Grid:
    """Turn '#'/'.' text rows into a grid of walls (1) and open spaces (0)."""
    grid: Grid = []
    for line in lines:
        row: Row = [1 if char == "#" else 0 for char in line]
        grid.append(row)
    return grid


def is_open(grid: Grid, coord: Coord) -> bool:
    row, col = coord
    if row < 0 or row >= len(grid):
        return False
    if col < 0 or col >= len(grid[row]):
        return False
    return grid[row][col] == 0


def neighbors(grid: Grid, coord: Coord) -> list[Coord]:
    """All open cells directly above, below, left of and right of coord."""
    row, col = coord
    candidates: list[Coord] = [(row - 1, col), (row + 1, col), (row, col - 1), (row, col + 1)]
    return [cell for cell in candidates if is_open(grid, cell)]


def solve(grid: Grid, start: Coord, end: Coord) -> int:
    if not is_open(grid, start) or not is_open(grid, end):
        return -1
    if start == end:
        return 0
    visited = {start}
    queue: deque[Step] = deque([(start, 0)])
    while queue:
        coord, distance = queue.popleft()
        for cell in neighbors(grid, coord):
            if cell == end:
                return distance + 1
            if cell not in visited:
                visited.add(cell)
                queue.append((cell, distance + 1))
    return -1


def summarize(
    results: dict[str, int],
) -> list[str]:
    report: list[str] = []
    for name in sorted(results):
        distance = results[name]
        outcome = f"{distance} steps" if distance >= 0 else "no path"
        report.append(f"{name}: {outcome}")
    return report


def main() -> None:
    mazes: dict[str, Grid] = {
        "open": parse_grid(["...", "...", "..."]),
