"""Audit library checkouts and report overdue books per patron."""

Record = tuple[str, str, int, int]
Titles = list[str]
Report = dict[str, Titles]

DAILY_FINE_CENTS = 25


def parse_records(
    rows: list[str],
) -> list[Record]:
    """Turn 'patron|title|checkout_day|duration' rows into records."""
    records: list[Record] = []
    for row in rows:
        fields: list[str] = [field.strip() for field in row.split("|")]
        if len(fields) != 4:
            raise ValueError(f"malformed record: {row!r}")
        name, title, checkout_day, duration = fields
        records.append((name, title, int(checkout_day), int(duration)))
    return records


def is_overdue(record: Record, today: int) -> bool:
    """A book is overdue when its due day falls strictly before today."""
    _, _, checkout_day, duration = record
    return checkout_day + duration < today


def days_overdue(record: Record, today: int) -> int:
    if not is_overdue(record, today):
        return 0
    _, _, checkout_day, duration = record
    return today - (checkout_day + duration)


def audit(records: list[Record], today: int) -> Report:
    """Map each patron with overdue books to the titles they still hold."""
    report: Report = {}
    for record in records:
        if is_overdue(record, today):
            name, title = record[0], record[1]
            titles: list[str] = report.setdefault(name, [])
            titles.append(title)
    return report


def overdue_days_by_patron(
    records: list[Record],
    today: int,
) -> dict[str, int]:
    totals: dict[str, int] = {}
    for record in records:
        late = days_overdue(record, today)
        if late:
            totals[record[0]] = totals.get(record[0], 0) + late
    return totals


def format_report(
    report: Report,
    late_days: dict[str, int],
) -> list[str]:
    lines: list[str] = []
    for name in sorted(report):
        titles = ", ".join(sorted(report[name]))
        fine = late_days[name] * DAILY_FINE_CENTS
        lines.append(f"{name}: {titles} ({late_days[name]} day(s) late, {fine} cents)")
    return lines


def main() -> None:
    rows: list[str] = [
        "Alice|Dune|10|5",
        "Alice|Emma|12|10",
        "Bob|Ulysses|1|7",
        "Carol|Hamlet|14|14",
    ]
    records = parse_records(rows)
    today = 16
    report = audit(records, today)
    for line in format_report(report, overdue_days_by_patron(records, today)):
        print(line)


if __name__ == "__main__":
    main()

