STEPS_PER_KM = 2000
GOAL = 10000

Activity = tuple[str, int]


def to_kilometers(steps: int) -> float:
    """Convert a raw step count into kilometers."""
    return steps / STEPS_PER_KM


def successful_days(
    activities: list[Activity],
) -> list[str]:
    """Return the dates whose step count exceeded the daily goal."""
    return [date for date, steps in activities if steps > GOAL]


def longest_streak(activities: list[Activity]) -> int:
    """Length of the longest run of consecutive goal-beating entries."""
    best = 0
    current = 0
    for _, steps in activities:
        if steps > GOAL:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best


def total_distance(activities: list[Activity]) -> float:
    return sum(to_kilometers(steps) for _, steps in activities)


def steps_by_date(
    activities: list[Activity],
) -> dict[str, int]:
    """Merge repeated entries for the same date into a single total."""
    totals: dict[str, int] = {}
    for date, steps in activities:
        totals[date] = totals.get(date, 0) + steps
    return totals


def normalize(
    activities: list[Activity],
) -> list[Activity]:
    """Validate the raw records and sort them chronologically per date."""
    merged = steps_by_date(activities)
    for date, steps in merged.items():
        if steps < 0:
            raise ValueError(f"negative step count for {date}: {steps}")
    return sorted(merged.items())


def track(activities):
    records = normalize(activities)
    return (total_distance(records), longest_streak(records), successful_days(records))


def format_report(distance: float, streak: int, achieved: list[str]) -> str:
    lines = [
        f"Total distance: {distance:.1f} km",
        f"Longest streak: {streak} day(s)",
        f"Successful days: {', '.join(achieved) if achieved else 'none'}",
    ]
    return "\n".join(lines)


def main() -> None:
    log: list[Activity] = [
        ("2024-05-01", 12000),
        ("2024-05-02", 5000),
        ("2024-05-03", 11500),
        ("2024-05-04", 10400),
        ("2024-05-04", 600),
        ("2024-05-05", 9000),
    ]
    distance, streak, achieved = track(log)
    print(format_report(distance, streak, achieved))

    daily = steps_by_date(log)
    for date in sorted(daily):
        print(f"{date}: {daily[date]} steps -> {to_kilometers(daily[date]):.2f} km")


if __name__ == "__main__":
    main()

