from __future__ import annotations

WINDOW = 7

WeekStats = tuple[float, float, float]
WeekTable = dict[int, WeekStats]
Summary = tuple[WeekTable, float]


def _validate(values: list[float]) -> None:
    if len(values) < WINDOW:
        raise ValueError(f"need at least {WINDOW} daily readings, got {len(values)}")
    for day, value in enumerate(values):
        if not isinstance(value, (int, float)):
            raise TypeError(f"reading for day {day} is not numeric: {value!r}")


def week_metrics(week: list[float]) -> WeekStats:
    if len(week) != WINDOW:
        raise ValueError(f"a week must hold exactly {WINDOW} readings, got {len(week)}")
    readings = [float(value) for value in week]
    return sum(readings) / WINDOW, max(readings), min(readings)


def summarize(temperatures: list[float]) -> Summary:
    _validate(temperatures)
    table: WeekTable = {}
    for start in range(len(temperatures) - WINDOW + 1):
        window: list[float] = [float(value) for value in temperatures[start:start + WINDOW]]
        table[start] = week_metrics(window)
    overall_max = max(float(value) for value in temperatures)
    return table, overall_max


def spread_counts(table: WeekTable) -> dict[str, int]:
    counts = {"stable": 0, "mild": 0, "volatile": 0}
    for _, maximum, minimum in table.values():
        spread = maximum - minimum
        if spread < 5.0:
            counts["stable"] += 1
        elif spread < 10.0:
            counts["mild"] += 1
        else:
            counts["volatile"] += 1
    return counts


def hottest_weeks(table: WeekTable) -> list[int]:
    peak = max(maximum for _, maximum, _ in table.values())
    return [start for start, stats in sorted(table.items()) if stats[1] == peak]


def format_report(summary: Summary) -> list[str]:
    table, overall_max = summary
    lines: list[str] = [f"weeks analysed: {len(table)}", f"overall maximum: {overall_max:.1f}"]
    for start, (average, maximum, minimum) in sorted(table.items()):
        lines.append(f"day {start:>2}: avg={average:.2f} max={maximum:.1f} min={minimum:.1f}")
    for label, count in spread_counts(table).items():
        lines.append(f"{label} weeks: {count}")
    peaks: list[int] = hottest_weeks(table)
    lines.append("hottest window starts: " + ", ".join(str(start) for start in peaks))
    return lines


def main() -> None:
    readings: list[float] = [
        12.5, 14.0, 13.2, 16.8, 19.4, 21.0, 18.6,
        17.9, 22.3, 24.1, 25.0, 23.7, 20.2, 18.0,
    ]
    for line in format_report(summarize(readings)):
        print(line)

    flat: list[float] = [20.0] * WINDOW
    print(summarize(flat))


if __name__ == "__main__":
    main()

