from typing import Iterable

Song = tuple[str, str, int]
Duration = tuple[int, int]
TitleList = list[str]
Playlist = tuple[TitleList, Duration]
Organized = dict[str, Playlist]


def split_duration(total_seconds: int) -> Duration:
    """Convert a number of seconds into whole minutes and leftover seconds."""
    if total_seconds < 0:
        raise ValueError("duration cannot be negative")
    return total_seconds // 60, total_seconds % 60


def genre_order(songs: Iterable[Song]) -> list[str]:
    """Genres in the order they first appear, without duplicates."""
    order: list[str] = []
    for _title, genre, _duration in songs:
        if genre not in order:
            order.append(genre)
    return order


def titles_for(songs: Iterable[Song], genre: str) -> list[str]:
    return [title for title, song_genre, _duration in songs if song_genre == genre]


def seconds_for(songs: Iterable[Song], genre: str) -> int:
    return sum(duration for _title, song_genre, duration in songs if song_genre == genre)


def organize(songs: list[Song]) -> Organized:
    """Map every genre to its song titles and its total playing time."""
    playlists: Organized = {}
    for genre in genre_order(songs):
        titles = titles_for(songs, genre)
        playlists[genre] = (titles, split_duration(seconds_for(songs, genre)))
    return playlists


def genre_second_totals(playlists: Organized) -> dict[str, int]:
    """Flatten each (minutes, seconds) pair back into plain seconds."""
    totals: dict[str, int] = {}
    for genre, (_titles, (minutes, seconds)) in playlists.items():
        totals[genre] = minutes * 60 + seconds
    return totals


def format_report(playlists: Organized) -> list[str]:
    totals = genre_second_totals(playlists)
    lines: list[str] = []
    for genre in sorted(totals, key=lambda name: (-totals[name], name)):
        titles, (minutes, seconds) = playlists[genre]
        lines.append(f"{genre}: {', '.join(titles)} [{minutes}m{seconds:02d}s]")
    return lines


def longest_genre(totals: dict[str, int]) -> str:
    return max(totals, key=lambda name: (totals[name], name))


def main() -> None:
    songs: list[Song] = [
        ("Thunder Road", "rock", 130),
        ("Blue in Green", "jazz", 327),
        ("Paranoid", "rock", 172),
        ("So What", "jazz", 545),
        ("Clair de Lune", "classical", 300),
    ]
    playlists = organize(songs)
    for line in format_report(playlists):
        print(line)
    totals = genre_second_totals(playlists)
    top = longest_genre(totals)
    top_minutes, top_seconds = split_duration(totals[top])
    print(f"Longest playlist: {top} ({top_minutes} min {top_seconds} s)")


if __name__ == "__main__":
    main()

