Match = tuple[int, str, str, str]
Standing = tuple[str, int]
Rounds = list[int]


def round_points(round_number: int) -> int:
    """Return the points awarded for winning a match in the given round."""
    if round_number < 1:
        raise ValueError(f"round number must be >= 1, got {round_number}")
    return 10 * 2 ** (round_number - 1)


def validate_matches(matches: list[Match]) -> None:
    """Ensure every match names a winner that actually played in it."""
    for round_number, team_one, team_two, winner in matches:
        if winner not in (team_one, team_two):
            raise ValueError(
                f"round {round_number}: winner {winner!r} did not play "
                f"{team_one!r} vs {team_two!r}"
            )


def tally_wins(
    matches: list[Match],
) -> dict[str, Rounds]:
    """Map each winning team to the rounds it won."""
    wins: dict[str, Rounds] = {}
    for round_number, _team_one, _team_two, winner in matches:
        wins.setdefault(winner, []).append(round_number)
    return wins


def team_score(rounds_won: list[int]) -> int:
    return sum(round_points(round_number) for round_number in rounds_won)


def score(
    matches: list[Match],
) -> list[Standing]:
    """Total the tournament points per team, best score first."""
    validate_matches(matches)
    wins = tally_wins(matches)
    totals: list[Standing] = [
        (team, team_score(rounds_won)) for team, rounds_won in wins.items()
    ]
    totals.sort(key=lambda entry: (-entry[1], entry[0]))
    return totals


def all_teams(
    matches: list[Match],
) -> list[str]:
    """Every team that appeared in the bracket, in alphabetical order."""
    names = set()
    for _round_number, team_one, team_two, _winner in matches:
        names.add(team_one)
        names.add(team_two)
    return sorted(names)


def full_standings(
    matches: list[Match],
) -> list[Standing]:
    """Standings including teams that never won a match."""
    scored: dict[str, int] = dict(score(matches))
    standings = [(team, scored.get(team, 0)) for team in all_teams(matches)]
    standings.sort(key=lambda entry: (-entry[1], entry[0]))
    return standings


def format_standings(standings: list[Standing]) -> str:
    width = max((len(team) for team, _points in standings), default=4)
    lines: list[str] = ["{:<{w}}  POINTS".format("TEAM", w=width)]
    for team, points in standings:
        lines.append("{:<{w}}  {:>6}".format(team, points, w=width))
    return "\n".join(lines)


def main() -> None:
    bracket: list[Match] = [
        (1, "Falcons", "Otters", "Falcons"),
        (1, "Bears", "Wolves", "Wolves"),
        (1, "Sharks", "Eagles", "Sharks"),
        (1, "Lions", "Hawks", "Lions"),
        (2, "Falcons", "Wolves", "Falcons"),
        (2, "Sharks", "Lions", "Lions"),
        (3, "Falcons", "Lions", "Lions"),
    ]
    print(format_standings(full_standings(bracket)))
    champion, points = score(bracket)[0]
    print(f"\nChampion: {champion} with {points} points")


