Property = tuple[str, int, int]
PropertyList = list[Property]
Totals = tuple[int, int]


def _validate(properties: PropertyList) -> None:
    for name, sqft, price in properties:
        if not name:
            raise ValueError("every property needs a neighborhood name")
        if sqft <= 0:
            raise ValueError(f"square footage must be positive, got {sqft}")
        if price < 0:
            raise ValueError(f"sale price cannot be negative, got {price}")


def neighborhood_totals(properties: PropertyList) -> dict[str, Totals]:
    """Sum square footage and sale price of the sold properties per neighborhood."""
    totals: dict[str, Totals] = {}
    for name, sqft, price in properties:
        if price > 0:
            area, money = totals.get(name, (0, 0))
            totals[name] = (area + sqft, money + price)
    return totals


def average_price_per_sqft(properties: PropertyList) -> dict[str, float]:
    rates: dict[str, float] = {}
    for name, pair in neighborhood_totals(properties).items():
        area, money = pair
        rates[name] = money / area
    return rates


def unsold_counts(properties: PropertyList) -> dict[str, int]:
    counts: dict[str, int] = {}
    for name, _, price in properties:
        if price == 0:
            counts[name] = counts.get(name, 0) + 1
    return counts


def appraise(properties: PropertyList) -> list[float]:
    _validate(properties)
    rates = average_price_per_sqft(properties)
    values: list[float] = []
    for name, sqft, price in properties:
        if price == 0:
            if name not in rates:
                raise ValueError(f"no sold comparables in neighborhood {name!r}")
            values.append(sqft * rates[name])
    return values


def format_report(
    properties: PropertyList,
    values: list[float],
) -> list[str]:
    unsold = [(name, sqft) for name, sqft, price in properties if price == 0]
    lines: list[str] = []
    for (name, sqft), value in zip(unsold, values):
        lines.append(f"{name:<12} {sqft:>6} sqft -> {value:>12,.2f}")
    counts = unsold_counts(properties)
    for name in sorted(counts):
        lines.append(f"{name}: {counts[name]} appraised")
    lines.append(f"total unsold area: {sum(s for _, s in unsold)} sqft")
    return lines


def main() -> None:
    listings: PropertyList = [
        ("Riverside", 100, 1000),
        ("Riverside", 50, 0),
        ("Oakhill", 2000, 500000),
        ("Oakhill", 1800, 430000),
        ("Oakhill", 1500, 0),
        ("Riverside", 120, 1300),
    ]
    rates = average_price_per_sqft(listings)
    for name in sorted(rates):
        print(f"{name:<12} {rates[name]:.2f} per sqft")
    for line in format_report(listings, appraise(listings)):
        print(line)


if __name__ == "__main__":
    main()

