Expense = tuple[str, str, float]
Charge = tuple[str, float]
ChargeList = list[Charge]
Descriptions = list[str]
AuditRow = tuple[float, bool, Descriptions]


def group_expenses(
    expenses: list[Expense],
) -> dict[str, ChargeList]:
    """Group raw expense records by department, keeping description and cost."""
    grouped: dict[str, ChargeList] = {}
    for department, description, cost in expenses:
        grouped.setdefault(department, []).append((description, cost))
    return grouped


def department_totals(
    grouped: dict[str, ChargeList],
) -> dict[str, float]:
    """Sum the charges of every department, rounded to cents."""
    totals: dict[str, float] = {}
    for department, charges in grouped.items():
        totals[department] = round(sum(cost for _, cost in charges), 2)
    return totals


def audit(
    budgets: dict[str, float],
    expenses: list[Expense],
) -> dict[str, AuditRow]:
    """Compare spending against budgets for every known department."""
    grouped = group_expenses(expenses)
    totals = department_totals(grouped)
    result: dict[str, AuditRow] = {}
    for department in sorted(set(budgets) | set(grouped)):
        charges: ChargeList = grouped.get(department, [])
        descriptions: list[str] = [description for description, _ in charges]
        total = totals.get(department, 0.0)
        limit = budgets.get(department, 0.0)
        result[department] = (total, total > limit, descriptions)
    return result


def balances(
    budgets: dict[str, float],
    result: dict[str, AuditRow],
) -> dict[str, float]:
    """Remaining budget per department; negative values mean an overage."""
    remaining: dict[str, float] = {}
    for department, (total, _, _) in result.items():
        remaining[department] = round(budgets.get(department, 0.0) - total, 2)
    return remaining


def format_report(
    budgets: dict[str, float],
    result: dict[str, AuditRow],
) -> list[str]:
    remaining = balances(budgets, result)
    lines: list[str] = []
    for department, (total, exceeded, descriptions) in result.items():
        left = remaining[department]
        status = f"OVER by {abs(left):.2f}" if exceeded else f"{left:.2f} left"
        detail = ", ".join(descriptions) if descriptions else "no expenses"
        lines.append(f"{department}: spent {total:.2f} ({status}) -> {detail}")
    return lines


def main() -> None:
    budgets: dict[str, float] = {"office": 100.0, "travel": 250.0, "legal": 500.0}
    expenses: list[Expense] = [
        ("office", "paper", 50.0),
        ("office", "printer ink", 62.5),
        ("travel", "train tickets", 180.0),
        ("marketing", "flyers", 40.0),
    ]
    result = audit(budgets, expenses)
    for line in format_report(budgets, result):
        print(line)


if __name__ == "__main__":
    main()

