from __future__ import annotations
from typing import Dict, List, Tuple

Item = Tuple[str, int]
Bin = List[Item]


def validate_items(items: List[Item], capacity: int) -> None:
    """Reject inputs that cannot be packed at all."""
    if capacity <= 0:
        raise ValueError("capacity must be a positive integer")
    for name, weight in items:
        if weight <= 0:
            raise ValueError(f"item {name!r} must have a positive weight")
        if weight > capacity:
            raise ValueError(f"item {name!r} weighs {weight}, more than capacity {capacity}")


def bin_weight(bin_items: Bin) -> int:
    """Total weight currently stored in one bin."""
    total = 0
    for _name, weight in bin_items:
        total += weight
    return total


def pack(
    items: List[Item],
    capacity: int,
) -> List[Bin]:
    """First-fit packing: each item goes into the first bin that still fits it."""
    validate_items(items, capacity)
    bins: List[Bin] = []
    for item in items:
        for existing in bins:
            if bin_weight(existing) + item[1] <= capacity:
                existing.append(item)
                break
        else:
            bins.append([item])
    return bins


def free_space(
    bins: List[Bin],
    capacity: int,
) -> List[int]:
    """Remaining capacity of every bin, in packing order."""
    return [capacity - bin_weight(b) for b in bins]


def weight_index(
