RawEvent = tuple[str, str, int]
Event = tuple[str, int]
EventLog = list[Event]
Durations = list[int]
ShiftReport = dict[str, Durations]

VALID_ACTIONS = ("in", "out")


def validate(events: list[RawEvent]) -> None:
    """Reject events whose action is unknown or whose timestamp is negative."""
    for name, action, stamp in events:
        if action not in VALID_ACTIONS:
            raise ValueError(f"unknown action {action!r} for {name}")
        if stamp < 0:
            raise ValueError(f"negative timestamp {stamp} for {name}")


def group_by_employee(
    events: list[RawEvent],
) -> dict[str, EventLog]:
    """Bucket raw events per employee and sort each bucket by timestamp."""
    grouped: dict[str, EventLog] = {}
    for name, action, stamp in events:
        grouped.setdefault(name, []).append((action, stamp))
    for log in grouped.values():
        log.sort(key=lambda entry: entry[1])
    return grouped


def pair_shifts(log: EventLog) -> list[int]:
    """Pair each clock in with the next clock out and measure the gap."""
    durations: list[int] = []
    open_at: int | None = None
    for action, stamp in log:
        if action == "in":
            open_at = stamp
        elif open_at is not None:
            durations.append(stamp - open_at)
            open_at = None
    return durations


def verify(events: list[RawEvent]) -> ShiftReport:
    validate(events)
    report: ShiftReport = {}
    for name, log in group_by_employee(events).items():
        report[name] = pair_shifts(log)
    return report


def total_minutes(report: ShiftReport) -> dict[str, int]:
    return {name: sum(durations) for name, durations in report.items()}


def format_report(report: ShiftReport) -> list[str]:
    lines: list[str] = []
    for name in sorted(report):
        shifts = ", ".join(str(minutes) for minutes in report[name])
        lines.append(f"{name}: [{shifts}]")
    return lines


def main() -> None:
    raw_events: list[RawEvent] = [
        ("alice", "in", 90),
        ("alice", "out", 120),
        ("bob", "in", 480),
        ("alice", "in", 200),
        ("bob", "out", 720),
        ("alice", "out", 260),
        ("carol", "in", 60),
    ]
    report = verify(raw_events)
    for line in format_report(report):
        print(line)
    totals: dict[str, int] = total_minutes(report)
    for name in sorted(totals):
        print(f"{name} worked {totals[name]} minutes across {len(report[name])} shift(s)")


if __name__ == "__main__":
    main()

