"""Group words into sets of anagrams."""

from __future__ import annotations

WordList = list[str]
Index = dict[str, WordList]
AnagramGroups = list[WordList]


def signature(word: str) -> str:
    """Return the sorted-letter signature of a word, ignoring case."""
    return "".join(sorted(word.lower()))


def build_index(
    words: list[str],
) -> Index:
    """Map every signature to the original words that produce it."""
    index: Index = {}
    for word in words:
        index.setdefault(signature(word), []).append(word)
    return index


def split_groups(index: Index) -> tuple[AnagramGroups, int]:
    """Keep signatures shared by several words, count the lonely ones."""
    groups: AnagramGroups = []
    discarded = 0
    for _, members in sorted(index.items()):
        if len(members) > 1:
            groups.append(members)
        else:
            discarded += len(members)
    return groups, discarded


def group(
    words: list[str],
) -> tuple[AnagramGroups, int]:
    """Return the anagram groups of *words* and the discarded word count."""
    return split_groups(build_index(words))


def letter_counts(word: str) -> dict[str, int]:
    """Count how often each letter occurs in a word, ignoring case."""
    counts: dict[str, int] = {}
    for char in word.lower():
        counts[char] = counts.get(char, 0) + 1
    return counts


def format_report(
    groups: AnagramGroups,
    discarded: int,
) -> str:
    """Render the groups with the letter profile they all share."""
    lines: list[str] = []
    for members in groups:
        profile = letter_counts(members[0])
        fingerprint = "".join(f"{char}{n}" for char, n in sorted(profile.items()))
        lines.append(f"[{fingerprint}] " + ", ".join(members))
    lines.append(f"discarded words: {discarded}")
    return "\n".join(lines)


def main() -> None:
    words: list[str] = [
        "listen",
        "Silent",
        "apple",
        "enlist",
        "stone",
        "tones",
        "notes",
        "banana",
    ]
    groups, discarded = group(words)
    print(format_report(groups, discarded))


if __name__ == "__main__":
    main()

