SummaryMap = dict[str, MovieStat]
ReviewerCounts = dict[str, int]
Reviewers = list[str]
Result = tuple[SummaryMap, Reviewers]


def average_score(scores: list[int]) -> float:
    """Arithmetic mean of a non-empty list of scores."""
    if not scores:
        raise ValueError("cannot average an empty list of scores")
    return sum(scores) / len(scores)


def validate(reviews: list[Review]) -> None:
    """Reject malformed reviews before any grouping happens."""
    for title, reviewer, score in reviews:
        if not title or not reviewer:
            raise ValueError("movie title and reviewer name must be non-empty")
        if not 1 <= score <= 5:
            raise ValueError(f"score {score} for {title!r} is outside 1..5")


def group_scores(reviews: list[Review]) -> ScoreIndex:
    """Collect every score given to each movie title."""
    grouped: ScoreIndex = {}
    for title, _, score in reviews:
        grouped.setdefault(title, []).append(score)
    return grouped


def count_by_reviewer(reviews: list[Review]) -> ReviewerCounts:
    """Count how many reviews each reviewer wrote."""
    counts: ReviewerCounts = {}
    for _, reviewer, _ in reviews:
        counts[reviewer] = counts.get(reviewer, 0) + 1
    return counts


def movie_stats(grouped: ScoreIndex) -> SummaryMap:
    summary: SummaryMap = {}
    for title, scores in grouped.items():
        stat: MovieStat = (round(average_score(scores), 2), len(scores))
        summary[title] = stat
    return summary


def prolific_reviewers(counts: ReviewerCounts, minimum: int = 3) -> Reviewers:
    return sorted(name for name, total in counts.items() if total > minimum)


def summarize(reviews: list[Review]) -> Result:
    validate(reviews)
    summary = movie_stats(group_scores(reviews))
    return summary, prolific_reviewers(count_by_reviewer(reviews))


def format_report(summary: SummaryMap, top: Reviewers) -> list[str]:
    lines: list[str] = []
    for title, (average, count) in sorted(summary.items()):
        lines.append(f"{title}: {average:.2f} from {count} review(s)")
    lines.append("Top reviewers: " + (", ".join(top) if top else "none"))
    return lines


def main() -> None:
    reviews: list[Review] = [
        ("Arrival", "ana", 4),
        ("Arrival", "ben", 5),
        ("Heat", "ana", 3),
        ("Heat", "cleo", 5),
        ("Solaris", "ana", 5),
        ("Solaris", "ben", 2),
        ("Whiplash", "ana", 4),
        ("Whiplash", "cleo", 4),
    ]
    summary, top = summarize(reviews)
    for line in format_report(summary, top):
        print(line)


if __name__ == "__main__":
    main()

