Point = tuple[int, int]
Legs = list[int]


def manhattan(
    start: tuple[int, int],
    end: tuple[int, int],
) -> int:
    """Manhattan (grid) distance between two integer coordinate pairs."""
    return abs(start[0] - end[0]) + abs(start[1] - end[1])


def missing_locations(
    locations: dict[str, Point],
    deliveries: list[str],
) -> list[str]:
    """Names in the delivery sequence that have no known coordinates."""
    unknown: list[str] = []
    for name in deliveries:
        if name not in locations and name not in unknown:
            unknown.append(name)
    return unknown


def route(
    locations: dict[str, Point],
    deliveries: list[str],
) -> tuple[int, Legs]:
    """Total distance and per-leg distances for the delivery sequence."""
    unknown = missing_locations(locations, deliveries)
    if unknown:
        raise KeyError("unknown locations: " + ", ".join(unknown))
    legs: list[int] = []
    for start, end in zip(deliveries, deliveries[1:]):
        legs.append(manhattan(locations[start], locations[end]))
    return sum(legs), legs


def distance_leaving_each_stop(
    deliveries: list[str],
    legs: list[int],
) -> dict[str, int]:
    """How far the driver travels away from each stop, summed per stop."""
    totals: dict[str, int] = {}
    for name, distance in zip(deliveries, legs):
        totals[name] = totals.get(name, 0) + distance
    return totals


def format_report(
    deliveries: list[str],
    legs: list[int],
    total: int,
) -> list[str]:
    lines: list[str] = ["Start: " + deliveries[0]]
    for index, distance in enumerate(legs):
        lines.append(
            f"{deliveries[index]} -> {deliveries[index + 1]}: {distance}"
        )
    lines.append(f"Total: {total}")
    return lines


def main() -> None:
    locations: dict[str, Point] = {
        "depot": (0, 0),
        "north": (0, 5),
        "market": (3, 5),
        "harbour": (3, 0),
    }
    deliveries: list[str] = ["depot", "north", "market", "harbour", "depot"]
    total, legs = route(locations, deliveries)
    for line in format_report(deliveries, legs, total):
        print(line)
    outgoing: dict[str, int] = distance_leaving_each_stop(deliveries, legs)
    for name in sorted(outgoing):
        print(f"  leaving {name}: {outgoing[name]}")


if __name__ == "__main__":
    main()

