def dish_combinations(dishes: Menu) -> Iterator[Combo]:
    """Yield every non-empty combination of dishes, shortest menus first."""
    for size in range(1, len(dishes) + 1):
        for combo in combinations(dishes, size):
            yield combo


def combination_calories(combo: Combo, recipes: Recipes) -> int:
    """Total calories of a menu."""
    return sum(recipes[dish] for dish in combo)


def find_menu(recipes: Recipes, target: int) -> Menu | None:
    """Return the first menu matching the target exactly, or None."""
    affordable: Menu = [d for d, c in recipes.items() if c <= target]
    for combo in dish_combinations(affordable):
        if combination_calories(combo, recipes) == target:
            return list(combo)
    return None


