        "salad": 200,
        "omelette": 500,
        "soup": 250,
        "steak": 700,
    }
    targets: Recipes = {"Ana": 500, "Bo": 750, "Cy": 123, "Dee": 1200}
    menus, unmet = plan(recipes, targets)
    for line in format_report(menus, unmet, recipes):
        print(line)


