Assignment = list[int]
Timetable = dict[str, Assignment]
Capacities = dict[str, int]


def validate_lengths(
    values: list[int],
    label: str,
) -> Assignment:
    """Return the values, ensuring every duration is a positive whole number."""
    for value in values:
        if not isinstance(value, int) or value <= 0:
            raise ValueError(f"{label} must contain positive integer minutes, got {value!r}")
    return list(values)


def sort_by_length(
    talks: list[int],
) -> Assignment:
    """Longest presentation first, so big talks claim room time before small ones."""
    return sorted(talks, reverse=True)


def label_rooms(
    rooms: list[int],
) -> Capacities:
    """Give every room capacity a stable identifier."""
    labelled: Capacities = {}
    for index, capacity in enumerate(rooms, start=1):
        labelled[f"Room-{index}"] = capacity
    return labelled


def pack_room(
    lengths: list[int],
    capacity: int,
) -> Assignment:
    """Greedily take presentations from `lengths` while free time remains."""
    assigned: Assignment = []
    remaining = capacity
    for length in lengths:
        if length <= remaining:
            assigned.append(length)
            remaining -= length
    return assigned


def schedule(
    talks: list[int],
    rooms: list[int],
) -> tuple[Timetable, Assignment]:
    """Assign presentations to rooms; return the timetable and the leftovers."""
    capacities = label_rooms(validate_lengths(rooms, "rooms"))
    pending = sort_by_length(validate_lengths(talks, "talks"))
    timetable: Timetable = {}
    for room_id, capacity in capacities.items():
        chosen = pack_room(pending, capacity)
        timetable[room_id] = chosen
        for length in chosen:
            pending.remove(length)
    return timetable, pending


def usage_report(
    capacities: Capacities,
    timetable: Timetable,
) -> Capacities:
    """Minutes of idle time left in each room after packing."""
    idle: Capacities = {}
    for room_id, capacity in capacities.items():
        idle[room_id] = capacity - sum(timetable[room_id])
    return idle


def format_report(
    timetable: Timetable,
    idle: Capacities,
) -> list[str]:
    lines: list[str] = []
    for room_id, assigned in timetable.items():
        slots = ", ".join(f"{length}m" for length in assigned) or "empty"
        lines.append(f"{room_id}: {slots} (idle {idle[room_id]}m)")
    return lines


def main() -> None:
    talks = [60, 25, 45, 90, 30, 15, 50, 20]
    rooms = [120, 100, 45]
    timetable, unscheduled = schedule(talks, rooms)
    idle = usage_report(label_rooms(rooms), timetable)
    for line in format_report(timetable, idle):
        print(line)
    print("Unscheduled:", ", ".join(f"{length}m" for length in unscheduled) or "none")


if __name__ == "__main__":
    main()

