Record = tuple[str, int]
Ledger = dict[str, int]
Members = list[str]
Groups = dict[str, Members]


def parse_records(
    rows: list[str],
) -> list[Record]:
    """Turn 'Name,12.50' text rows into (name, amount-in-cents) pairs."""
    records: list[Record] = []
    for row in rows:
        fields = row.split(",")
        if len(fields) != 2:
            raise ValueError(f"malformed record: {row!r}")
        name = fields[0].strip()
        if not name:
            raise ValueError(f"missing shopper name: {row!r}")
        records.append((name, round(float(fields[1]) * 100)))
    return records


def sum_by_shopper(purchases: list[Record]) -> Ledger:
    """Add up every transaction belonging to the same shopper."""
    totals: Ledger = {}
    for name, amount in purchases:
        totals[name] = totals.get(name, 0) + amount
    return totals


def highest_tier(total: int, thresholds: Ledger) -> str | None:
    """Return the best tier whose minimum spend is met, or None."""
    ranked = sorted(thresholds.items(), key=lambda item: item[1], reverse=True)
    for name, minimum in ranked:
        if total >= minimum:
            return name
    return None


def tier(
    purchases: list[Record],
    thresholds: Ledger,
) -> tuple[Groups, Members]:
    """Group shoppers by the highest tier they reached."""
    totals = sum_by_shopper(purchases)
    groups: Groups = {name: [] for name in thresholds}
    unranked: Members = []
    for shopper in sorted(totals):
        best = highest_tier(totals[shopper], thresholds)
        if best is None:
            unranked.append(shopper)
        else:
            groups[best].append(shopper)
    return groups, unranked


def money(cents: int) -> str:
    return f"${cents / 100:,.2f}"


def format_report(groups: Groups, unranked: Members, totals: Ledger) -> list[str]:
    lines: list[str] = []
    for tier_name, members in groups.items():
        spent = [f"{who} ({money(totals[who])})" for who in members]
        lines.append(f"{tier_name}: " + (", ".join(spent) if spent else "-"))
    lines.append("No tier: " + (", ".join(unranked) if unranked else "-"))
    return lines


def main() -> None:
    rows: list[str] = [
        "Ada,120.00",
        "Grace,45.50",
        "Ada,89.99",
        "Linus,9.99",
        "Grace,10.00",
        "Margaret,300.00",
    ]
    thresholds: Ledger = {"Bronze": 5000, "Silver": 15000, "Gold": 25000}
    records = parse_records(rows)
    groups, unranked = tier(records, thresholds)
    for line in format_report(groups, unranked, sum_by_shopper(records)):
        print(line)


if __name__ == "__main__":
    main()

