from __future__ import annotations

Flight = tuple[str, str]
CityList = list[str]
RouteMap = dict[str, CityList]
ItineraryList = list[CityList]
Counts = dict[str, int]
Rank = tuple[str, int]

MAX_STOPS = 2


def build_route_map(flights: list[Flight]) -> RouteMap:
    """Group the flight pairs by departure city."""
    route_map: RouteMap = {}
    for departure, arrival in flights:
        route_map.setdefault(departure, []).append(arrival)
    return route_map


def explore(
    route_map: RouteMap,
    current: str,
    destination: str,
    stops_left: int,
    trail: CityList,
) -> ItineraryList:
    """Collect every itinerary from `current` to `destination` without revisits."""
    found: ItineraryList = []
    for arrival in route_map.get(current, []):
        if arrival in trail:
            continue
        path: CityList = trail + [arrival]
        if arrival == destination:
            found.append(path)
        elif stops_left > 0:
            found.extend(
                explore(route_map, arrival, destination, stops_left - 1, path)
            )
    return found


def count_cities(itineraries: ItineraryList) -> Counts:
    counts: dict[str, int] = {}
    for itinerary in itineraries:
        for city in itinerary:
            counts[city] = counts.get(city, 0) + 1
    return counts


def connect(
    flights: list[Flight],
    origin: str,
    destination: str,
) -> tuple[ItineraryList, Counts]:
    route_map = build_route_map(flights)
    itineraries = explore(route_map, origin, destination, MAX_STOPS, [origin])
    return itineraries, count_cities(itineraries)


def rank_cities(counts: Counts) -> list[Rank]:
    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))


def format_report(itineraries: ItineraryList, counts: Counts) -> list[str]:
    lines: list[str] = []
    for itinerary in itineraries:
        lines.append(" -> ".join(itinerary))
    if not itineraries:
        lines.append("no itinerary found")
    for city, times in rank_cities(counts):
        lines.append(f"{city}: {times}")
    return lines


def main() -> None:
    flights: list[Flight] = [
        ("Paris", "Lyon"),
        ("Paris", "Berlin"),
        ("Lyon", "Rome"),
        ("Berlin", "Rome"),
        ("Rome", "Athens"),
        ("Lyon", "Athens"),
        ("Athens", "Paris"),
    ]
    itineraries, counts = connect(flights, "Paris", "Athens")
    for line in format_report(itineraries, counts):
        print(line)


if __name__ == "__main__":
    main()

