    holdings: Dict[str, int] = {}
    for row in rows:
        name, _, count = row.partition(":")
        holdings[name.strip()] = int(count)
    return holdings


def parse_rates(
    rows: List[str],
) -> Dict[str, float]:
    """Read "TICKER: rate" lines into a payout-per-share mapping."""
    rates: Dict[str, float] = {}
    for row in rows:
        name, _, rate = row.partition(":")
        rates[name.strip()] = float(rate)
    return rates


def payout_for(
    company: str,
    holdings: Dict[str, int],
    rates: Dict[str, float],
) -> float:
    """Multiply the shares held of a single company by its payout rate."""
    return holdings.get(company, 0) * rates.get(company, 0.0)


def paying_companies(
    holdings: Dict[str, int],
    rates: Dict[str, float],
) -> CompanyList:
    """Filter the portfolio down to companies with a non-zero payout rate."""
    return [company for company in holdings if rates.get(company, 0.0) != 0.0]


def project(
    holdings: Dict[str, int],
    rates: Dict[str, float],
) -> Projection:
    """Return projected payouts per company and the non-paying companies."""
    payouts: PayoutMap = {}
    paying = paying_companies(holdings, rates)
    for company in paying:
        payouts[company] = payout_for(company, holdings, rates)
    dividend_free: List[str] = [c for c in holdings if c not in paying]
    return payouts, dividend_free


def portfolio_counts(payouts: PayoutMap, silent: CompanyList) -> Tuple[int, int]:
    """Count how many holdings pay dividends and how many do not."""
    return len(payouts), len(silent)


def format_report(
    payouts: PayoutMap,
    dividend_free: CompanyList,
) -> List[str]:
    """Render a payout table followed by the non-paying holdings."""
    lines: List[str] = []
    for company, amount in sorted(payouts.items(), key=lambda item: -item[1]):
        lines.append(f"{company:<6}{amount:>12.2f}")
    lines.append(f"{'TOTAL':<6}{sum(payouts.values()):>12.2f}")
    if dividend_free:
        lines.append("No dividend: " + ", ".join(sorted(dividend_free)))
    return lines


def main() -> None:
    holding_rows: List[str] = ["AAPL: 120", "KO: 300", "TSLA: 45", "BRK: 10"]
    rate_rows: List[str] = ["AAPL: 0.96", "KO: 1.94", "TSLA: 0.0"]
    holdings = parse_holdings(holding_rows)
    rates = parse_rates(rate_rows)
    payouts, dividend_free = project(holdings, rates)
    paying_count, silent_count = portfolio_counts(payouts, dividend_free)
    for line in format_report(payouts, dividend_free):
        print(line)
    print(f"{paying_count} paying holdings, {silent_count} without dividends")


if __name__ == "__main__":
    main()

