def total_capacity(rooms: DeskCounts) -> int:
    """Total number of desks available across all venues."""
    seats = 0
    for venue, desks in rooms.items():
        if desks < 0:
            raise ValueError(f"venue {venue!r} has a negative desk count")
        seats += desks
    return seats


def fill_venues(students: Roster, rooms: DeskCounts) -> Seating:
    """Fill venues one after another until each reaches its desk limit."""
    assignment: Seating = {}
    cursor = 0
    for venue in sorted(rooms):
        seated = students[cursor:cursor + rooms[venue]]
        assignment[venue] = seated
        cursor += len(seated)
    return assignment


def distribute(students: Roster, rooms: DeskCounts) -> Placement:
    """Seat the test takers and report who could not be placed."""
    capacity = total_capacity(rooms)
    assignment = fill_venues(students, rooms)
