def display(char: str) -> str:
    """Render a character so whitespace stays visible in a report."""
    escapes: dict[str, str] = {
        " ": "<space>",
        "\n": "<newline>",
        "\t": "<tab>",
    }
    return escapes.get(char, char)


def count_characters(text: str) -> dict[str, int]:
    """Iterate over the text and populate the per-character counts."""
    counts: dict[str, int] = {}
    for char in text:
        counts[char] = counts.get(char, 0) + 1
    return counts


def rank_characters(counts: dict[str, int]) -> list[str]:
    """Extract the characters and sort them by descending count."""
    characters: list[str] = list(counts)
    characters.sort(key=lambda char: (-counts[char], char))
    return characters


Breakdown = tuple[
    dict[str, int],
    list[str],
]


def analyze(ciphertext: str) -> Breakdown:
    """Return the character counts and the characters ranked by frequency."""
    if not isinstance(ciphertext, str):
        raise TypeError("analyze() expects a single string of text")
    counts = count_characters(ciphertext)
    return counts, rank_characters(counts)


Leader = tuple[int, str]


def most_common(
    counts: dict[str, int],
    ranking: list[str],
    limit: int,
) -> list[Leader]:
    """Pair the highest-ranked characters with their counts."""
    leaders: list[Leader] = []
    for char in ranking[:limit]:
        leaders.append((counts[char], char))
    return leaders


def format_report(
    counts: dict[str, int],
    ranking: list[str],
) -> list[str]:
    """Build one bar-chart line per character, most frequent first."""
    total = sum(counts.values())
    lines: list[str] = [f"{total} characters, {len(ranking)} distinct"]
    for char in ranking:
        count = counts[char]
        share = 100.0 * count / total
        bar = "#" * count
        lines.append(f"{display(char):>10} {count:4d} {share:5.1f}%  {bar}")
    return lines


def main() -> None:
    message = "Meet me at the old bridge at midnight; bring the blue key."
    counts, ranking = analyze(message)
    for line in format_report(counts, ranking):
        print(line)
    print()
    top: list[Leader] = most_common(counts, ranking, 5)
    for rank, (count, char) in enumerate(top, start=1):
        print(f"#{rank}: {display(char)!r} appears {count} time(s)")


if __name__ == "__main__":
    main()

