from math import isclose

Breakdown = dict[str, float]
BreakdownList = list[Breakdown]
SplitResult = tuple[BreakdownList, Breakdown]
Remainder = tuple[float, str]


def validate_proportions(proportions: dict[str, float]) -> None:
    if not proportions:
        raise ValueError("no workers given")
    negatives: list[str] = [name for name, pct in proportions.items() if pct < 0]
    if negatives:
        raise ValueError(f"negative shares for: {', '.join(sorted(negatives))}")
    if not isclose(sum(proportions.values()), 100.0, abs_tol=1e-9):
        raise ValueError("proportions must add up to 100")


def to_cents(amount: float) -> int:
    if amount < 0:
        raise ValueError(f"invoice amount cannot be negative: {amount}")
    return round(amount * 100)


def allocate_cents(
    total_cents: int,
    proportions: dict[str, float],
) -> dict[str, int]:
    cuts: dict[str, int] = {}
    remainders: list[Remainder] = []
    for name, pct in proportions.items():
        scaled = total_cents * pct
        cuts[name] = int(scaled // 100)
        remainders.append((scaled % 100, name))
    remainders.sort(key=lambda item: (-item[0], item[1]))
    leftover = total_cents - sum(cuts.values())
    for index in range(leftover):
        cuts[remainders[index % len(remainders)][1]] += 1
    return cuts


def shares_for(amount: float, proportions: dict[str, float]) -> Breakdown:
    cuts: dict[str, int] = allocate_cents(to_cents(amount), proportions)
    return {name: cents / 100 for name, cents in cuts.items()}


def add_to_totals(totals: dict[str, float], shares: Breakdown) -> None:
    for name, cut in shares.items():
        totals[name] = round(totals.get(name, 0.0) + cut, 2)


def split(
    invoices: list[float],
    proportions: dict[str, float],
) -> SplitResult:
    validate_proportions(proportions)
    breakdowns: BreakdownList = []
    totals: dict[str, float] = {name: 0.0 for name in proportions}
    for amount in invoices:
        shares = shares_for(amount, proportions)
        breakdowns.append(shares)
        add_to_totals(totals, shares)
    return breakdowns, totals


def format_report(
    breakdowns: BreakdownList,
    totals: dict[str, float],
) -> list[str]:
    lines: list[str] = []
    for index, shares in enumerate(breakdowns, start=1):
        parts = [f"{name} {cut:.2f}" for name, cut in sorted(shares.items())]
        lines.append(f"invoice {index}: " + ", ".join(parts))
    for name, paid in sorted(totals.items()):
        lines.append(f"total {name}: {paid:.2f}")
    return lines


def main() -> None:
    invoices: list[float] = [1000.00, 333.33, 47.05]
    proportions = {"ana": 50.0, "bruno": 33.5, "cleo": 16.5}
    breakdowns, totals = split(invoices, proportions)
    for line in format_report(breakdowns, totals):
        print(line)
    print(f"grand total: {sum(totals.values()):.2f} of {sum(invoices):.2f}")


if __name__ == "__main__":
    main()

