"""Identify inventory items that are running low against required minimums."""

Counts = dict[str, int]
LowStock = list[str]
Report = tuple[LowStock, Counts]
OrderLine = tuple[str, int]
Order = list[OrderLine]


def validate_counts(counts: dict[str, int], label: str) -> None:
    """Reject negative or non-integer stock figures before comparing them."""
    for product, amount in counts.items():
        if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
            raise ValueError(f"{label}: invalid count for {product!r}: {amount!r}")


def is_below_minimum(
    product: str,
    inventory: dict[str, int],
    minimums: Counts,
) -> bool:
    """True when the stock held for `product` fails to reach its minimum."""
    return inventory.get(product, 0) < minimums[product]


def deficit(
    product: str,
    inventory: Counts,
    minimums: dict[str, int],
) -> int:
    """Units required to bring `product` back up to its minimum (0 if fine)."""
    shortfall = minimums[product] - inventory.get(product, 0)
    return max(shortfall, 0)


def prioritize(inventory: Counts, minimums: Counts) -> Report:
    """Return the low products and how many units each one needs."""
    validate_counts(inventory, "inventory")
    validate_counts(minimums, "minimums")
    low: list[str] = []
    needed: dict[str, int] = {}
    for product in sorted(minimums):
        if is_below_minimum(product, inventory, minimums):
            low.append(product)
            needed[product] = deficit(product, inventory, minimums)
    return low, needed


def restock_order(needed: dict[str, int]) -> Order:
    """Largest shortfalls first, ties broken alphabetically."""
    return sorted(needed.items(), key=lambda item: (-item[1], item[0]))


def format_report(order: Order) -> list[str]:
    width = max((len(product) for product, _ in order), default=0)
    return [f"{product:<{width}}  needs {amount:>3} units" for product, amount in order]


def main() -> None:
    inventory: dict[str, int] = {
        "bolts": 120,
        "nuts": 18,
        "washers": 0,
        "hinges": 45,
        "screws": 7,
    }
    minimums: Counts = {
        "bolts": 100,
        "nuts": 50,
        "washers": 25,
        "hinges": 40,
        "screws": 60,
    }
    low, needed = prioritize(inventory, minimums)
    print("Low stock products:", ", ".join(low) if low else "none")
    for line in format_report(restock_order(needed)):
        print(" ", line)
    print(f"Total units to order: {sum(needed.values())}")


if __name__ == "__main__":
    main()

