ROOM_PRIORITY: list[str] = ["penthouse", "suite", "deluxe", "double", "standard"]

GuestList = list[str]
Placements = dict[str, GuestList]


def priority_rank(room_type: str) -> int:
    """Lower rank means a more desirable room type."""
    if room_type in ROOM_PRIORITY:
        return ROOM_PRIORITY.index(room_type)
    return len(ROOM_PRIORITY)


def normalize_vacancies(
    available: dict[str, int],
) -> dict[str, int]:
    """Clean up room-type keys and reject impossible vacancy counts."""
    cleaned: dict[str, int] = {}
    for room_type, count in available.items():
        if count < 0:
            raise ValueError(f"negative vacancy count for {room_type!r}")
        key = room_type.strip().lower()
        cleaned[key] = cleaned.get(key, 0) + count
    return cleaned


def has_vacancy(available: dict[str, int]) -> bool:
    """True when at least one unit of any room type is still free."""
    return any(count > 0 for count in available.values())


def best_room(available: dict[str, int]) -> str:
    """Return the most desirable room type that still has a vacant unit."""
    candidates = [room for room, count in available.items() if count > 0]
    return min(candidates, key=priority_rank)


def assign_guest(
    guest: str,
    room_type: str,
    placements: Placements,
    available: dict[str, int],
) -> None:
    """Place one guest into a room type and consume a vacant unit."""
    placements.setdefault(room_type, []).append(guest)
    available[room_type] -= 1


def upgrade(
    reservations: list[str],
    available: dict[str, int],
) -> tuple[Placements, GuestList]:
    """Upgrade as many guests as vacancies allow, best rooms first."""
    vacancies = normalize_vacancies(available)
    placements: Placements = {}
    waitlist: GuestList = []
    for guest in reservations:
        if has_vacancy(vacancies):
            assign_guest(guest, best_room(vacancies), placements, vacancies)
        else:
            waitlist.append(guest)
    return placements, waitlist


def summarize(placements: Placements) -> dict[str, int]:
    """Count how many guests landed in each room type."""
    return {room_type: len(guests) for room_type, guests in placements.items()}


def format_report(
    placements: Placements,
    waitlist: GuestList,
) -> list[str]:
    counts = summarize(placements)
    lines: list[str] = []
    for room_type in sorted(counts, key=priority_rank):
        guests = ", ".join(placements[room_type])
        lines.append(f"{room_type}: {counts[room_type]} upgraded ({guests})")
    if waitlist:
        lines.append("no upgrade available: " + ", ".join(waitlist))
    return lines


def main() -> None:
    requests: list[str] = ["Ana", "Boris", "Chen", "Dalia", "Emre", "Farah"]
    vacant: dict[str, int] = {"Suite": 1, "deluxe": 2, "standard": 1}
    placements, waitlist = upgrade(requests, vacant)
    for line in format_report(placements, waitlist):
        print(line)


if __name__ == "__main__":
    main()

