from bisect import bisect_right


def find_in_sequence(sample: str, motif: str) -> list[int]:
    """Slide over one genetic string and report every start of `motif`."""
    positions: list[int] = []
    start = sample.find(motif)
    while start != -1:
        positions.append(start)
        start = sample.find(motif, start + 1)
    return positions


def sample_offsets(
    samples: list[str],
) -> list[int]:
    """Global coordinate at which each genetic string begins."""
    starts: list[int] = []
    total = 0
    for sample in samples:
        starts.append(total)
        total += len(sample)
    return starts


def collect_positions(
    samples: list[str],
    motif: str,
    starts: list[int],
) -> list[int]:
    """Aggregate the hits of one motif over the whole collection."""
    combined: list[int] = []
    for index, sample in enumerate(samples):
        for local in find_in_sequence(sample, motif):
            combined.append(starts[index] + local)
    return combined


def locate(
    starts: list[int],
    position: int,
) -> tuple[int, int]:
    """Translate a global coordinate back to (sample index, local offset)."""
    index = bisect_right(starts, position) - 1
    return index, position - starts[index]


def normalize(
    sequences: list[str],
) -> list[str]:
    cleaned: list[str] = []
    for sequence in sequences:
        text = sequence.strip().upper()
        if not text:
            raise ValueError("empty sequence in input")
        cleaned.append(text)
    return cleaned


def match(
    samples: list[str],
    motifs: list[str],
):
    genomes = normalize(samples)
    targets = normalize(motifs)
    starts = sample_offsets(genomes)
    index = {}
    unmatched: list[str] = []
    for motif in targets:
        hits: list[int] = collect_positions(genomes, motif, starts)
        index[motif] = hits
        if not hits:
            unmatched.append(motif)
    return index, unmatched


def format_report(
    counts: dict[str, int],
    unmatched: list[str],
) -> str:
    lines = [f"{motif}: {counts[motif]} hit(s)" for motif in sorted(counts)]
    if unmatched:
        lines.append("no matches: " + ", ".join(sorted(unmatched)))
    return "\n".join(lines)


def main() -> None:
    samples: list[str] = ["ACGTACGTGGA", "TTACGTTTGGACG", "GGGCCCAAA"]
    motifs: list[str] = ["ACGT", "GGA", "TTTT"]
    index, unmatched = match(samples, motifs)
    starts = sample_offsets(normalize(samples))
    for motif in sorted(index):
        for position in index[motif]:
            sample_index, offset = locate(starts, position)
            print(f"{motif} -> sample {sample_index}, offset {offset}")
    counts: dict[str, int] = {motif: len(hits) for motif, hits in index.items()}
    print(format_report(counts, unmatched))


if __name__ == "__main__":
    main()

