UNVISITED = 0
ACTIVE = 1
DONE = 2
BLOCKED = 3

Deps = list[str]
Graph = dict[str, Deps]
States = dict[str, int]


def _normalize(packages: Graph) -> Graph:
    """Return the graph with every mentioned dependency present as a node."""
    graph = {name: list(deps) for name, deps in packages.items()}
    for deps in packages.values():
        for dep in deps:
            if dep not in graph:
                graph[dep] = []
    return graph


def _init_states(graph: Graph) -> States:
    """Create the visit table used to detect cycles while walking the graph."""
    return {name: UNVISITED for name in graph}


def _visit(
    name: str,
    graph: Graph,
    states: States,
    order: Deps,
    stuck: set[str],
) -> bool:
    """Depth-first walk; returns False if `name` sits on or below a cycle."""
    if states[name] == DONE:
        return True
    if states[name] == BLOCKED:
        return False
    if states[name] == ACTIVE:
        stuck.add(name)
        return False
    states[name] = ACTIVE
    resolvable = True
    for dep in graph[name]:
        if not _visit(dep, graph, states, order, stuck):
            resolvable = False
    if resolvable:
        states[name] = DONE
        order.append(name)
        return True
    states[name] = BLOCKED
    stuck.add(name)
    return False


def resolve(packages: Graph) -> tuple[Deps, Deps]:
    graph = _normalize(packages)
    states = _init_states(graph)
    order: list[str] = []
    stuck: set[str] = set()
    for name in sorted(graph):
        _visit(name, graph, states, order, stuck)
    return order, sorted(stuck)


def format_report(packages: Graph, order: Deps, stuck: Deps) -> str:
    counts: dict[str, int] = {name: len(packages.get(name, [])) for name in order}
    implicit: list[str] = sorted(name for name in order if name not in packages)
    lines = ["Installation order:"]
    for step, name in enumerate(order, start=1):
        lines.append(f"  {step:2d}. {name} ({counts[name]} direct dependencies)")
    if implicit:
        lines.append("Not declared, installed as leaves: " + ", ".join(implicit))
    if stuck:
        lines.append("Stuck in circular dependencies: " + ", ".join(stuck))
    else:
        lines.append("No circular dependencies found.")
    return "\n".join(lines)


def main() -> None:
    packages: Graph = {
        "webapp": ["flask", "database"],
        "flask": ["werkzeug", "jinja"],
        "werkzeug": [],
        "jinja": ["markupsafe"],
        "database": ["driver"],
        "driver": ["config"],
        "config": ["driver"],
    }
    order, stuck = resolve(packages)
    print(format_report(packages, order, stuck))


if __name__ == "__main__":
    main()

