from typing import Dict, List, Tuple


def matchable_amount(donation: int, budget: int) -> int:
    """How much of `donation` a campaign with `budget` left can still match."""
    if donation < 0:
        raise ValueError(f"contribution must not be negative: {donation}")
    if budget <= 0:
        return 0
    return min(donation, budget)


def deduct(campaigns: Dict[str, int], name: str, amount: int) -> int:
    """Take `amount` out of one campaign's budget and report what is left."""
    remaining = campaigns[name] - amount
    if remaining < 0:
        raise ValueError(f"overdrawn budget for {name}")
    campaigns[name] = remaining
    return remaining


def validate_budgets(campaigns: Dict[str, int]) -> None:
    for name, budget in campaigns.items():
        if budget < 0:
            raise ValueError(f"budget of {name} is negative: {budget}")


def split_donation(
    donation: int,
    campaigns: Dict[str, int],
) -> Dict[str, int]:
    """Spread a single contribution over the campaigns that still have budget."""
    shares: Dict[str, int] = {}
    outstanding = donation
    for name in campaigns:
        if outstanding == 0:
            break
        share = matchable_amount(outstanding, campaigns[name])
        if share > 0:
            deduct(campaigns, name, share)
            shares[name] = share
            outstanding -= share
    return shares


def fund(
    donations: List[int],
    campaigns: Dict[str, int],
) -> Tuple[
    Dict[str, int],
    List[int],
]:
    """Match contributions against campaign budgets, in order, until they dry up."""
    validate_budgets(campaigns)
    budgets = dict(campaigns)
    matched: Dict[str, int] = {name: 0 for name in budgets}
    unmatched: List[int] = []
    for donation in donations:
        shares = split_donation(donation, budgets)
        for name, share in shares.items():
            matched[name] += share
        if sum(shares.values()) < donation:
            unmatched.append(donation)
    return matched, unmatched


def format_report(
    matched: Dict[str, int],
    unmatched: List[int],
) -> List[str]:
    lines = [f"{name}: matched {matched[name]}" for name in sorted(matched)]
    lines.append(f"total matched: {sum(matched.values())}")
    if unmatched:
        shortfalls = [str(amount) for amount in unmatched]
        lines.append("partially matched contributions: " + ", ".join(shortfalls))
    else:
        lines.append("every contribution was fully matched")
    return lines


def main() -> None:
    donations: List[int] = [50, 120, 75, 200, 40]
    campaigns: Dict[str, int] = {"clean-water": 150, "school-books": 180, "shelter": 60}
