from itertools import combinations

Pair = tuple[str, str]
PairList = list[Pair]
Prices = list[int]
Usage = dict[str, int]
ItemBest = tuple[int, Pair]
Result = tuple[Prices, Usage]


def validate_cart(prices: Prices) -> Prices:
    """Return the cart prices, rejecting anything that is not a non-negative int."""
    checked: Prices = []
    for price in prices:
        if not isinstance(price, int) or price < 0:
            raise ValueError(f"invalid item price: {price!r}")
        checked.append(price)
    return checked


def code_pairs(codes: list[str]) -> PairList:
    """All ways of picking at most two codes; "" stands for an unused slot."""
    pairs: PairList = [("", "")]
    for code in codes:
        pairs.append((code, ""))
    for first, second in combinations(codes, 2):
        pairs.append((first, second))
    return pairs


def pair_price(price: int, pair: Pair, coupons: Usage) -> int:
    """Price after subtracting the flat deductions of the codes in `pair`."""
    total = price
    for code in pair:
        if code:
            total -= coupons[code]
    return max(total, 0)


def best_for_item(price: int, pairs: PairList, coupons: Usage) -> ItemBest:
    best_pair: Pair = ("", "")
    best_price = price
    for pair in pairs:
        candidate = pair_price(price, pair, coupons)
        if candidate < best_price:
            best_price = candidate
            best_pair = pair
    return best_price, best_pair


def combine(cart: Prices, coupons: Usage) -> Result:
    """Cheapest price per item using at most two coupons, plus code usage counts."""
    prices = validate_cart(cart)
    pairs = code_pairs(sorted(coupons))
    usage: Usage = {code: 0 for code in coupons}
    cheapest: Prices = []
    for price in prices:
        final, winning = best_for_item(price, pairs, coupons)
        cheapest.append(final)
        for code in winning:
            if code:
                usage[code] += 1
    return cheapest, usage


def format_report(original: Prices, final: Prices, usage: Usage) -> list[str]:
    lines = [f"item {i}: {a} -> {b}" for i, (a, b) in enumerate(zip(original, final))]
    lines.append(f"total saved: {sum(original) - sum(final)}")
    for code, times in sorted(usage.items(), key=lambda kv: (-kv[1], kv[0])):
        lines.append(f"{code} used {times}x")
    return lines


def main() -> None:
    cart: Prices = [120, 45, 8, 300]
    coupons: Usage = {"SAVE10": 10, "HALFOFF": 50, "TINY": 3}
    final, usage = combine(cart, coupons)
    for line in format_report(cart, final, usage):
        print(line)


if __name__ == "__main__":
    main()

