    return preferences


def parse_catalog(
    entries: list[str],
) -> list[ShowRecord]:
    """Turn "title | category" lines into show records."""
    catalog: list[ShowRecord] = []
    for entry in entries:
        title, _, category = entry.partition("|")
        catalog.append((title.strip(), category.strip().lower()))
    return catalog


def filter(
    episodes: list[ShowRecord],
    preferences: dict[str, bool],
) -> tuple[Titles, Tallies]:
