"""Match house hunters with homes they can actually afford."""

Listing = tuple[str, int]
Addresses = list[str]
Matches = dict[str, Addresses]
Budgets = dict[str, int]


def can_afford(price: int, budget: int) -> bool:
    """Return True when a single asking price fits inside one budget."""
    if price < 0:
        raise ValueError(f"asking price cannot be negative: {price}")
    return price <= budget


def parse_budgets(
    rows: list[str],
) -> Budgets:
    """Read "Name: budget" lines into a client -> budget mapping."""
    budgets: dict[str, int] = {}
    for row in rows:
        name, separator, raw_budget = row.rpartition(":")
        if not separator:
            raise ValueError(f"malformed budget entry: {row!r}")
        budgets[name.strip()] = int(raw_budget)
    return budgets


def parse_listings(
    rows: list[str],
) -> list[Listing]:
    """Read "address,price" lines into (address, price) pairs."""
    listings: list[Listing] = []
    for row in rows:
        address, separator, raw_price = row.rpartition(",")
        if not separator:
            raise ValueError(f"malformed listing entry: {row!r}")
        listings.append((address.strip(), int(raw_price)))
    return listings


def group_by_client(buyers: Budgets, listings: list[Listing]) -> Matches:
    """Group every affordable address under the name of each client."""
    matches: dict[str, Addresses] = {name: [] for name in buyers}
    for address, price in listings:
        for name, budget in buyers.items():
            if can_afford(price, budget):
                matches[name].append(address)
    return matches


def find_unaffordable(buyers: Budgets, listings: list[Listing]) -> Addresses:
    """Collect addresses that no client in the pool can pay for."""
    budgets: list[int] = list(buyers.values())
    leftovers: Addresses = []
    for address, price in listings:
        if not any(can_afford(price, budget) for budget in budgets):
            leftovers.append(address)
    return leftovers


def pair(buyers: Budgets, properties: list[Listing]) -> tuple[Matches, Addresses]:
    """Pair clients with affordable homes and flag the overpriced ones."""
    return group_by_client(buyers, properties), find_unaffordable(buyers, properties)


def format_report(matches: Matches, unaffordable: Addresses) -> list[str]:
    """Turn the pairing result into printable report lines."""
    lines: list[str] = []
    for name, addresses in sorted(matches.items()):
        lines.append(f"{name}: " + (", ".join(addresses) or "nothing in budget"))
    lines.append("Overpriced: " + (", ".join(unaffordable) or "none"))
    return lines


def main() -> None:
    budget_rows = ["Ada: 250000", "Bo: 400000", "Cleo: 180000"]
    listing_rows = [
        "12 Oak Lane, 175000",
        "7 Birch Road, 320000",
        "44 Cedar Court, 410000",
        "9 Maple Way, 249000",
    ]
    buyers = parse_budgets(budget_rows)
    listings = parse_listings(listing_rows)
    matches, unaffordable = pair(buyers, listings)
    for line in format_report(matches, unaffordable):
        print(line)


if __name__ == "__main__":
    main()

