import re

TOKEN_PATTERN = re.compile(r"[\w']+|[^\w\s]")
NO_SPACE_BEFORE = frozenset(",.!?;:)")


def tokenize(sentence: str) -> list[str]:
    """Split a sentence into words and standalone punctuation marks."""
    return TOKEN_PATTERN.findall(sentence)


def detokenize(tokens: list[str]) -> str:
    """Glue tokens back together with sensible spacing."""
    text = ""
    for token in tokens:
        if text and token not in NO_SPACE_BEFORE:
            text += " "
        text += token
    return text


def match_case(source: str, target: str) -> str:
    """Give the translated word the capitalisation of the source word."""
    if len(source) > 1 and source.isupper():
        return target.upper()
    if source[0].isupper():
        return target.capitalize()
    return target


def lookup(
    word: str,
    dictionary: dict[str, str],
    missing: dict[str, int],
) -> str:
    """Translate a single token, recording it in `missing` when unknown."""
    if not word[0].isalnum():
        return word
    key = word.lower()
    if key in dictionary:
        return match_case(word, dictionary[key])
    missing[key] = missing.get(key, 0) + 1
    return word


def translate(
    phrases: list[str],
    dictionary: dict[str, str],
) -> tuple[
    list[str],
    dict[str, int],
]:
    """Translate every sentence and report the words that had no entry."""
    translated: list[str] = []
    unrecognized: dict[str, int] = {}
    for phrase in phrases:
        tokens = tokenize(phrase)
        rendered: list[str] = [lookup(t, dictionary, unrecognized) for t in tokens]
        translated.append(detokenize(rendered))
    return translated, unrecognized


def format_report(
    unrecognized: dict[str, int],
) -> list[str]:
    """Build report lines, most frequent unknown word first."""
    ordered = sorted(unrecognized.items(), key=lambda item: (-item[1], item[0]))
    return [f"{word} ({count}x)" for word, count in ordered]


def main() -> None:
    glossary: dict[str, str] = {
        "the": "le",
        "cat": "chat",
        "dog": "chien",
        "sleeps": "dort",
        "and": "et",
        "runs": "court",
    }
    phrases: list[str] = [
        "The cat sleeps.",
        "The dog runs and barks!",
        "A cat and a dog.",
    ]
    sentences, unrecognized = translate(phrases, glossary)
    for original, result in zip(phrases, sentences):
        print(f"{original} -> {result}")
    report = format_report(unrecognized)
    print("Unrecognized: " + (", ".join(report) if report else "none"))


if __name__ == "__main__":
    main()

