from collections.abc import Mapping


def implicit_jobs(
    jobs: Mapping[str, list[str]],
) -> list[str]:
    """Names used as prerequisites but never declared as jobs themselves."""
    unknown: set[str] = set()
    for deps in jobs.values():
        for dep in deps:
            if dep not in jobs:
                unknown.add(dep)
    return sorted(unknown)


def inbound_counts(
    jobs: Mapping[str, list[str]],
) -> dict[str, int]:
    """Map every job to the number of prerequisites it is still waiting for."""
    counts: dict[str, int] = {}
    for name, deps in jobs.items():
        counts[name] = sum(1 for dep in deps if dep in jobs)
    return counts


def ready_jobs(
    counts: dict[str, int],
) -> list[str]:
    """Jobs with no outstanding prerequisites, in a stable alphabetical order."""
    return sorted(name for name, count in counts.items() if count == 0)


def sequence(
    jobs: Mapping[str, list[str]],
) -> list[str]:
    """Return a valid execution order, or [] when the graph contains a cycle."""
    remaining = {name: list(deps) for name, deps in jobs.items()}
    for name in implicit_jobs(jobs):
        remaining[name] = []
    order: list[str] = []
    while remaining:
        ready: list[str] = ready_jobs(inbound_counts(remaining))
        if not ready:
            return []
        order.extend(ready)
        done = set(ready)
        for name in ready:
            del remaining[name]
        for deps in remaining.values():
            deps[:] = [dep for dep in deps if dep not in done]
    return order


def step_numbers(
    order: list[str],
) -> dict[str, int]:
    """Assign a 1-based step number to each job of a computed order."""
    return {name: index for index, name in enumerate(order, start=1)}


def format_plan(
    steps: dict[str, int],
) -> list[str]:
    width = len(str(len(steps)))
    return [f"{number:>{width}}. {name}" for name, number in steps.items()]


def main() -> None:
    jobs = {
        "paint": ["sand", "prime"],
        "prime": ["sand"],
        "sand": [],
        "inspect": ["paint"],
    }
    plan: list[str] = sequence(jobs)
    for line in format_plan(step_numbers(plan)):
        print(line)

    cyclic = {"wash": ["dry"], "dry": ["wash"]}
    blocked: list[str] = sequence(cyclic)
    if not blocked:
        print("circular dependency detected:", ", ".join(sorted(cyclic)))


if __name__ == "__main__":
    main()

