Round = tuple[str, str, int]
Standing = tuple[str, int]
Leaderboard = list[Standing]
Totals = dict[str, int]
Result = tuple[Leaderboard, int]


def validate_rounds(rounds: list[Round]) -> None:
    """Reject malformed rounds before any scoring happens."""
    for index, entry in enumerate(rounds):
        if len(entry) != 3:
            raise ValueError(f"round {index} must hold name, action and points")
        name, action, points = entry
        if not isinstance(name, str) or not isinstance(action, str):
            raise TypeError(f"round {index} must use strings for name and action")
        if not isinstance(points, int) or isinstance(points, bool):
            raise TypeError(f"round {index} must use an integer points value")


def tally_points(rounds: list[Round]) -> Totals:
    """Sum every player's points across all rounds."""
    totals: dict[str, int] = {}
    for name, _action, points in rounds:
        totals[name] = totals.get(name, 0) + points
    return totals


def rank_players(totals: Totals) -> Leaderboard:
    """Turn the totals mapping into a leaderboard, best score first."""
    ordered: list[Standing] = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    return ordered


def best_single_action(rounds: list[Round]) -> int:
    """Largest amount of points awarded by one single action."""
    values: list[int] = [points for _name, _action, points in rounds]
    if not values:
        return 0
    return max(values)


def count_actions(rounds: list[Round]) -> Totals:
    """How many times each action was performed overall."""
    counts: dict[str, int] = {}
    for _name, action, _points in rounds:
        counts[action] = counts.get(action, 0) + 1
    return counts


def score(rounds: list[Round]) -> Result:
    validate_rounds(rounds)
    totals = tally_points(rounds)
    return rank_players(totals), best_single_action(rounds)


def format_leaderboard(board: Leaderboard) -> list[str]:
    lines: list[str] = []
    for rank, (name, total) in enumerate(board, start=1):
        lines.append(f"{rank}. {name:<8}{total:>5}")
    return lines


def main() -> None:
    rounds: list[Round] = [
        ("bob", "jump", 5),
        ("alice", "run", 7),
        ("bob", "dash", 3),
        ("carol", "jump", 9),
        ("alice", "dash", 4),
        ("carol", "run", -2),
    ]
    board, best = score(rounds)
    for line in format_leaderboard(board):
        print(line)
    print(f"best single action: {best}")

    action_totals: dict[str, int] = count_actions(rounds)
    summary: list[str] = [f"{action} x{times}" for action, times in sorted(action_totals.items())]
    print("actions: " + ", ".join(summary))


if __name__ == "__main__":
    main()

