"""Earliest-arrival routing over a timetable of train connections."""

import heapq

CENTRAL = "central"

Connection = tuple[str, str, int, int]
Adjacency = list[Connection]
Graph = dict[str, Adjacency]
Schedule = dict[str, int]
HeapItem = tuple[int, str]


def validate(connections: list[Connection]) -> Adjacency:
    """Reject timetable rows whose arrival precedes their departure."""
    checked: list[Connection] = []
    for source, dest, departure, arrival in connections:
        if arrival < departure:
            raise ValueError(f"{source}->{dest} arrives before it departs")
        checked.append((source, dest, departure, arrival))
    return checked


def build_graph(connections: list[Connection]) -> Graph:
    """Map every station to the connections leaving it."""
    graph: Graph = {}
    for connection in connections:
        graph.setdefault(connection[0], []).append(connection)
        graph.setdefault(connection[1], [])
    return graph


def search(graph: Graph, origin: str) -> Schedule:
    """Dijkstra-style scan keeping the earliest arrival per station."""
    arrivals: dict[str, int] = {origin: 0}
    queue: list[HeapItem] = [(0, origin)]
    while queue:
        now, station = heapq.heappop(queue)
        if now > arrivals.get(station, now):
            continue
        for _, dest, departure, arrival in graph.get(station, []):
            if departure < now:
                continue
            if arrival < arrivals.get(dest, arrival + 1):
                arrivals[dest] = arrival
                heapq.heappush(queue, (arrival, dest))
    return arrivals


def route(connections):
    """Earliest arrival time at every station reachable from central."""
    graph = build_graph(validate(connections))
    return search(graph, CENTRAL)


def unreachable(graph: Graph, schedule: Schedule) -> list[str]:
    return sorted(station for station in graph if station not in schedule)


def format_schedule(schedule: Schedule) -> list[str]:
    ranked: list[HeapItem] = sorted((time, station) for station, time in schedule.items())
    return [f"{station:>8} @ {time:02d}:00" for time, station in ranked]


def main() -> None:
    timetable: list[Connection] = [
        ("central", "north", 8, 9),
        ("central", "east", 8, 11),
        ("north", "east", 9, 10),
        ("east", "harbour", 7, 8),
        ("north", "harbour", 10, 13),
        ("depot", "central", 6, 7),
    ]
    schedule = route(timetable)
    for line in format_schedule(schedule):
        print(line)
    stranded: list[str] = unreachable(build_graph(timetable), schedule)
    if stranded:
        print("unreachable:", ", ".join(stranded))


if __name__ == "__main__":
    main()

