from typing import Dict, List, Set, Tuple

IngredientList = List[str]
Replacements = Dict[str, str]
SwapResult = Tuple[IngredientList, Set[str]]
RecipeBook = Dict[str, IngredientList]
MenuResult = Tuple[RecipeBook, IngredientList]


def normalise_replacements(replacements: Replacements) -> Dict[str, str]:
    """Lower-case the allergen keys and drop entries without a real alternative."""
    cleaned: Dict[str, str] = {}
    for allergen, alternative in replacements.items():
        key = allergen.strip().lower()
        safe = alternative.strip()
        if key and safe:
            cleaned[key] = safe
    return cleaned


def swap_ingredients(ingredients: List[str], replacements: Replacements) -> SwapResult:
    """Return the rewritten ingredient list plus the allergens actually swapped."""
    updated: IngredientList = []
    replaced: Set[str] = set()
    for ingredient in ingredients:
        key = ingredient.strip().lower()
        if key in replacements:
            updated.append(replacements[key])
            replaced.add(key)
        else:
            updated.append(ingredient)
    return updated, replaced


def swap_menu(recipes: RecipeBook, replacements: Replacements) -> Tuple[RecipeBook, Set[str]]:
    """Apply the ingredient swap to every dish on the menu."""
    rewritten: RecipeBook = {}
    all_replaced: Set[str] = set()
    for dish, ingredients in recipes.items():
        new_ingredients, replaced = swap_ingredients(ingredients, replacements)
        rewritten[dish] = new_ingredients
        all_replaced |= replaced
    return rewritten, all_replaced


def substitute(recipes: RecipeBook, replacements: Replacements) -> MenuResult:
    """Swap allergens for safe alternatives and report which allergens were used."""
    table = normalise_replacements(replacements)
    rewritten, replaced = swap_menu(recipes, table)
    allergens: IngredientList = sorted(replaced)
    return rewritten, allergens


def count_swaps_per_dish(original: RecipeBook, updated: RecipeBook) -> Dict[str, int]:
    """Count how many ingredients changed in each dish."""
    counts: Dict[str, int] = {}
    for dish, ingredients in original.items():
        new_ingredients = updated[dish]
        pairs = zip(ingredients, new_ingredients)
        counts[dish] = sum(1 for before, after in pairs if before != after)
    return counts


def format_report(counts: Dict[str, int], allergens: IngredientList) -> List[str]:
    lines: IngredientList = []
    for dish in sorted(counts):
        lines.append(f"{dish}: {counts[dish]} substitution(s)")
    lines.append("removed allergens: " + (", ".join(allergens) or "none"))
    return lines


def main() -> None:
    menu: RecipeBook = {
        "cake": ["flour", "Milk", "butter"],
        "pancakes": ["flour", "milk", "egg"],
        "salad": ["lettuce", "tomato"],
    }
    swaps: Dict[str, str] = {"milk": "oatmilk", "egg": "flaxseed", "honey": ""}
    updated, allergens = substitute(menu, swaps)
    for dish, ingredients in updated.items():
        print(f"{dish} -> {ingredients}")
    for line in format_report(count_swaps_per_dish(menu, updated), allergens):
        print(line)


if __name__ == "__main__":
    main()

