from __future__ import annotations

Components = list[str]
Batch = tuple[str, str, Components]
BatchList = list[Batch]
SiteMap = dict[str, str]
Sites = set[str]
OriginMap = dict[str, Sites]
LoadMap = dict[str, int]


def parse_batch(line: str) -> Batch:
    """Parse "product | site | comp, comp, ..." into a batch tuple."""
    fields = line.split("|")
    if len(fields) != 3:
        raise ValueError(f"malformed batch record: {line!r}")
    product, site, raw_components = (field.strip() for field in fields)
    components: Components = [c.strip() for c in raw_components.split(",") if c.strip()]
    return product, site, components


def build_component_sites(batches: BatchList) -> SiteMap:
    """Map every component identifier to the site it originates from."""
    sites: SiteMap = {}
    for product, site, _components in batches:
        sites[product] = site
    for _product, site, components in batches:
        for component in components:
            sites.setdefault(component, site)
    return sites


def upstream_sites(
    product: str,
    batches: BatchList,
    component_sites: SiteMap,
    seen: set[str] | None = None,
) -> Sites:
    """Collect every site appearing in the component tree of ``product``."""
    if seen is None:
        seen = set()
    if product in seen:
        return set()
    seen.add(product)
    found: Sites = set()
    for batch_product, _site, components in batches:
        if batch_product != product:
            continue
        for component in components:
            found.add(component_sites[component])
            found |= upstream_sites(component, batches, component_sites, seen)
    return found


def trace(batches: BatchList) -> OriginMap:
    component_sites = build_component_sites(batches)
    origins: OriginMap = {}
    for product, _site, _components in batches:
        origins[product] = upstream_sites(product, batches, component_sites)
    return origins


def site_load(origins: OriginMap) -> LoadMap:
    """Count how many traced products each site contributes to."""
    load: LoadMap = {}
    for sites in origins.values():
        for site in sites:
            load[site] = load.get(site, 0) + 1
    return load


def format_report(origins: OriginMap, load: LoadMap) -> list[str]:
    lines = []
    for product in sorted(origins):
        joined = ", ".join(sorted(origins[product])) or "-"
        lines.append(f"{product}: {joined}")
    for site, count in sorted(load.items(), key=lambda item: (-item[1], item[0])):
        lines.append(f"  site {site} feeds {count} product(s)")
    return lines


def main() -> None:
    records = [
        "phone | alpha | battery, screen",
        "battery | beta | cell, casing",
        "screen | gamma | glass",
        "cell | delta | lithium",
    ]
    batches: BatchList = [parse_batch(record) for record in records]
    origins = trace(batches)
    for line in format_report(origins, site_load(origins)):
        print(line)


if __name__ == "__main__":
    main()

