import string

Positions = list[int]
Lines = list[str]
Ranking = list[str]
Counts = dict[str, int]
Index = dict[str, Positions]
Span = tuple[int, int]
Spans = dict[str, Span]


def tokenize(line: str) -> list[str]:
    cleaned = line.translate(str.maketrans("", "", string.punctuation))
    words = []
    for word in cleaned.lower().split():
        if len(word) >= 3:
            words.append(word)
    return words


def build_index(lines: Lines) -> Index:
    index_map: Index = {}
    for number, line in enumerate(lines):
        for word in tokenize(line):
            positions = index_map.setdefault(word, [])
            if number not in positions:
                positions.append(number)
    return index_map


def count_occurrences(lines: Lines) -> Counts:
    counts: Counts = {}
    for line in lines:
        for word in tokenize(line):
            counts[word] = counts.get(word, 0) + 1
    return counts


def top_words(counts: Counts, limit: int = 3) -> Ranking:
    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return [word for word, _count in ranked[:limit]]


def index(
    lines: Lines,
) -> tuple[Index, Ranking]:
    index_map = build_index(lines)
    counts = count_occurrences(lines)
    return index_map, top_words(counts)


def format_report(index_map: Index, top: Ranking) -> str:
    rows = []
    for word in sorted(index_map):
        places = ", ".join(str(number) for number in index_map[word])
        rows.append(f"{word}: {places}")
    rows.append("top three: " + ", ".join(top))
    return "\n".join(rows)


def spread(index_map: Index) -> Spans:
    ranges: Spans = {}
    for word, positions in index_map.items():
        ranges[word] = (min(positions), max(positions))
    return ranges


def main() -> None:
    lines: Lines = [
        "The quick brown fox jumps over the lazy dog.",
        "A quick brown dog barks; the fox runs!",
        "Lazy dog, lazy fox -- the dog sleeps.",
    ]
    index_map, top = index(lines)
    print(format_report(index_map, top))
    ranges = spread(index_map)
    for word in top:
        first, last = ranges[word]
        print(f"{word} spans lines {first}-{last}")


if __name__ == "__main__":
    main()

