"""Aggregate wildlife observation counts by region and rank species by abundance."""

Observation = tuple[str, str, int]
ObservationList = list[Observation]
SpeciesCounts = dict[str, int]
Tally = dict[str, SpeciesCounts]
SpeciesList = list[str]
Ranking = dict[str, SpeciesList]
Pair = tuple[str, int]


def parse_observation(line: str) -> Observation:
    """Turn a 'region, species, count' text record into an observation tuple."""
    parts: list[str] = [field.strip() for field in line.split(",")]
    if len(parts) != 3:
        raise ValueError(f"expected 'region, species, count', got {line!r}")
    region, species, raw_count = parts
    if not region or not species:
        raise ValueError(f"region and species must be non-empty in {line!r}")
    return region, species, int(raw_count)


def read_observations(lines: list[str]) -> ObservationList:
    """Parse every non-blank text record into an observation."""
    records: ObservationList = []
    for line in lines:
        if line.strip():
            records.append(parse_observation(line))
    return records


def tally_counts(observations: ObservationList) -> Tally:
    """Sum the counts of each species inside each region."""
    tally: Tally = {}
    for region, species, count in observations:
        counts: SpeciesCounts = tally.setdefault(region, {})
        counts[species] = counts.get(species, 0) + count
    return tally


def rank_species(tally: Tally) -> Ranking:
    """Replace each region's counts by its species names, most abundant first."""
    ranking: Ranking = {}
    for region, counts in tally.items():
        ordered: list[Pair] = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
        ranking[region] = [pair[0] for pair in ordered]
    return ranking


def aggregate(observations: ObservationList) -> Ranking:
    """Map each region to its species sorted by total observed count, descending."""
    return rank_species(tally_counts(observations))


def format_report(ranking: Ranking) -> list[str]:
    """Render one readable line per region, regions in alphabetical order."""
    report: list[str] = []
    for region in sorted(ranking):
        species: SpeciesList = ranking[region]
        report.append(f"{region}: {' > '.join(species)}")
    return report


def main() -> None:
    raw_records: list[str] = [
        "north, bear, 2",
        "north, fox, 5",
        "north, bear, 4",
        "south, deer, 1",
        "south, fox, 1",
    ]
    observations = read_observations(raw_records)
    ranking = aggregate(observations)
    print(ranking)
    for line in format_report(ranking):
        print(line)


if __name__ == "__main__":
    main()

