Passenger = tuple[str, str, int]
Roster = list[Passenger]
Car = list[str]


def parse_requests(lines: list[str]) -> Roster:
    """Turn 'name, neighborhood, wait' text lines into passenger tuples."""
    requests: Roster = []
    for line in lines:
        parts: list[str] = [field.strip() for field in line.split(",")]
        if len(parts) != 3:
            raise ValueError(f"malformed request: {line!r}")
        name, neighborhood, wait = parts
        requests.append((name, neighborhood, int(wait)))
    return requests


def group_by_neighborhood(requests: Roster) -> dict[str, Roster]:
    """Collect the passengers that share a pickup neighborhood."""
    groups: dict[str, Roster] = {}
    for passenger in requests:
        groups.setdefault(passenger[1], []).append(passenger)
    return groups


def split_into_cars(passengers: Roster, capacity: int) -> list[Roster]:
    """Longest waiting passengers board first, then chunk by capacity."""
    if capacity < 1:
        raise ValueError("capacity must be at least one passenger per car")
    ordered: Roster = sorted(passengers, key=lambda passenger: -passenger[2])
    cars: list[Roster] = []
    for start in range(0, len(ordered), capacity):
        cars.append(ordered[start:start + capacity])
    return cars


def assign(requests: Roster, capacity: int) -> list[Car]:
    """Return one list of passenger names per dispatched car."""
    grouped = group_by_neighborhood(requests)
    assignments: list[Car] = []
    for neighborhood in sorted(grouped):
        for car in split_into_cars(grouped[neighborhood], capacity):
            names: list[str] = [passenger[0] for passenger in car]
            assignments.append(names)
    return assignments


def longest_waits(
    groups: dict[str, Roster],
) -> dict[str, int]:
    """Worst wait time still outstanding in each neighborhood."""
    waits: dict[str, int] = {}
    for neighborhood, passengers in groups.items():
        waits[neighborhood] = max(passenger[2] for passenger in passengers)
    return waits


def format_manifest(
    cars: list[Car],
    waits: dict[str, int],
) -> list[str]:
    report: list[str] = []
    for index, car in enumerate(cars, start=1):
        report.append(f"Car {index}: " + ", ".join(car))
    for neighborhood, wait in sorted(waits.items()):
        report.append(f"{neighborhood}: longest wait {wait} min")
    return report


def main() -> None:
    raw: list[str] = [
        "dan, downtown, 10",
        "erin, downtown, 4",
        "omar, downtown, 15",
        "lena, riverside, 7",
    ]
    requests = parse_requests(raw)
    cars = assign(requests, 2)
    print(cars)
    for line in format_manifest(cars, longest_waits(group_by_neighborhood(requests))):
        print(line)


if __name__ == "__main__":
    main()

