Performance = tuple[str, int, int]
Stage = list[Performance]
Lineup = list[str]
BusyTimes = dict[str, int]


def validate(
    performances: list[Performance],
) -> list[Performance]:
    """Check every entry looks like (band, start, end) with a positive length."""
    checked: list[Performance] = []
    for entry in performances:
        name, start, end = entry
        if not isinstance(name, str) or not name:
            raise ValueError(f"band name must be a non-empty string: {name!r}")
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError(f"times must be integers for band {name!r}")
        if end <= start:
            raise ValueError(f"performance of {name!r} ends before it starts")
        checked.append((name, start, end))
    return checked


def can_schedule(stage: Stage, performance: Performance) -> bool:
    """True when the new performance overlaps nothing already on the stage."""
    _, start, end = performance
    for _, booked_start, booked_end in stage:
        if start < booked_end and booked_start < end:
            return False
    return True


def place_performances(
    ordered: list[Performance],
) -> list[Stage]:
    """Greedily drop each performance on the first stage with room for it."""
    stages: list[Stage] = []
    for performance in ordered:
        for stage in stages:
            if can_schedule(stage, performance):
                stage.append(performance)
                break
        else:
            stages.append([performance])
    return stages


def schedule(
    performances: list[Performance],
) -> list[Lineup]:
    ordered = sorted(validate(performances), key=lambda item: item[1])
    stages = place_performances(ordered)
    return [[name for name, _, _ in stage] for stage in stages]


def stage_busy_times(
    performances: list[Performance],
) -> BusyTimes:
    """Total playing time booked per stage label, e.g. {'Stage 1': 7}."""
    ordered = sorted(validate(performances), key=lambda item: item[1])
    busy: BusyTimes = {}
    for index, stage in enumerate(place_performances(ordered), start=1):
        busy[f"Stage {index}"] = sum(end - start for _, start, end in stage)
    return busy


def format_report(
    lineups: list[Lineup],
    busy: BusyTimes,
) -> list[str]:
    lines: list[str] = []
    for index, bands in enumerate(lineups, start=1):
        label = f"Stage {index}"
        lines.append(f"{label}: {' -> '.join(bands)} ({busy[label]} h)")
    return lines


def main() -> None:
    festival: list[Performance] = [
        ("rockband", 1, 3),
        ("jazztrio", 2, 5),
        ("folkduo", 3, 4),
        ("synthwave", 4, 6),
        ("bluesmen", 5, 7),
    ]
    for line in format_report(schedule(festival), stage_busy_times(festival)):
        print(line)
    print(schedule([("rockband", 1, 3)]))


