"""Progressive income tax calculator for a roster of individuals."""

Record = tuple[str, int]
Entry = tuple[float, str]
Registry = dict[str, Entry]
Names = list[str]
Roster = list[Record]

BRACKET_NAMES: list[str] = ["low", "medium", "high", "top"]
BRACKET_FLOORS: dict[str, int] = {"low": 0, "medium": 10_000, "high": 50_000, "top": 150_000}
BRACKET_RATES: dict[str, float] = {"low": 0.10, "medium": 0.20, "high": 0.30, "top": 0.40}


def assess_income(income: int) -> tuple[bool, float, str]:
    """Return validity, tax owed and the name of the highest bracket reached."""
    if income < 0:
        return (False, 0.0, "")
    tax = 0.0
    reached = BRACKET_NAMES[0]
    for index, name in enumerate(BRACKET_NAMES):
        floor = BRACKET_FLOORS[name]
        if income <= floor:
            break
        if index + 1 < len(BRACKET_NAMES):
            ceiling = BRACKET_FLOORS[BRACKET_NAMES[index + 1]]
        else:
            ceiling = income
        tax += (min(income, ceiling) - floor) * BRACKET_RATES[name]
        reached = name
    return (True, round(tax, 2), reached)


def build_registry(roster: Roster) -> Registry:
    """Drop invalid entries and map each name to its tax and highest bracket."""
    registry: Registry = {}
    for name, income in roster:
        valid, tax, bracket = assess_income(income)
        if valid:
            registry[name] = (tax, bracket)
    return registry


def top_bracket_names(registry: Registry) -> Names:
    highest = BRACKET_NAMES[-1]
    return sorted(name for name, (_, bracket) in registry.items() if bracket == highest)


def totals_by_bracket(registry: Registry) -> dict[str, float]:
    totals: dict[str, float] = {name: 0.0 for name in BRACKET_NAMES}
    for tax, bracket in registry.values():
        totals[bracket] = round(totals[bracket] + tax, 2)
    return totals


def format_report(registry: Registry, top_earners: Names) -> list[str]:
    lines: list[str] = []
    for name in sorted(registry):
        tax, bracket = registry[name]
        lines.append(f"{name:<8} {tax:>12,.2f}  {bracket}")
    for bracket, total in totals_by_bracket(registry).items():
        lines.append(f"total[{bracket}] = {total:,.2f}")
    lines.append("top bracket: " + (", ".join(top_earners) if top_earners else "none"))
    return lines


def calculate(incomes: Roster) -> tuple[Registry, Names]:
    registry = build_registry(incomes)
    return (registry, top_bracket_names(registry))


def main() -> None:
    roster: Roster = [
        ("eve", 50),
        ("adam", 42_000),
        ("mallory", -1),
        ("trent", 180_000),
        ("peggy", 150_001),
    ]
    registry, top_earners = calculate(roster)
    for line in format_report(registry, top_earners):
        print(line)


if __name__ == "__main__":
    main()

