HIGH_USAGE_THRESHOLD = 100

Reading = tuple[str, str, int]
Readings = list[Reading]
CategoryTotals = dict[str, int]
DeviceIds = set[str]
DeviceList = list[str]
CategoryTotal = tuple[str, int]
Ranking = list[CategoryTotal]
AnalysisResult = tuple[CategoryTotals, DeviceList]


def totals_by_category(readings: Readings) -> CategoryTotals:
    """Accumulate energy usage per category."""
    totals: CategoryTotals = {}
    for device, category, usage in readings:
        if not device:
            raise ValueError("device identifier must not be empty")
        totals[category] = totals.get(category, 0) + usage
    return totals


def high_usage_devices(readings: Readings) -> DeviceIds:
    """Collect identifiers of devices whose usage exceeds the threshold."""
    flagged: DeviceIds = set()
    for device, _category, usage in readings:
        if usage > HIGH_USAGE_THRESHOLD:
            flagged.add(device)
    return flagged


def analyze(readings: Readings) -> AnalysisResult:
    """Return category totals together with the sorted high usage devices."""
    totals = totals_by_category(readings)
    flagged = high_usage_devices(readings)
    return totals, sorted(flagged)


def parse_line(line: str) -> Reading:
    """Parse one comma separated reading, e.g. 'heater,climate,200'."""
    parts = [field.strip() for field in line.split(",")]
    if len(parts) != 3:
        raise ValueError(f"expected 3 fields, got {len(parts)}: {line!r}")
    device, category, usage = parts
    return device, category, int(usage)


def parse_readings(lines: list[str]) -> Readings:
    """Parse a batch of textual readings, skipping blank lines."""
    readings: Readings = []
    for line in lines:
        if line.strip():
            readings.append(parse_line(line))
    return readings


def rank_categories(totals: CategoryTotals) -> Ranking:
    """Order categories by descending usage, breaking ties by name."""
    return sorted(totals.items(), key=lambda item: (-item[1], item[0]))


def format_report(totals: CategoryTotals, flagged: DeviceList) -> str:
    """Render a human readable summary of one analysis run."""
    lines = ["Energy usage by category:"]
    for category, total in rank_categories(totals):
        lines.append(f"  {category:<10} {total:>6} units")
    if flagged:
        lines.append("High usage devices: " + ", ".join(flagged))
    else:
        lines.append("High usage devices: none")
    return "\n".join(lines)


def main() -> None:
    raw: list[str] = [
        "heater,climate,200",
        "fan,climate,45",
        "fridge,kitchen,130",
        "",
        "lamp,lighting,20",
        "oven,kitchen,90",
    ]
    totals, flagged = analyze(parse_readings(raw))
    print(format_report(totals, flagged))


if __name__ == "__main__":
    main()

