EPS = 1e-9
MAX_STEPS = 4

Rate = tuple[str, str, float]
Edge = tuple[str, float]
Adjacency = list[Edge]
Graph = dict[str, Adjacency]
Dataset = list[Rate]
Path = list[str]


def validate_rates(rates: list[Rate]) -> None:
    for src, dst, mult in rates:
        if not src or not dst:
            raise ValueError("currency codes must be non-empty")
        if mult <= 0.0:
            raise ValueError(f"multiplier for {src}->{dst} must be positive")


def build_graph(rates: list[Rate]) -> Graph:
    graph: Graph = {}
    for src, dst, mult in rates:
        edges: Adjacency = graph.setdefault(src, [])
        edges.append((dst, mult))
        graph.setdefault(dst, [])
    return graph


def outdegree(graph: Graph) -> dict[str, int]:
    return {currency: len(edges) for currency, edges in graph.items()}


def _search(
    graph: Graph,
    start: str,
    current: str,
    product: float,
    path: list[str],
) -> Path:
    if len(path) > MAX_STEPS:
        return []
    for target, mult in graph.get(current, []):
        gain = product * mult
        if target == start:
            if gain > 1.0 + EPS:
                return path + [start]
        elif target not in path:
            found = _search(graph, start, target, gain, path + [target])
            if found:
                return found
    return []


def arbitrage(rates: Dataset) -> Path:
    validate_rates(rates)
    graph = build_graph(rates)
    for start in sorted(graph):
        cycle = _search(graph, start, start, 1.0, [start])
        if cycle:
            return cycle
    return []


def cycle_product(graph: Graph, path: list[str]) -> float:
    product = 1.0
    for current, target in zip(path, path[1:]):
        product *= max(mult for dst, mult in graph[current] if dst == target)
    return product


def describe(rates: Dataset) -> str:
    graph = build_graph(rates)
    degrees = outdegree(graph)
    spread = ", ".join(f"{cur}:{deg}" for cur, deg in sorted(degrees.items()))
    path = arbitrage(rates)
    if not path:
        return f"[{spread}] -> no arbitrage, result {path}"
    factor = cycle_product(graph, path)
    return f"[{spread}] -> {' -> '.join(path)} (x{factor:.4f})"


def main() -> None:
    datasets: list[Dataset] = [
        [("gold", "silver", 2.0)],
        [("USD", "EUR", 0.9), ("EUR", "JPY", 160.0), ("JPY", "USD", 0.008)],
        [("USD", "EUR", 0.9), ("EUR", "USD", 1.1)],
    ]
    for rates in datasets:
        print(describe(rates))


if __name__ == "__main__":
    main()

