from typing import Dict, List

CourseList = List[str]
CourseMap = Dict[str, CourseList]


def meets_requirements(
    completed: List[str],
    required: List[str],
) -> bool:
    """Return True when every required course appears in the completed list."""
    done = set(completed)
    return all(course in done for course in required)


def eligible_courses(
    completed: List[str],
    prerequisites: CourseMap,
) -> List[str]:
    """Return the courses a single student can take next, in catalogue order."""
    done = set(completed)
    eligible: CourseList = []
    for course, required in prerequisites.items():
        if course in done:
            continue
        if meets_requirements(completed, required):
            eligible.append(course)
    return eligible


def validate(students: CourseMap, prerequisites: CourseMap) -> CourseMap:
    """Map each student name to the list of new courses they are eligible for."""
    result: CourseMap = {}
    for name, completed in students.items():
        result[name] = eligible_courses(completed, prerequisites)
    return result


def missing_prerequisites(
    completed: List[str],
    prerequisites: CourseMap,
) -> CourseMap:
    """For each course out of reach, list the courses the student has not passed."""
    done = set(completed)
    pending: CourseMap = {}
    for course, required in prerequisites.items():
        if course in done:
            continue
        gaps = [req for req in required if req not in done]
        if gaps:
            pending[course] = gaps
    return pending


def progress_counts(eligibility: CourseMap) -> Dict[str, int]:
    """Count how many new courses each student may enrol in."""
    return {name: len(courses) for name, courses in eligibility.items()}


def format_report(eligibility: CourseMap, pending: Dict[str, CourseMap]) -> str:
    """Build a human readable summary of eligibility and outstanding courses."""
    counts = progress_counts(eligibility)
    lines: List[str] = []
    for name in sorted(eligibility):
        open_courses = ", ".join(eligibility[name]) or "nothing new"
        lines.append(f"{name} ({counts[name]} available): {open_courses}")
        for course, gaps in sorted(pending[name].items()):
            lines.append(f"    {course} still needs {', '.join(gaps)}")
    return "\n".join(lines)


def main() -> None:
    students: CourseMap = {
        "john": ["math"],
        "ada": ["math", "physics"],
        "bea": [],
    }
    prerequisites: CourseMap = {
        "physics": ["math"],
        "mechanics": ["math", "physics"],
        "math": [],
        "art": [],
    }
    eligibility = validate(students, prerequisites)
    pending: Dict[str, CourseMap] = {
        name: missing_prerequisites(completed, prerequisites)
        for name, completed in students.items()
    }
    print(eligibility)
    print(format_report(eligibility, pending))


if __name__ == "__main__":
    main()

