    submissions: list[str],
) -> dict[str, int]:
    """Tally how often each author appears in the submission list."""
    counts: dict[str, int] = {}
    for name in submissions:
        counts[name] = counts.get(name, 0) + 1
    return counts


def validate(submissions: list[str]) -> None:
    """Reject input that cannot yield three distinct foreign reviewers."""
    if len(submissions) < 4:
        raise ValueError("need at least four submissions to assign three reviewers")
    duplicates: list[str] = [name for name, n in count_names(submissions).items() if n > 1]
    if duplicates:
        raise ValueError("duplicate authors: " + ", ".join(sorted(duplicates)))


def shift(names: list[str], offset: int) -> Reviewers:
    """Return the name list rotated left by `offset` positions."""
    size = len(names)
    step = offset % size
    return [names[(i + step) % size] for i in range(size)]


def collate(
    names: list[str],
) -> dict[str, Reviewers]:
    """Map every author to the three reviewers drawn from offsets 1, 2 and 3."""
    assignments: dict[str, Reviewers] = {name: [] for name in names}
    for offset in (1, 2, 3):
        reviewers = shift(names, offset)
        for author, reviewer in zip(names, reviewers):
            assignments[author].append(reviewer)
    return assignments


def workload(
    assignments: dict[str, Reviewers],
) -> dict[str, int]:
    """Count how many papers each person has been asked to review."""
    load: dict[str, int] = {author: 0 for author in assignments}
    for reviewers in assignments.values():
        for reviewer in reviewers:
            load[reviewer] += 1
    return load


def match(submissions: list[str]) -> Roster:
    """Assign three distinct peer reviewers to every submitted paper."""
    validate(submissions)
    assignments = collate(submissions)
    pairs: Roster = []
