    lines: list[str] = []
    for author, reviewers in pairs:
        lines.append(f"{author}: reviewed by {', '.join(reviewers)}")
    load: dict[str, int] = workload(dict(pairs))
    for reviewer in sorted(load):
        lines.append(f"{reviewer} reviews {load[reviewer]} paper(s)")
    return lines


