import random

Pair = tuple[str, str]


def shuffled(
    names: list[str],
) -> list[str]:
    """Return a new list containing the same names in random order."""
    copy: list[str] = list(names)
    random.shuffle(copy)
    return copy


def is_derangement(
    original: list[str],
    candidate: list[str],
) -> bool:
    """True only if no name occupies the same position in both lists."""
    if len(original) != len(candidate):
        return False
    for giver, receiver in zip(original, candidate):
        if giver == receiver:
            return False
    return True


def validate(
    participants: list[str],
) -> list[str]:
    """Strip the names and reject empty, duplicate or too-few entries."""
    cleaned: list[str] = [name.strip() for name in participants]
    if any(not name for name in cleaned):
        raise ValueError("participant names must not be empty")
    seen: dict[str, int] = {}
    for name in cleaned:
        seen[name] = seen.get(name, 0) + 1
    repeated = sorted(name for name, count in seen.items() if count > 1)
    if repeated:
        raise ValueError("duplicate participants: " + ", ".join(repeated))
    if len(cleaned) < 2:
        raise ValueError("at least two participants are required")
    return cleaned


def draw(
    participants: list[str],
) -> list[Pair]:
    """Pair every giver with a receiver so that nobody draws themselves."""
    givers = validate(participants)
    receivers = shuffled(givers)
    while not is_derangement(givers, receivers):
        receivers = shuffled(givers)
    return list(zip(givers, receivers))


def format_pairs(pairs: list[Pair]) -> str:
    """Render the pairing as one aligned 'giver -> receiver' line per pair."""
    width = max(len(giver) for giver, _ in pairs)
    lines: list[str] = []
    for giver, receiver in pairs:
        lines.append(f"{giver.ljust(width)} -> {receiver}")
    return "\n".join(lines)


def receiver_index(
    pairs: list[Pair],
) -> dict[str, str]:
    """Map each receiver back to the giver who has to buy their present."""
    index: dict[str, str] = {}
    for giver, receiver in pairs:
        index[receiver] = giver
    return index


def main() -> None:
    people: list[str] = ["alice", "bob", "carol", " dave "]
    pairs = draw(people)
    print(format_pairs(pairs))
    lookup = receiver_index(pairs)
    print("\ngifts received:")
    for receiver in sorted(lookup):
        print(f"{receiver} gets a present from {lookup[receiver]}")


if __name__ == "__main__":
    main()

