import sys
from collections import deque

Names = list[str]
Puzzle = tuple[str, Names]
PuzzleList = list[Puzzle]
Counts = dict[str, int]
DependentMap = dict[str, Names]

def count_prerequisites(puzzles: PuzzleList) -> Counts:
    counts: dict[str, int] = {}
    for name, prereqs in puzzles:
        counts.setdefault(name, 0)
        for prereq in prereqs:
            counts.setdefault(prereq, 0)
        counts[name] += len(prereqs)
    return counts

def build_dependents(puzzles: PuzzleList) -> DependentMap:
    dependents: DependentMap = {}
    for name, prereqs in puzzles:
        dependents.setdefault(name, [])
        for prereq in prereqs:
            dependents.setdefault(prereq, []).append(name)
    return dependents

def order(puzzles):
    remaining = count_prerequisites(puzzles)
    dependents = build_dependents(puzzles)
    queue: list[str] = sorted(name for name, n in remaining.items() if n == 0)
    pending = deque(queue)
    solved: list[str] = []
    while pending:
        current = pending.popleft()
        solved.append(current)
        for follower in dependents[current]:
            remaining[follower] -= 1
            if remaining[follower] == 0:
                pending.append(follower)
    if len(solved) != len(remaining):
        blocked = sorted(name for name, n in remaining.items() if n > 0)
        raise ValueError("circular prerequisites among: " + ", ".join(blocked))
    return solved

def parse_line(line: str) -> Puzzle:
    name, _, rest = line.partition(":")
    prereqs = [part.strip() for part in rest.split(",") if part.strip()]
    return name.strip(), prereqs

def read_puzzles(lines) -> PuzzleList:
    parsed: PuzzleList = []
    for line in lines:
        stripped = line.strip()
        if stripped and not stripped.startswith("#"):
            parsed.append(parse_line(stripped))
    return parsed

def format_schedule(sequence: Names) -> str:
    steps: list[str] = []
    for index, name in enumerate(sequence, start=1):
        steps.append(f"{index}. {name}")
    return "\n".join(steps)

def depth_report(puzzles: PuzzleList, sequence: Names) -> Counts:
    depths: dict[str, int] = {name: 0 for name in sequence}
    prereq_map: DependentMap = {name: prereqs for name, prereqs in puzzles}
    for name in sequence:
        for prereq in prereq_map.get(name, []):
            depths[name] = max(depths[name], depths[prereq] + 1)
    return depths

def main() -> None:
    puzzles = read_puzzles(sys.stdin)
    sequence = order(puzzles)
    print(format_schedule(sequence))
    depths = depth_report(puzzles, sequence)
    print("deepest chain:", max(depths.values(), default=0))

if __name__ == "__main__":
    main()

