MIN_GREEN = 10

Phase = tuple[int, int]
Record = tuple[str, int, int]
Timings = dict[str, Phase]
Corridor = list[Record]


def green_split(north_volume: int, east_volume: int) -> Phase:
    """Split a cycle proportionally to the two volumes, never below MIN_GREEN."""
    if north_volume < 0 or east_volume < 0:
        raise ValueError("traffic volumes must be non-negative")
    if north_volume == 0 or east_volume == 0:
        return (MIN_GREEN, MIN_GREEN)
    divisor = _gcd(north_volume, east_volume)
    north_share = north_volume // divisor
    east_share = east_volume // divisor
    scale = -(-MIN_GREEN // min(north_share, east_share))
    return (north_share * scale, east_share * scale)


def _gcd(first: int, second: int) -> int:
    while second:
        first, second = second, first % second
    return first


def intersection_timing(intersection: Record) -> Timings:
    """Turn one raw intersection record into a single-entry timing mapping."""
    name, north_volume, east_volume = intersection
    if not name:
        raise ValueError("intersection name must not be empty")
    return {name: green_split(north_volume, east_volume)}


def synchronize(intersections: Corridor) -> Timings:
    """Map every intersection name to its northbound/eastbound green times."""
    timings: Timings = {}
    for intersection in intersections:
        timings.update(intersection_timing(intersection))
    return timings


def cycle_lengths(timings: Timings) -> dict[str, int]:
    """Full cycle duration (both phases) for each intersection."""
    cycles: dict[str, int] = {}
    for name, (north, east) in timings.items():
        cycles[name] = north + east
    return cycles


def volume_totals(intersections: Corridor) -> list[int]:
    """Combined traffic volume of each record, in input order."""
    totals: list[int] = []
    for _, north_volume, east_volume in intersections:
        totals.append(north_volume + east_volume)
    return totals


def format_report(
    timings: Timings,
    cycles: dict[str, int],
    demands: list[int],
) -> list[str]:
    rows: list[str] = []
    for name in sorted(timings):
        north, east = timings[name]
        rows.append(
            f"{name:<8} north={north:>3}s east={east:>3}s cycle={cycles[name]:>3}s"
        )
    rows.append(f"corridor demand: {sum(demands)} vehicles/hour")
    return rows


def main() -> None:
    intersections: Corridor = [
        ("main", 20, 20),
        ("oak", 30, 20),
        ("pine", 45, 0),
        ("elm", 120, 45),
    ]
    timings = synchronize(intersections)
    demands = volume_totals(intersections)
    for line in format_report(timings, cycle_lengths(timings), demands):
        print(line)


if __name__ == "__main__":
    main()

