def validate(passes: list[Pass]) -> None:
    """Reject malformed pass records before any scheduling is attempted."""
    for record in passes:
        name, aos, los = record
        if not isinstance(name, str) or not name:
            raise ValueError("satellite name must be a non-empty string")
        if not isinstance(aos, int) or not isinstance(los, int):
            raise TypeError(f"times for {name} must be integers")
        if aos >= los:
            raise ValueError(f"loss of signal for {name} must follow acquisition")


def overlaps(assigned: list[Pass], new_pass: Pass) -> bool:
    """True when the new pass shares any time with an already assigned pass."""
    _, new_aos, new_los = new_pass
    for _, aos, los in assigned:
        if new_aos < los and aos < new_los:
            return True
    return False


def find_antenna(schedule: dict[int, Timeline], new_pass: Pass) -> int:
    """Lowest numbered antenna that is free for the whole pass, else -1."""
    for antenna in ANTENNAS:
        if not overlaps(schedule[antenna], new_pass):
            return antenna
    return -1


def allocate(
    passes: list[Pass],
) -> dict[int, Names]:
    validate(passes)
    schedule: dict[int, Timeline] = {antenna: [] for antenna in ANTENNAS}
    for record in sorted(passes, key=lambda item: item[1]):
        antenna = find_antenna(schedule, record)
        if antenna == -1:
            raise ValueError(f"no antenna available for {record[0]}")
        schedule[antenna].append(record)
    result: dict[int, Names] = {}
    for antenna in ANTENNAS:
        if schedule[antenna]:
            result[antenna] = [name for name, _, _ in schedule[antenna]]
    return result


