Bid = tuple[str, str, int]
Offer = tuple[str, int]
OfferList = list[Offer]
Grouped = dict[str, OfferList]
Result = dict[str, Offer]


def normalize_bids(
    raw: list[Bid],
) -> list[Bid]:
    """Strip names, reject empty labels and negative amounts."""
    cleaned: list[Bid] = []
    for bidder, item, amount in raw:
        name = bidder.strip()
        label = item.strip()
        if not name:
            raise ValueError("bidder name must not be empty")
        if not label:
            raise ValueError("item name must not be empty")
        if amount < 0:
            raise ValueError(f"negative bid on {label!r} by {name!r}")
        cleaned.append((name, label, int(amount)))
    return cleaned


def group_bids(bids: list[Bid]) -> Grouped:
    """Map each item name to the offers made on it, in arrival order."""
    grouped: Grouped = {}
    for bidder, item, amount in bids:
        grouped.setdefault(item, []).append((bidder, amount))
    return grouped


def highest_bid(offers: OfferList) -> tuple[str, int]:
    """Return the biggest offer, keeping the earliest one on ties."""
    best = offers[0]
    for offer in offers[1:]:
        if offer[1] > best[1]:
            best = offer
    return best


def resolve(bids: list[Bid]) -> Result:
    grouped = group_bids(normalize_bids(bids))
    winners: dict[str, Offer] = {}
    for item, offers in grouped.items():
        winners[item] = highest_bid(offers)
    return winners


def count_wins(results: Result) -> dict[str, int]:
    tally: dict[str, int] = {}
    for bidder, _amount in results.values():
        tally[bidder] = tally.get(bidder, 0) + 1
    return tally


def format_report(results: Result) -> list[str]:
    lines: list[str] = []
    for item in sorted(results):
        bidder, amount = results[item]
        lines.append(f"{item}: {bidder} wins with {amount}")
    for bidder, wins in sorted(count_wins(results).items()):
        lines.append(f"  {bidder} took {wins} item(s)")
    return lines


def main() -> None:
    data: list[Bid] = [
        ("sam", "vase", 50),
        ("ada", "vase", 50),
        ("ada", "lamp", 30),
        ("leo", "lamp", 45),
        ("sam", "rug", 10),
    ]
    for line in format_report(resolve(data)):
        print(line)


if __name__ == "__main__":
    main()

