Player = tuple[str, str, int, int]


def value_metric(
    players: list[Player],
) -> dict[str, float]:
    """Map each player name to its score-per-cost value."""
    metrics: dict[str, float] = {}
    for name, _position, cost, score in players:
        if cost <= 0:
            raise ValueError(f"cost for {name} must be a positive integer")
        metrics[name] = score / cost
    return metrics


def position_counts(
    players: list[Player],
) -> dict[str, int]:
    """Count how many candidates exist for every required position."""
    counts: dict[str, int] = {}
    for _name, position, _cost, _score in players:
        counts[position] = counts.get(position, 0) + 1
    return counts


def one_per_position(
    candidates: list[Player],
) -> list[Player]:
    """Keep the first candidate seen for each unique position."""
    taken: set[str] = set()
    kept: list[Player] = []
    for player in candidates:
        if player[1] not in taken:
            taken.add(player[1])
            kept.append(player)
    return kept


def affordable(
    players: list[Player],
    remaining: int,
) -> list[Player]:
    return [player for player in players if player[2] <= remaining]


def totals(
    picked: list[Player],
) -> tuple[int, int]:
    cost = sum(player[2] for player in picked)
    score = sum(player[3] for player in picked)
    return cost, score


def draft(
    players: list[Player],
    budget: int,
) -> list[str]:
    metrics = value_metric(players)
    ranked: list[Player] = sorted(players, key=lambda p: metrics[p[0]], reverse=True)
    chosen: list[Player] = []
    spent = 0
    for player in one_per_position(ranked):
        if spent + player[2] <= budget:
            chosen.append(player)
            spent += player[2]
    covered = {player[1] for player in chosen}
    for position in position_counts(players):
        if position in covered:
            continue
        options = affordable([p for p in players if p[1] == position], budget - spent)
        if options:
            cheapest = min(options, key=lambda p: p[2])
            chosen.append(cheapest)
            spent += cheapest[2]
            covered.add(position)
    return [player[0] for player in chosen]


def roster_report(
    names: list[str],
    players: list[Player],
) -> str:
    lookup: dict[str, Player] = {player[0]: player for player in players}
    picked = [lookup[name] for name in names]
    cost, score = totals(picked)
    lines = [f"{p[0]:<8}{p[1]:<10}{p[2]:>4}{p[3]:>4}" for p in picked]
    lines.append(f"cost {cost} of budget, score {score}")
    return "\n".join(lines)


def main() -> None:
    squad: list[Player] = [
        ("tom", "forward", 10, 20),
        ("ana", "forward", 6, 15),
        ("kim", "midfield", 8, 18),
        ("raj", "midfield", 4, 9),
        ("eve", "keeper", 5, 11),
        ("lou", "keeper", 3, 6),
    ]
    print(roster_report(draft(squad, 20), squad))


if __name__ == "__main__":
    main()

