import sys

Commit = tuple[str, str, int]
FileSet = set[str]
FileSets = dict[str, FileSet]
Totals = dict[str, int]


def group_files_by_author(commits: list[Commit]) -> FileSets:
    """Map each author to the set of distinct files they touched."""
    grouped: FileSets = {}
    for author, filename, lines in commits:
        if lines < 0:
            raise ValueError(f"negative line count for {author} on {filename}")
        grouped.setdefault(author, set()).add(filename)
    return grouped


def find_broad_contributors(author_files: FileSets, threshold: int = 3) -> list[str]:
    """Authors who modified at least `threshold` distinct files, alphabetically."""
    broad: list[str] = []
    for author, files in author_files.items():
        if len(files) >= threshold:
            broad.append(author)
    return sorted(broad)


def total_lines_by_author(commits: list[Commit]) -> Totals:
    """Sum of modified lines per author, used for the report."""
    totals: Totals = {}
    for author, _filename, lines in commits:
        totals[author] = totals.get(author, 0) + lines
    return totals


def evaluate(commits):
    author_files = group_files_by_author(commits)
    broad_contributors = find_broad_contributors(author_files)
    return author_files, broad_contributors


def parse_commit_line(line: str) -> Commit:
    """Parse 'author,file,lines' into a commit tuple."""
    parts = [field.strip() for field in line.split(",")]
    if len(parts) != 3:
        raise ValueError(f"malformed commit record: {line!r}")
    author, filename, lines = parts
    return author, filename, int(lines)


def read_commits(stream) -> list[Commit]:
    records: list[Commit] = []
    for line in stream:
        if line.strip():
            records.append(parse_commit_line(line))
    return records


def format_report(author_files: FileSets, broad: list[str], totals: Totals) -> str:
    lines: list[str] = ["author                 files  lines  broad"]
    for author in sorted(author_files):
        flag = "yes" if author in broad else "no"
        lines.append(
            f"{author:<22} {len(author_files[author]):>5} {totals[author]:>6}  {flag}"
        )
    lines.append(f"broad contributors: {', '.join(broad) if broad else '(none)'}")
    return "\n".join(lines)


def main(argv: list[str]) -> int:
    if len(argv) > 1:
        with open(argv[1], encoding="utf-8") as handle:
            commits = read_commits(handle)
    else:
        commits = [
            ("dev", "index", 10),
            ("dev", "router", 4),
            ("dev", "views", 22),
            ("ana", "index", 7),
            ("ana", "tests", 31),
        ]
    author_files, broad = evaluate(commits)
    print(format_report(author_files, broad, total_lines_by_author(commits)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

