Scan = tuple[str, str, int]
Stop = tuple[str, int]
Itinerary = list[Stop]
Grouped = dict[str, Itinerary]
Route = list[str]
Routes = dict[str, Route]


def parse_scans(rows: list[str]) -> list[Scan]:
    """Turn 'bag,airport,timestamp' text rows into scan tuples."""
    parsed: list[Scan] = []
    for row in rows:
        fields = [part.strip() for part in row.split(",")]
        if len(fields) != 3:
            raise ValueError(f"malformed scan row: {row!r}")
        bag, airport, stamp = fields
        parsed.append((bag, airport.upper(), int(stamp)))
    return parsed


def group_scans(scans: list[Scan]) -> Grouped:
    """Collect every (airport, timestamp) pair seen for each bag."""
    grouped: Grouped = {}
    for bag, airport, stamp in scans:
        grouped.setdefault(bag, []).append((airport, stamp))
    return grouped


def order_route(stops: Itinerary) -> Route:
    """Sort the stops chronologically and keep only the airport codes."""
    ordered: Itinerary = sorted(stops, key=lambda stop: stop[1])
    return [airport for airport, _ in ordered]


def track(scans: list[Scan]) -> Routes:
    """Map each bag identifier to its chronological list of airports."""
    grouped = group_scans(scans)
    routes: Routes = {}
    for bag, stops in grouped.items():
        routes[bag] = order_route(stops)
    return routes


def leg_counts(routes: Routes) -> dict[str, int]:
    """How many flight legs each bag travelled (stops minus one)."""
    legs: dict[str, int] = {}
    for bag, route in routes.items():
        legs[bag] = max(len(route) - 1, 0)
    return legs


def airport_traffic(routes: Routes) -> dict[str, int]:
    """How many bag scans each airport handled."""
    traffic: dict[str, int] = {}
    for route in routes.values():
        for airport in route:
            traffic[airport] = traffic.get(airport, 0) + 1
    return traffic


def format_report(routes: Routes) -> list[str]:
    legs = leg_counts(routes)
    lines: list[str] = []
    for bag in sorted(routes):
        path = " -> ".join(routes[bag])
        lines.append(f"{bag}: {path} ({legs[bag]} legs)")
    return lines


def main() -> None:
    rows: list[str] = [
        "bag1,jfk,12",
        "bag1,ams,40",
