OrderGroups = dict[bool, OrderList]

PREP_TIMES: dict[str, int] = {"espresso": 1, "latte": 3, "blended": 5}


def prep_time(drink: str) -> int:
    """Return the preparation time in minutes for a drink type."""
    key = drink.strip().lower()
    if key not in PREP_TIMES:
        raise ValueError(f"unknown drink type: {drink!r}")
    return PREP_TIMES[key]


def group_by_loyalty(orders: OrderList) -> OrderGroups:
    """Split orders into loyalty members and everyone else."""
    groups: OrderGroups = {True: [], False: []}
    for order in orders:
        groups[bool(order[2])].append(order)
    return groups


def prioritize(orders: OrderList) -> list[int]:
    """Loyalty members first, then fastest drinks; returns order identifiers."""
    groups = group_by_loyalty(orders)
    queue: list[int] = []
    for loyal in (True, False):
        batch: OrderList = sorted(groups[loyal], key=lambda order: prep_time(order[1]))
        queue.extend(order[0] for order in batch)
    return queue


def count_drinks(orders: OrderList) -> dict[str, int]:
    """Tally how many of each drink type the queue contains."""
    counts: dict[str, int] = {}
    for _, drink, _loyal in orders:
        key = drink.strip().lower()
        counts[key] = counts.get(key, 0) + 1
    return counts


def wait_times(orders: OrderList) -> dict[int, int]:
    """Cumulative minutes until each order is finished, following the queue."""
    drinks: dict[int, str] = {oid: drink for oid, drink, _ in orders}
    waits: dict[int, int] = {}
    elapsed = 0
    for oid in prioritize(orders):
        elapsed += prep_time(drinks[oid])
        waits[oid] = elapsed
    return waits


def format_report(orders: OrderList) -> list[str]:
    """Human readable queue report, one line per order plus a summary."""
    loyalty: dict[int, bool] = {oid: loyal for oid, _, loyal in orders}
    drinks: dict[int, str] = {oid: drink for oid, drink, _ in orders}
    waits = wait_times(orders)
    lines: list[str] = []
    for position, oid in enumerate(prioritize(orders), start=1):
        tag = "member" if loyalty[oid] else "guest"
        lines.append(
            f"{position}. order {oid} ({drinks[oid]}, {tag}) ready at {waits[oid]} min"
        )
    totals = count_drinks(orders)
    summary = ", ".join(f"{name} x{totals[name]}" for name in sorted(totals))
    lines.append(f"totals: {summary}")
    return lines


def main() -> None:
    orders: OrderList = [
        (1, "espresso", True),
        (2, "blended", True),
        (3, "latte", False),
        (4, "espresso", False),
        (5, "latte", True),
    ]
    print(prioritize(orders))
    for line in format_report(orders):
        print(line)


if __name__ == "__main__":
    main()

