Person = tuple[str, str]
Match = tuple[str, str]
Names = list[str]
NameGroups = dict[str, Names]


def normalize(
    people: list[Person],
) -> list[Person]:
    """Strip and lower-case each name/blood-type pair, rejecting unknown types."""
    cleaned: list[Person] = []
    for name, blood_type in people:
        key = blood_type.strip().lower()
        if key not in VALID_TYPES:
            raise ValueError(f"unknown blood type for {name!r}: {blood_type!r}")
        cleaned.append((name.strip(), key))
    return cleaned


def group_by_blood_type(people: list[Person]) -> NameGroups:
    """Map every blood type to the names of the individuals carrying it."""
    groups: NameGroups = {}
    for name, blood_type in people:
        groups.setdefault(blood_type, []).append(name)
    return groups


def match_groups(
    donor_groups: NameGroups,
    recipient_groups: NameGroups,
) -> list[Match]:
    """Pair donors with recipients sharing the exact same blood type."""
    matches: list[Match] = []
    for blood_type in sorted(donor_groups):
        recipients: Names = recipient_groups.get(blood_type, [])
        for donor, recipient in zip(donor_groups[blood_type], recipients):
            matches.append((donor, recipient))
    return matches


def pair(donors, recipients):
    """Return donor/recipient name pairs built from exact blood type matches."""
    donor_groups = group_by_blood_type(normalize(donors))
    recipient_groups = group_by_blood_type(normalize(recipients))
    return match_groups(donor_groups, recipient_groups)


def count_unmatched(
    people: list[Person],
    matched_names: set[str],
) -> dict[str, int]:
    """Count, per blood type, how many individuals were left without a partner."""
    leftovers: dict[str, int] = {}
    for name, blood_type in normalize(people):
        if name not in matched_names:
            leftovers[blood_type] = leftovers.get(blood_type, 0) + 1
    return leftovers


def format_report(
    matches: list[Match],
    waiting: dict[str, int],
) -> str:
    lines: list[str] = [f"{donor} -> {recipient}" for donor, recipient in matches]
    for blood_type in sorted(waiting):
        lines.append(f"waiting ({blood_type}): {waiting[blood_type]}")
    return "\n".join(lines)


def main() -> None:
    donors: list[Person] = [
        ("dan", "positive"),
        ("erin", "negative"),
        ("frank", "positive"),
    ]
    recipients: list[Person] = [("ray", "positive"), ("sam", "ab")]
    matches = pair(donors, recipients)
    print(matches)
    paired_donors = {donor for donor, _ in matches}
    paired_recipients = {recipient for _, recipient in matches}
    print(format_report(matches, count_unmatched(donors, paired_donors)))
    print(format_report([], count_unmatched(recipients, paired_recipients)))


if __name__ == "__main__":
    main()

