YearPop = tuple[int, int]
History = list[YearPop]
PopulationTable = dict[str, History]
CitySummary = tuple[str, int, int]


def parse_records(records: list[str]) -> PopulationTable:
    """Turn ``city,year,population`` strings into per-city histories."""
    table: PopulationTable = {}
    for line in records:
        fields: list[str] = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"expected three comma separated fields: {line!r}")
        city, year_text, population_text = fields
        if not city:
            raise ValueError(f"missing city name in record: {line!r}")
        entry: tuple[int, int] = (int(year_text), int(population_text))
        table.setdefault(city, []).append(entry)
    for history in table.values():
        history.sort()
    return table


def max_population(history: History) -> int:
    """Largest population found in a list of (year, population) pairs."""
    if not history:
        raise ValueError("cannot take the maximum of an empty history")
    return max(population for _year, population in history)


def population_growth(history: History) -> int:
    """Population change between the earliest and the latest recorded year."""
    if not history:
        raise ValueError("cannot measure growth of an empty history")
    years: list[int] = [year for year, _population in history]
    by_year: dict[int, int] = {year: population for year, population in history}
    return by_year[max(years)] - by_year[min(years)]


def track(
    records: list[str],
) -> list[CitySummary]:
    """Summarise each city as (name, maximum population, total growth)."""
    table = parse_records(records)
    summaries: list[CitySummary] = []
    for city in sorted(table):
        history = table[city]
        summaries.append((city, max_population(history), population_growth(history)))
    return summaries


def format_summaries(
    summaries: list[CitySummary],
) -> list[str]:
    """Render summaries as aligned, human readable report lines."""
    width = max((len(city) for city, _peak, _growth in summaries), default=0)
    lines: list[str] = []
    for city, peak, growth in summaries:
        lines.append(f"{city:<{width}}  peak={peak:>9,}  growth={growth:>+10,}")
    return lines


def main() -> None:
    raw: list[str] = [
        "Boston, 2000, 589141",
        "Boston, 2010, 617594",
        "Detroit, 2000, 951270",
        "Detroit, 2010, 713777",
        "Austin, 2000, 656562",
        "Austin, 2010, 790390",
    ]
    summaries = track(raw)
    for line in format_summaries(summaries):
        print(line)
    totals: dict[str, int] = {city: growth for city, _peak, growth in summaries}
    print(f"net change across {len(totals)} cities: {sum(totals.values()):+,}")


if __name__ == "__main__":
    main()

