Request = tuple[str, int]
Timestamps = list[int]

WINDOW_SECONDS = 10
MAX_REQUESTS_PER_WINDOW = 3


def parse_log_line(line: str) -> tuple[str, int]:
    """Turn a raw "<ip> <timestamp>" log line into a request tuple."""
    parts = line.split()
    if len(parts) != 2:
        raise ValueError(f"malformed log line: {line!r}")
    ip, raw_timestamp = parts
    return ip, int(raw_timestamp)


def parse_log(
    lines: list[str],
) -> list[Request]:
    """Parse a whole log, ignoring blank lines."""
    return [parse_log_line(line) for line in lines if line.strip()]


def group_by_ip(
    requests: list[Request],
) -> dict[str, Timestamps]:
    """Group request timestamps by the ip address that issued them."""
    grouped: dict[str, Timestamps] = {}
    for ip, timestamp in requests:
        grouped.setdefault(ip, []).append(timestamp)
    return grouped


def is_flooding(timestamps: list[int]) -> bool:
    """True if more than three requests ever fall inside a ten second window."""
    ordered = sorted(timestamps)
    for start in range(len(ordered) - MAX_REQUESTS_PER_WINDOW):
        span = ordered[start + MAX_REQUESTS_PER_WINDOW] - ordered[start]
        if span < WINDOW_SECONDS:
            return True
    return False


def request_counts(
    requests: list[Request],
) -> dict[str, int]:
    """How many requests each ip address made in total."""
    counts: dict[str, int] = {}
    for ip, _timestamp in requests:
        counts[ip] = counts.get(ip, 0) + 1
    return counts


def throttle(
    requests: list[Request],
) -> list[str]:
    """Return the ip addresses that exceeded the rate limit."""
    banned: list[str] = []
    for ip, timestamps in group_by_ip(requests).items():
        if is_flooding(timestamps):
            banned.append(ip)
    return sorted(banned)


def format_report(
    banned: list[str],
    counts: dict[str, int],
) -> str:
    if not banned:
        return "no ip addresses banned"
    rows = [f"{ip} banned after {counts[ip]} requests" for ip in banned]
    return "\n".join(rows)


def main() -> None:
    log_lines: list[str] = [
        "10.0.0.1 1", "10.0.0.1 2", "10.0.0.1 3", "10.0.0.1 4",
        "10.0.0.2 5", "10.0.0.2 40", "10.0.0.2 41", "10.0.0.2 42",
        "10.0.0.3 7", "10.0.0.3 20", "10.0.0.3 31", "10.0.0.3 45",
        "10.0.0.4 12", "10.0.0.4 13", "10.0.0.4 14", "10.0.0.4 30",
    ]
    requests = parse_log(log_lines)
    print(format_report(throttle(requests), request_counts(requests)))


if __name__ == "__main__":
    main()

