        if span < WINDOW_SECONDS:
            return True
    return False


def request_counts(
    requests: List[Request],
) -> Dict[str, int]:
    """How many requests each ip address made in total."""
    counts: Dict[str, int] = {}
    for ip, _timestamp in requests:
        counts[ip] = counts.get(ip, 0) + 1
    return counts


def throttle(
    requests: List[Request],
) -> List[str]:
    """Return the ip addresses that exceeded the rate limit."""
    banned: List[str] = []
    for ip, timestamps in group_by_ip(requests).items():
        if is_flooding(timestamps):
            banned.append(ip)
    return sorted(banned)


def format_report(
    banned: List[str],
    counts: Dict[str, int],
) -> str:
    if not banned:
        return "no ip addresses banned"
    rows = [f"{ip} banned after {counts[ip]} requests" for ip in banned]
    return "\n".join(rows)


def main() -> None:
    log_lines: List[str] = [
        "10.0.0.1 1", "10.0.0.1 2", "10.0.0.1 3", "10.0.0.1 4",
        "10.0.0.2 5", "10.0.0.2 40", "10.0.0.2 41", "10.0.0.2 42",
        "10.0.0.3 7", "10.0.0.3 20", "10.0.0.3 31", "10.0.0.3 45",
        "10.0.0.4 12", "10.0.0.4 13", "10.0.0.4 14", "10.0.0.4 30",
    ]
    requests = parse_log(log_lines)
    print(format_report(throttle(requests), request_counts(requests)))


