def ingredient_cost(ingredients: Ingredients, prices: PriceTable) -> int:
    """Sum the price of every ingredient in the list."""
    total = 0
    for item in ingredients:
        total += prices[item]
    return total


def missing_ingredients(
    ingredients: Ingredients,
    prices: PriceTable,
) -> list[str]:
    """Return the ingredients that have no known price, in order of appearance."""
    missing: list[str] = []
    for item in ingredients:
        if item not in prices and item not in missing:
            missing.append(item)
    return missing


def estimate(
    recipes: dict[str, Ingredients],
    prices: PriceTable,
) -> tuple[CostTable, RecipeNames]:
    """Price every recipe, separating the ones with unknown ingredients."""
    costs: CostTable = {}
    unpriceable: RecipeNames = []
    for name in sorted(recipes):
        ingredients = recipes[name]
        if missing_ingredients(ingredients, prices):
            unpriceable.append(name)
        else:
            costs[name] = ingredient_cost(ingredients, prices)
    return costs, unpriceable


def cheapest_recipes(costs: CostTable, limit: int) -> list[RankedPair]:
    """Return up to `limit` recipes ordered by cost, then by name."""
    ranked = sorted(costs.items(), key=lambda pair: (pair[1], pair[0]))
    return ranked[:limit]


def format_report(
    costs: CostTable,
    unpriceable: RecipeNames,
    recipes: dict[str, Ingredients],
    prices: PriceTable,
) -> str:
    lines: list[str] = []
    for name, cost in cheapest_recipes(costs, 3):
        lines.append(f"{name}: {cost}")
    for name in unpriceable:
        gaps = missing_ingredients(recipes[name], prices)
        lines.append(f"{name}: no price for {', '.join(gaps)}")
    return "\n".join(lines)


