        "omelette": ["eggs", "butter", "cheese"],
        "pancakes": ["flour", "eggs", "sugar", "butter", "milk"],
    }
    costs, unpriceable = estimate(recipes, prices)
    print(format_report(costs, unpriceable, recipes, prices))
