"""Organize requests for popular library books and report the queues."""

Entry = tuple[str, int]
Queue = list[Entry]
Request = tuple[str, str, int]
Assignment = tuple[str, str]


def group_requests(
    requests: list[Request],
) -> dict[str, Queue]:
    """Map every book title to the (user id, day) pairs requested for it."""
    queues: dict[str, Queue] = {}
    for title, user, day in requests:
        if not title or not user:
            raise ValueError("book title and user id must be non-empty")
        if day < 1:
            raise ValueError(f"invalid request day for {title!r}: {day}")
        queues.setdefault(title, []).append((user, day))
    return queues


def sort_by_day(entries: Queue) -> Queue:
    """Order (user id, day) pairs so that the earliest request comes first."""
    return sorted(entries, key=lambda entry: entry[1])


def first_in_line(entries: Queue) -> Entry:
    """Return the single entry whose request day is the smallest."""
    ordered = sort_by_day(entries)
    return ordered[0]


def count_requests(
    queues: dict[str, Queue],
) -> dict[str, int]:
    """Count how many people asked for each title."""
    return {title: len(entries) for title, entries in queues.items()}


def manage(
    requests: list[Request],
) -> list[Assignment]:
    """Pair each title with the user id of the person who is first in line."""
    queues = group_requests(requests)
    assignments: list[Assignment] = []
    for title in sorted(queues):
        user, _day = first_in_line(queues[title])
        assignments.append((title, user))
    return assignments


def day_span(
    requests: list[Request],
) -> tuple[int, int]:
    """Return the first and last day covered by the requests."""
    days: list[int] = [day for _title, _user, day in requests]
    return min(days), max(days)


def format_report(
    assignments: list[Assignment],
    counts: dict[str, int],
    span: tuple[int, int],
) -> list[str]:
    """Turn the assignments into human readable report lines."""
    lines = [f"Requests from day {span[0]} to day {span[1]}"]
    for title, user in assignments:
        waiting = counts[title] - 1
        lines.append(f"{title}: {user} is first in line ({waiting} still waiting)")
    return lines


def main() -> None:
    requests: list[Request] = [
        ("Dune", "userB", 2),
        ("Dune", "userA", 1),
        ("Hamlet", "userC", 5),
        ("Hamlet", "userD", 3),
        ("Hamlet", "userA", 4),
        ("Ulysses", "userE", 7),
    ]
    counts = count_requests(group_requests(requests))
    for line in format_report(manage(requests), counts, day_span(requests)):
        print(line)


if __name__ == "__main__":
    main()

