SIGNS: dict[str, int] = {
    "deposit": 1,
    "credit": 1,
    "withdrawal": -1,
    "debit": -1,
}


def _parse_line(entry: str) -> tuple[str, int]:
    fields = [field.strip() for field in entry.split(",")]
    if len(fields) != 3:
        raise ValueError(f"expected 'account, amount, type' but got {entry!r}")
    account, raw_amount, kind = fields
    kind = kind.lower()
    if kind not in SIGNS:
        raise ValueError(f"unknown transaction type {kind!r} in {entry!r}")
    return account, int(raw_amount) * SIGNS[kind]


def group_by_account(transactions: list[str]):
    """Map every account name to the signed amounts recorded for it."""
    ledger = {}
    for entry in transactions:
        account, amount = _parse_line(entry)
        amounts: list[int] = ledger.setdefault(account, [])
        amounts.append(amount)
    return ledger


def total(amounts: list[int]) -> int:
    running = 0
    for amount in amounts:
        running += amount
    return running


def reconcile(transactions: list[str]):
    """Return (account, balance) pairs ordered by descending balance."""
    ledger = group_by_account(transactions)
    balances = [(account, total(amounts)) for account, amounts in ledger.items()]
    balances.sort(key=lambda pair: (-pair[1], pair[0]))
    return balances


def count_types(transactions: list[str]):
    """Tally how often each transaction type appears in the ledger."""
    counts: dict[str, int] = {}
    for entry in transactions:
        kind = entry.split(",")[-1].strip().lower()
        counts[kind] = counts.get(kind, 0) + 1
    return counts


def format_row(balance: tuple[str, int]) -> str:
    account, amount = balance
    return f"{account:<12}{amount:>8}"


def format_report(balances, counts: dict[str, int]) -> str:
    rows: list[str] = [format_row(balance) for balance in balances]
    rows.append("-" * 20)
    for kind in sorted(counts):
        rows.append(f"{kind:<12}{counts[kind]:>8}")
    return "\n".join(rows)


def main() -> None:
    ledger: list[str] = [
        "alice, 50, deposit",
        "bob, 120, deposit",
        "alice, 20, withdrawal",
        "carol, 300, credit",
        "bob, 45, debit",
        "carol, 100, withdrawal",
        "alice, 15, deposit",
    ]
    balances = reconcile(ledger)
    print(format_report(balances, count_types(ledger)))


if __name__ == "__main__":
    main()

