"""Restocking report built from shipment and sales records."""

Entry = tuple[str, int]


def aggregate(
    entries: list[Entry],
) -> dict[str, int]:
    """Sum the quantities of every item appearing in ``entries``."""
    totals: dict[str, int] = {}
    for name, quantity in entries:
        totals[name] = totals.get(name, 0) + quantity
    return totals


def net_quantities(
    shipped: dict[str, int],
    sold: dict[str, int],
) -> dict[str, int]:
    """Subtract sold quantities from shipped quantities, item by item."""
    remaining = dict(shipped)
    for name, quantity in sold.items():
        remaining[name] = remaining.get(name, 0) - quantity
    return remaining


def inventory(
    shipments: list[Entry],
    sales: list[Entry],
) -> list[str]:
    """Return the items whose net quantity has dropped to zero or below."""
    remaining = net_quantities(aggregate(shipments), aggregate(sales))
    return [name for name, quantity in remaining.items() if quantity <= 0]


def parse_entries(
    records: list[str],
) -> list[Entry]:
    """Turn ``"name:quantity"`` records into item/quantity tuples."""
    parsed: list[Entry] = []
    for record in records:
        name, _, raw_quantity = record.partition(":")
        quantity = int(raw_quantity)
        if quantity < 0:
            raise ValueError(f"negative quantity in record {record!r}")
        parsed.append((name.strip(), quantity))
    return parsed


def format_report(
    remaining: dict[str, int],
    restock: list[str],
) -> str:
    """Render the stock levels, flagging the items that need restocking."""
    flagged = set(restock)
    lines: list[str] = []
    for name in sorted(remaining):
        marker = " <- restock" if name in flagged else ""
        lines.append(f"{name:<10}{remaining[name]:>4}{marker}")
    return "\n".join(lines)


def main() -> None:
    shipment_records = ["apple: 10", "banana: 24", "cherry: 5", "apple: 6"]
    sales_records = ["apple: 16", "banana: 9", "cherry: 7"]

    shipments = parse_entries(shipment_records)
    sales = parse_entries(sales_records)

    restock = inventory(shipments, sales)
    remaining = net_quantities(aggregate(shipments), aggregate(sales))

    print(format_report(remaining, restock))
    print("\nNeed restocking:", ", ".join(sorted(restock)) or "nothing")


if __name__ == "__main__":
    main()

