from typing import Dict, List, Tuple

ShareTable = Dict[str, int]
Ride = Tuple[str, int, str]
Balance = Tuple[str, int]
Balances = List[Balance]
Report = List[str]


def parse_passengers(passenger_field: str) -> List[str]:
    """Split a comma separated passenger field into clean names."""
    names = [part.strip() for part in passenger_field.split(",")]
    return [name for name in names if name]


def divide_fare(total: int, passenger_field: str) -> ShareTable:
    """Divide a fare equally, giving any leftover to the first passengers."""
    passengers = parse_passengers(passenger_field)
    if not passengers:
        raise ValueError("a ride needs at least one passenger")
    base, extra = divmod(total, len(passengers))
    shares: ShareTable = {}
    for position, name in enumerate(passengers):
        shares[name] = shares.get(name, 0) + base + (1 if position < extra else 0)
    return shares


def merge_shares(all_shares: List[ShareTable]) -> ShareTable:
    """Accumulate several per-trip share tables into one balance table."""
    totals: ShareTable = {}
    for shares in all_shares:
        for name, amount in shares.items():
            totals[name] = totals.get(name, 0) + amount
    return totals


def validate_ride(ride: Ride) -> None:
    trip_id, fare, passenger_field = ride
    if not trip_id.strip():
        raise ValueError("every ride needs a trip identifier")
    if fare < 0:
        raise ValueError(f"trip {trip_id} has a negative fare")
    if not passenger_field.strip():
        raise ValueError(f"trip {trip_id} has no passengers")


def split(rides: List[Ride]) -> Balances:
    """Return each passenger and the total amount owed across all rides."""
    per_trip: List[ShareTable] = []
    for ride in rides:
        validate_ride(ride)
        _, fare, passenger_field = ride
        per_trip.append(divide_fare(fare, passenger_field))
    totals = merge_shares(per_trip)
    return sorted(totals.items(), key=lambda item: (-item[1], item[0]))


def format_report(owed: Balances) -> Report:
    lines: Report = []
    width = max((len(name) for name, _ in owed), default=0)
    for name, amount in owed:
        lines.append(f"{name.ljust(width)} owes {amount}")
    total = sum(amount for _, amount in owed)
    lines.append(f"{'TOTAL'.ljust(width)}      {total}")
    return lines


def main() -> None:
    rides: List[Ride] = [
        ("R1", 10, "ana,ben"),
        ("R2", 30, "ana,ben,cara"),
        ("R3", 7, "ben,cara,dan"),
        ("R4", 12, "ana"),
    ]
    for line in format_report(split(rides)):
        print(line)


if __name__ == "__main__":
    main()

