Review = tuple[str, int]
Ratings = list[int]


def group_ratings(
    reviews: list[Review],
) -> dict[str, Ratings]:
    """Build a mapping from product name to the list of ratings it received."""
    grouped: dict[str, Ratings] = {}
    for name, rating in reviews:
        grouped.setdefault(name, []).append(rating)
    return grouped


def count_fives(ratings: Ratings) -> int:
    """Count how many ratings in the list are exactly five."""
    total = 0
    for rating in ratings:
        if rating == 5:
            total += 1
    return total


def validate_reviews(reviews: list[Review]) -> None:
    """Reject entries whose rating is outside the one-to-five scale."""
    for name, rating in reviews:
        if not 1 <= rating <= 5:
            raise ValueError(f"rating for {name!r} out of range: {rating}")


def aggregate(reviews):
    """Return the names of products with at least three ratings of five."""
    validate_reviews(reviews)
    grouped = group_ratings(reviews)
    top_products: list[str] = []
    for name, ratings in grouped.items():
        if count_fives(ratings) >= 3:
            top_products.append(name)
    return top_products


def five_star_counts(
    reviews: list[Review],
) -> dict[str, int]:
    """Summarise how many five-star ratings each product collected."""
    grouped = group_ratings(reviews)
    return {name: count_fives(ratings) for name, ratings in grouped.items()}


def rating_spread(ratings: Ratings) -> tuple[int, int]:
    """Return the lowest and highest rating in the list."""
    return min(ratings), max(ratings)


def format_report(
    reviews: list[Review],
) -> list[str]:
    """Produce one human-readable line per product, best performers first."""
    grouped = group_ratings(reviews)
    counts: dict[str, int] = five_star_counts(reviews)
    winners = set(aggregate(reviews))
    lines: list[str] = []
    for name in sorted(grouped, key=lambda p: (-counts[p], p)):
        low, high = rating_spread(grouped[name])
        mark = "TOP" if name in winners else "   "
        lines.append(
            f"{mark} {name:<12} reviews={len(grouped[name]):>2} "
            f"fives={counts[name]:>2} range={low}-{high}"
        )
    return lines


def main() -> None:
    reviews: list[Review] = [
        ("thermos", 5),
        ("thermos", 5),
        ("thermos", 4),
        ("thermos", 5),
        ("lamp", 5),
        ("lamp", 3),
        ("lamp", 5),
        ("notebook", 5),
        ("notebook", 5),
        ("notebook", 5),
        ("notebook", 5),
        ("kettle", 2),
    ]
    for line in format_report(reviews):
        print(line)
    print("consistently top rated:", aggregate(reviews))


if __name__ == "__main__":
    main()

