Message = tuple[str, int]
MessageList = list[Message]
Threads = dict[str, MessageList]
SenderList = list[str]
Timeline = dict[str, SenderList]


def parse_message(raw: str) -> tuple[str, str, int]:
    parts = [field.strip() for field in raw.split(",")]
    if len(parts) != 3:
        raise ValueError(f"malformed message record: {raw!r}")
    thread, sender, stamp = parts
    if not thread or not sender:
        raise ValueError(f"missing thread or sender: {raw!r}")
    return thread, sender, int(stamp)


def group_by_thread(emails: list[str]) -> Threads:
    threads: Threads = {}
    for raw in emails:
        thread, sender, timestamp = parse_message(raw)
        threads.setdefault(thread, []).append((sender, timestamp))
    return threads


def senders_in_order(messages: MessageList) -> list[str]:
    ordered = sorted(messages, key=lambda message: message[1])
    return [sender for sender, _timestamp in ordered]


def organize(emails: list[str]) -> Timeline:
    grouped = group_by_thread(emails)
    timeline: Timeline = {}
    for thread in sorted(grouped):
        timeline[thread] = senders_in_order(grouped[thread])
    return timeline


def count_contributions(timeline: Timeline) -> dict[str, int]:
    totals: dict[str, int] = {}
    for senders in timeline.values():
        for sender in senders:
            totals[sender] = totals.get(sender, 0) + 1
    return totals


def format_timeline(timeline: Timeline) -> list[str]:
    return [f"{thread}: {' -> '.join(senders)}" for thread, senders in timeline.items()]


def format_contributions(
    totals: dict[str, int],
) -> list[str]:
    ranked = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    return [f"{sender} sent {count} message(s)" for sender, count in ranked]


def main() -> None:
    inbox: list[str] = [
        "thread-1, Alice, 1",
        "thread-1, Bob, 2",
        "thread-2, Carol, 10",
        "thread-1, Alice, 5",
        "thread-2, Dave, 3",
        "thread-3, Erin, 7",
        "thread-2, Carol, 8",
    ]
    timeline = organize(inbox)
    for line in format_timeline(timeline):
        print(line)

    print("-" * 30)
    totals = count_contributions(timeline)
    for line in format_contributions(totals):
        print(line)

    busiest: tuple[str, int] = max(totals.items(), key=lambda item: (item[1], item[0]))
    print(f"Most active participant: {busiest[0]} ({busiest[1]})")


if __name__ == "__main__":
    main()

