Record = tuple[str, str, int]
Stop = tuple[str, int]
StopList = list[Stop]
Timetable = dict[str, StopList]
Duration = tuple[str, int]
DurationList = list[Duration]


def validate_records(
    records: list[Record],
) -> list[Record]:
    """Reject malformed rows early with a clear message."""
    checked: list[Record] = []
    for index, row in enumerate(records):
        if len(row) != 3:
            raise ValueError(f"row {index} must hold route, stop and minutes")
        route, stop, minutes = row
        if not isinstance(minutes, int) or isinstance(minutes, bool):
            raise ValueError(f"row {index}: minutes must be an int, got {minutes!r}")
        if minutes < 0:
            raise ValueError(f"row {index}: minutes must not be negative")
        checked.append((str(route), str(stop), minutes))
    return checked


def group_by_route(records: list[Record]) -> Timetable:
    """Map each route name to its list of (stop, minutes) pairs."""
    grouped: dict[str, StopList] = {}
    for route, stop, minutes in validate_records(records):
        grouped.setdefault(route, []).append((stop, minutes))
    for stops in grouped.values():
        stops.sort(key=lambda pair: pair[1])
    return grouped


def route_duration(stops: StopList) -> int:
    """The total duration of a route is the largest offset among its stops."""
    if not stops:
        return 0
    minutes: list[int] = [minute for _, minute in stops]
    return max(minutes)


def schedule(routes: list[Record]) -> DurationList:
    timetable = group_by_route(routes)
    totals: DurationList = []
    for route, stops in timetable.items():
        totals.append((route, route_duration(stops)))
    return totals


def count_stops(timetable: Timetable) -> dict[str, int]:
    return {route: len(stops) for route, stops in timetable.items()}


def format_report(timetable: Timetable, totals: DurationList) -> list[str]:
    counts: dict[str, int] = count_stops(timetable)
    lines: list[str] = []
    width = max((len(route) for route, _ in totals), default=0)
    for route, duration in sorted(totals, key=lambda item: -item[1]):
        lines.append(f"{route:<{width}}  {duration:>3} min  {counts[route]} stops")
    return lines


def main() -> None:
    routes: list[Record] = [
        ("Red Line", "Central", 0),
        ("Red Line", "Museum", 5),
        ("Red Line", "Harbour", 15),
        ("Red Line", "Airport", 10),
        ("Bus 12", "Depot", 0),
        ("Bus 12", "Market", 22),
        ("Tram 3", "Hillside", 8),
    ]
    totals = schedule(routes)
    print(totals)
    for line in format_report(group_by_route(routes), totals):
        print(line)


if __name__ == "__main__":
    main()

