"""Evaluate movie performance across theatre screens."""

TicketRow = tuple[str, int, int]
Sales = list[int]
Summary = tuple[str, int, float]
ScreenPeak = tuple[int, int]
ScreenKey = tuple[str, int]
RowList = list[TicketRow]
Grouped = dict[str, Sales]
PeakMap = dict[str, ScreenPeak]
SummaryList = list[Summary]


def parse_rows(raw_lines: list[str]) -> RowList:
    """Turn "title,screen,sold" text lines into structured ticket rows."""
    rows: RowList = []
    for line in raw_lines:
        if not line.strip():
            continue
        title, screen, sold = (part.strip() for part in line.split(","))
        rows.append((title, int(screen), int(sold)))
    return rows


def group_by_movie(tickets: RowList) -> Grouped:
    """Group ticket sales by movie title, keeping one entry per screen."""
    grouped: Grouped = {}
    for title, screen, sold in tickets:
        if sold < 0:
            raise ValueError(f"negative sales for {title!r} on screen {screen}")
        grouped.setdefault(title, []).append(sold)
    return grouped


def totals_and_average(sales: Sales) -> tuple[int, float]:
    """Return the sum of the sales and the average sales per screen."""
    if not sales:
        return (0, 0.0)
    total = sum(sales)
    return (total, total / len(sales))


def busiest_screen(tickets: RowList) -> PeakMap:
    """Map each title to the (screen, sales) pair with the highest sales."""
    per_screen: dict[ScreenKey, int] = {}
    for title, screen, sold in tickets:
        key = (title, screen)
        per_screen[key] = per_screen.get(key, 0) + sold

    peaks: PeakMap = {}
    for (title, screen), sold in per_screen.items():
        current = peaks.get(title)
        if current is None or sold > current[1]:
            peaks[title] = (screen, sold)
    return peaks


def summarize(tickets: RowList) -> SummaryList:
    """Return (title, total sales, average sales per screen) for each movie."""
    summaries: SummaryList = []
    for title, sales in group_by_movie(tickets).items():
        total, average = totals_and_average(sales)
        summaries.append((title, total, average))
    summaries.sort(key=lambda item: (-item[1], item[0]))
    return summaries


def format_report(summaries: SummaryList, peaks: PeakMap) -> list[str]:
    """Render one human-readable line per movie."""
    lines: list[str] = []
    for title, total, average in summaries:
        screen, sold = peaks[title]
        lines.append(
            f"{title}: total={total}, avg/screen={average:.1f}, "
            f"best=screen {screen} ({sold})"
        )
    return lines


def main() -> None:
    raw_lines: list[str] = [
        "Dune, 1, 50",
        "Dune, 2, 50",
        "Arrival, 1, 120",
        "Arrival, 3, 80",
        "Arrival, 3, 15",
        "Solaris, 2, 40",
    ]
    tickets = parse_rows(raw_lines)
    for line in format_report(summarize(tickets), busiest_screen(tickets)):
        print(line)


if __name__ == "__main__":
    main()

