Log = tuple[str, str, int]
Invoice = tuple[str, int]
CostList = list[int]
CostMap = dict[str, CostList]


def entry_cost(log: Log, rates: dict[str, int]) -> int:
    """Cost of a single log entry: the project rate times the hours worked."""
    client, project, hours = log
    if hours < 0:
        raise ValueError(f"negative hours logged for {client} on {project}")
    if project not in rates:
        raise KeyError(f"no rate configured for project {project!r}")
    return rates[project] * hours


def group_costs(
    logs: list[Log],
    rates: dict[str, int],
) -> CostMap:
    """Group the individual entry costs by client name."""
    grouped: CostMap = {}
    for log in logs:
        client = log[0]
        grouped.setdefault(client, []).append(entry_cost(log, rates))
    return grouped


def totals(grouped: CostMap) -> dict[str, int]:
    return {client: sum(costs) for client, costs in grouped.items()}


def invoice(
    logs: list[Log],
    rates: dict[str, int],
) -> list[Invoice]:
    """Total billing amount per client, largest invoice first."""
    grouped = group_costs(logs, rates)
    summed = totals(grouped)
    return sorted(summed.items(), key=lambda item: (-item[1], item[0]))


def column_widths(
    invoices: list[Invoice],
) -> tuple[int, int]:
    name_width = max((len(client) for client, _ in invoices), default=0)
    amount_width = max((len(str(amount)) for _, amount in invoices), default=0)
    return name_width, amount_width


def format_report(
    invoices: list[Invoice],
) -> list[str]:
    widths = column_widths(invoices)
    name_width, amount_width = widths
    lines: list[str] = []
    for client, amount in invoices:
        lines.append(f"{client:<{name_width}}  {amount:>{amount_width}}")
    return lines


def project_hours(
    logs: list[Log],
) -> dict[str, int]:
    hours: dict[str, int] = {}
    for _, project, worked in logs:
        hours[project] = hours.get(project, 0) + worked
    return hours


def main() -> None:
    rates: dict[str, int] = {"redesign": 5, "api": 90, "audit": 120}
    logs: list[Log] = [
        ("Acme", "redesign", 10),
        ("Acme", "api", 12),
        ("Globex", "audit", 8),
        ("Globex", "api", 3),
        ("Initech", "redesign", 40),
    ]
    invoices = invoice(logs, rates)
    for line in format_report(invoices):
        print(line)
    print("hours per project:")
    for project, worked in sorted(project_hours(logs).items()):
        print(f"  {project}: {worked}")


if __name__ == "__main__":
    main()

