Report = list[str]


def validate_streams(streams: StreamLog) -> None:
    """Reject entries that cannot be turned into a payout."""
    for artist, title, plays in streams:
        if not artist or not title:
            raise ValueError("artist and song title must be non-empty")
        if plays < 0:
            raise ValueError(f"negative play count for {title!r}: {plays}")


def group_by_artist(streams: StreamLog) -> Grouped:
    """Collect every (song, plays) pair belonging to each artist."""
    grouped: Grouped = {}
    for artist, title, plays in streams:
        grouped.setdefault(artist, []).append((title, plays))
    return grouped


def total_earnings(songs: Catalog, payouts: Payouts) -> int:
    """Sum plays * per-play payout over a single artist's catalog."""
    total = 0
    for title, plays in songs:
        total += plays * payouts.get(title, 0)
    return total


def unpriced_songs(streams: StreamLog, payouts: Payouts) -> Titles:
    """Song titles that appear in the stream log but have no payout rate."""
    missing: Titles = []
    for _, title, _plays in streams:
        if title not in payouts and title not in missing:
            missing.append(title)
    return missing


def royalties(streams: StreamLog, payouts: Payouts) -> Earnings:
    validate_streams(streams)
    grouped = group_by_artist(streams)
    earned: Earnings = []
    for artist, songs in grouped.items():
        earned.append((artist, total_earnings(songs, payouts)))
    earned.sort(key=lambda item: (-item[1], item[0]))
    return earned


def format_report(earned: Earnings) -> Report:
    width = max((len(artist) for artist, _ in earned), default=0)
    lines: Report = []
    for artist, amount in earned:
        lines.append(f"{artist.ljust(width)}  {amount:>6}")
    return lines


def main() -> None:
    streams: StreamLog = [
        ("Nova Trio", "Blue Hours", 2),
