Ticket = tuple[str, str, int]
Hours = list[int]
Ranked = tuple[str, int]


def group_by_category(
    tickets: list[Ticket],
) -> dict[str, Hours]:
    """Map each issue category to the list of waiting hours reported for it."""
    grouped: dict[str, Hours] = {}
    for user, category, hours in tickets:
        if not user.strip():
            raise ValueError("every ticket must name a user")
        if hours < 0:
            raise ValueError(f"negative waiting time for {category!r}")
        key = category.strip().lower()
        grouped.setdefault(key, []).append(hours)
    return grouped


def longest_wait(hours: Hours) -> int:
    """Return the largest waiting time in a non-empty list of hours."""
    if not hours:
        raise ValueError("cannot take the maximum of an empty ticket group")
    worst = hours[0]
    for value in hours[1:]:
        if value > worst:
            worst = value
    return worst


def prioritize(
    tickets: list[Ticket],
) -> list[Ranked]:
    """Rank issue categories by their longest waiting time, worst first."""
    ranking: list[Ranked] = []
    for category, hours in group_by_category(tickets).items():
        ranking.append((category, longest_wait(hours)))
    ranking.sort(key=lambda entry: (-entry[1], entry[0]))
    return ranking


def ticket_counts(
    tickets: list[Ticket],
) -> dict[str, int]:
    """Count how many tickets were filed per category."""
    counts: dict[str, int] = {}
    for category, hours in group_by_category(tickets).items():
        counts[category] = len(hours)
    return counts


def format_report(
    ranking: list[Ranked],
    counts: dict[str, int],
) -> str:
    """Render the ranking as an aligned text table."""
    if not ranking:
        return "no tickets in the queue"
    width = max(len(category) for category, _ in ranking)
    lines: list[str] = []
    for category, worst in ranking:
        total = counts[category]
        label = "ticket" if total == 1 else "tickets"
        lines.append(f"{category.ljust(width)}  {worst:>3}h  ({total} {label})")
    return "\n".join(lines)


def main() -> None:
    tickets: list[Ticket] = [
        ("ana", "network", 2),
        ("bruno", "network", 5),
        ("carla", "login", 9),
        ("diego", "printer", 1),
        ("erik", "login", 4),
        ("fabia", "printer", 7),
        ("gil", "email", 7),
    ]
    ranking = prioritize(tickets)
    print(format_report(ranking, ticket_counts(tickets)))
    top_category, top_wait = ranking[0]
    print(f"\nescalate '{top_category}' first: waiting {top_wait} hours")


if __name__ == "__main__":
    main()

