from typing import Dict, List, Tuple

LIMIT = 50

Trip = Tuple[str, int]
TripList = List[Trip]
TripLog = Dict[str, TripList]


def parse_record(record: str) -> Tuple[str, str, int]:
    """Split one raw delivery line into driver, restaurant and distance."""
    fields = record.split(",")
    if len(fields) != 3:
        raise ValueError(f"malformed delivery record: {record!r}")
    driver, restaurant, raw_distance = (field.strip() for field in fields)
    try:
        distance = int(raw_distance)
    except ValueError:
        raise ValueError(f"distance is not an integer: {record!r}") from None
    return driver, restaurant, distance


def parse_deliveries(deliveries: List[str]) -> TripLog:
    """Group the raw records by driver name, keeping (restaurant, distance)."""
    log: TripLog = {}
    for record in deliveries:
        driver, restaurant, distance = parse_record(record)
        log.setdefault(driver, []).append((restaurant, distance))
    return log


def total_distance(trips: TripList) -> int:
    """Sum the distance component of every trip in the list."""
    distances: List[int] = [distance for _, distance in trips]
    return sum(distances)


def driver_totals(log: TripLog) -> Dict[str, int]:
    """Collapse each driver's trip list into a single total distance."""
    return {driver: total_distance(trips) for driver, trips in log.items()}


def optimize(
    deliveries: List[str],
) -> List[str]:
    """Return the drivers whose total distance exceeds the allowed limit."""
    totals = driver_totals(parse_deliveries(deliveries))
    return [driver for driver, total in totals.items() if total > LIMIT]


def format_report(
    totals: Dict[str, int],
    flagged: List[str],
) -> List[str]:
    """Build one readable line per driver, marking the flagged ones."""
    lines: List[str] = []
    for driver in sorted(totals):
        status = "OVER LIMIT" if driver in flagged else "ok"
        lines.append(f"{driver:<8} {totals[driver]:>4} km  {status}")
    return lines


def main() -> None:
    deliveries: List[str] = [
        "Alice,Pasta Palace,30",
        "Alice,Sushi Spot,30",
        "Bob,Burger Barn,12",
        "Bob,Taco Town,19",
        "Cleo,Curry Corner,51",
        "Dan,Diner Deluxe,50",
    ]
    flagged = optimize(deliveries)
    totals = driver_totals(parse_deliveries(deliveries))
    for line in format_report(totals, flagged):
        print(line)
    print("flagged drivers:", ", ".join(sorted(flagged)))


if __name__ == "__main__":
    main()

