Donation = tuple[int, str, int]
Amounts = list[int]
AmountsByYear = dict[int, Amounts]
YearTotals = tuple[int, int]
Summary = dict[int, YearTotals]


def group_by_year(donations: list[Donation]) -> AmountsByYear:
    """Group donation amounts by graduation year, preserving input order."""
    grouped: AmountsByYear = {}
    for year, name, amount in donations:
        if not name.strip():
            raise ValueError(f"donation for class of {year} is missing a donor name")
        if amount < 0:
            raise ValueError(f"negative donation of {amount} from {name}")
        grouped.setdefault(year, []).append(amount)
    return grouped


def summarize(amounts: Amounts) -> YearTotals:
    """Return the total of the amounts together with how many there are."""
    return sum(amounts), len(amounts)


def tally(donations):
    """Map each graduation year to (total donated, number of donors)."""
    grouped = group_by_year(donations)
    result: Summary = {}
    for year in sorted(grouped):
        result[year] = summarize(grouped[year])
    return result


def top_classes(summary: Summary, limit: int) -> list[int]:
    """Return the years of the `limit` most generous classes."""
    ranked = sorted(summary, key=lambda year: (-summary[year][0], year))
    return ranked[:limit]


def average_gift(summary: Summary) -> dict[int, float]:
    """Compute the mean gift size for every class in the summary."""
    averages: dict[int, float] = {}
    for year, (total, count) in summary.items():
        averages[year] = total / count
    return averages


def overall(summary: Summary) -> YearTotals:
    """Collapse the per-year summary into a single (total, donors) pair."""
    totals: Amounts = [total for total, _ in summary.values()]
    counts: Amounts = [count for _, count in summary.values()]
    return sum(totals), sum(counts)


def format_report(summary: Summary) -> list[str]:
    """Render one human readable line per graduating class."""
    averages = average_gift(summary)
    lines: list[str] = []
    for year in sorted(summary):
        total, count = summary[year]
        donors = "donor" if count == 1 else "donors"
        lines.append(f"Class of {year}: ${total:,} from {count} {donors} (avg ${averages[year]:,.2f})")
    return lines


def main() -> None:
    donations: list[Donation] = [
        (1998, "Ada Reyes", 50),
        (2004, "Marcus Hall", 250),
        (1998, "Jo Tanaka", 50),
        (2011, "Priya Nair", 120),
        (2004, "Lena Okafor", 75),
        (2011, "Sam Diaz", 400),
    ]
    summary = tally(donations)
    for line in format_report(summary):
        print(line)

    grand_total, donor_count = overall(summary)
    print(f"All classes: ${grand_total:,} from {donor_count} donors")
    for rank, year in enumerate(top_classes(summary, 2), start=1):
        print(f"#{rank} class of {year} with ${summary[year][0]:,}")


if __name__ == "__main__":
    main()

