"""Organize watering days for a collection of house plants."""

PlantRecord = tuple[str, int, int]

DayGroups = dict[
    int,
    list[str],
]

DaySlot = tuple[
    int,
    list[str],
]


def validate(plants: list[PlantRecord]) -> None:
    """Reject records that cannot describe a real watering cycle."""
    for name, frequency, days_since in plants:
        if frequency <= 0:
            raise ValueError(f"{name}: watering frequency must be positive")
        if days_since < 0:
            raise ValueError(f"{name}: days since watering cannot be negative")


def days_until_watering(frequency: int, days_since: int) -> int:
    """Days left before the next watering; overdue plants collapse to zero."""
    return max(frequency - days_since, 0)


def due_days(
    plants: list[PlantRecord],
) -> dict[str, int]:
    """Map every plant name to its number of days until watering."""
    due: dict[str, int] = {}
    for name, frequency, days_since in plants:
        due[name] = days_until_watering(frequency, days_since)
    return due


def group_by_day(due: dict[str, int]) -> DayGroups:
    """Collect plant names sharing the same watering day."""
    groups: DayGroups = {}
    for name, day in due.items():
        names: list[str] = groups.setdefault(day, [])
        names.append(name)
    return groups


def schedule(
    plants: list[PlantRecord],
) -> list[DaySlot]:
    """Return (day, plant names) pairs sorted by ascending day."""
    validate(plants)
    groups = group_by_day(due_days(plants))
    return [(day, groups[day]) for day in sorted(groups)]


def overdue_plants(
    plants: list[PlantRecord],
) -> list[str]:
    """Names of plants whose watering is due now or already missed."""
    return [name for name, day in due_days(plants).items() if day == 0]


def format_schedule(
    summary: list[DaySlot],
) -> list[str]:
    """Render the summary as human readable report lines."""
    lines: list[str] = []
    for day, names in summary:
        when = "today" if day == 0 else f"in {day} day(s)"
        lines.append(f"{when}: {', '.join(names)}")
    return lines


def main() -> None:
    plants: list[PlantRecord] = [
        ("Fern", 3, 1),
        ("Cactus", 14, 15),
        ("Ivy", 5, 5),
        ("Orchid", 7, 2),
    ]
    summary = schedule(plants)
    print(summary)
    for line in format_schedule(summary):
        print(line)
    urgent = overdue_plants(plants)
    print(f"{len(urgent)} plant(s) need water right away")


if __name__ == "__main__":
    main()

