from __future__ import annotations

Measurement = tuple[str, int, float]
Timestamps = list[int]
SizeSeries = list[float]
Result = tuple[str, Timestamps]

TOLERANCE = 0.20


def validate_measurements(rows: list[Measurement]) -> None:
    """Reject rows that cannot be interpreted as (machine, timestamp, size)."""
    for index, row in enumerate(rows):
        if len(row) != 3:
            raise ValueError(f"row {index}: expected three fields, got {len(row)}")
        machine, timestamp, size = row
        if not isinstance(machine, str) or not machine:
            raise ValueError(f"row {index}: machine identifier must be a non-empty string")
        if isinstance(timestamp, bool) or not isinstance(timestamp, int):
            raise ValueError(f"row {index}: timestamp must be an integer")
        if isinstance(size, bool) or not isinstance(size, (int, float)):
            raise ValueError(f"row {index}: part size must be numeric")


def collect_sizes(
    rows: list[Measurement],
) -> dict[str, SizeSeries]:
    """Group the measured part sizes per machine, preserving input order."""
    grouped: dict[str, SizeSeries] = {}
    for machine, _, size in rows:
        grouped.setdefault(machine, []).append(float(size))
    return grouped


def machine_averages(
    grouped: dict[str, SizeSeries],
) -> dict[str, float]:
    averages: dict[str, float] = {}
    for machine, sizes in grouped.items():
        averages[machine] = sum(sizes) / len(sizes)
    return averages


def is_defective(size: float, average: float) -> bool:
    """A part is faulty when it misses the average by over 20% of its own size."""
    return abs(size - average) > TOLERANCE * abs(size)


def defective_timestamps(
    rows: list[Measurement],
    averages: dict[str, float],
) -> dict[str, Timestamps]:
    faults: dict[str, Timestamps] = {}
    for machine, timestamp, size in rows:
        if is_defective(float(size), averages[machine]):
            faults.setdefault(machine, []).append(int(timestamp))
    return faults


def process(
    measurements: list[Measurement],
) -> list[Result]:
    validate_measurements(measurements)
    averages = machine_averages(collect_sizes(measurements))
    faults = defective_timestamps(measurements, averages)
    return [(machine, sorted(faults[machine])) for machine in sorted(faults)]


def format_report(
    results: list[Result],
) -> list[str]:
    lines: list[str] = []
    for machine, stamps in results:
        moments = ", ".join(str(stamp) for stamp in stamps)
        lines.append(f"{machine}: {len(stamps)} defective part(s) at t={moments}")
    return lines


def main() -> None:
    readings: list[Measurement] = [
        ("M1", 1, 100), ("M1", 2, 105), ("M1", 3, 50),
        ("M2", 4, 20), ("M2", 5, 21), ("M2", 6, 19.5), ("M2", 7, 40),
        ("M3", 8, 7), ("M3", 9, 7.2),
    ]
    results = process(readings)
    print(results)
    for line in format_report(results):
        print(line)


if __name__ == "__main__":
    main()

