LEVEL_CAPACITY = 5
NUM_LEVELS = 3
LEVEL_LABELS = ("first", "second", "third")

Request = tuple[str, int]
Level = list[str]
Garage = list[Level]


def level_for_size(size: int) -> int:
    """Return the index of the level that accepts a vehicle of the given size."""
    if size < 4:
        return 0
    if size <= 6:
        return 1
    return 2


def validate(vehicles: list[Request]) -> None:
    """Reject malformed requests before any allocation happens."""
    for index, request in enumerate(vehicles):
        if len(request) != 2:
            raise ValueError(f"request {index} must be a (name, size) pair")
        name, size = request
        if not isinstance(name, str) or not name:
            raise ValueError(f"request {index} has an invalid owner name")
        if not isinstance(size, int) or isinstance(size, bool) or size <= 0:
            raise ValueError(f"request {index} has an invalid vehicle size")


def allocate(vehicles):
    """Assign each request to a level, skipping vehicles that find their level full."""
    validate(vehicles)
    levels: Garage = [[] for _ in range(NUM_LEVELS)]
    for name, size in vehicles:
        target = level_for_size(size)
        if len(levels[target]) < LEVEL_CAPACITY:
            levels[target].append(name)
    return levels


def turned_away(
    vehicles: list[Request],
    levels: Garage,
) -> list[str]:
    """List owners, in request order, who did not get a spot."""
    parked = {name for level in levels for name in level}
    return [name for name, _ in vehicles if name not in parked]


def occupancy(levels: Garage) -> dict[str, int]:
    """Map a human-readable level label to the number of vehicles on it."""
    return {label: len(level) for label, level in zip(LEVEL_LABELS, levels)}


def free_space(levels: Garage) -> tuple[int, int, int]:
    """Remaining capacity of each level, as a fixed-size triple."""
    first, second, third = (LEVEL_CAPACITY - len(level) for level in levels)
    return first, second, third


def report(vehicles: list[Request]) -> str:
    """Build a multi-line summary of one allocation run."""
    levels = allocate(vehicles)
    counts = occupancy(levels)
    lines = []
    for label, level in zip(LEVEL_LABELS, levels):
        names = ", ".join(level) or "-"
        lines.append(f"{label:>6} level ({counts[label]}): {names}")
    spare = free_space(levels)
    lines.append(f"free spots: {spare[0]}/{spare[1]}/{spare[2]}")
    rejected = turned_away(vehicles, levels)
    if rejected:
        lines.append("turned away: " + ", ".join(rejected))
    return "\n".join(lines)


def main() -> None:
    requests: list[Request] = [
        ("Alice", 3), ("Bob", 5), ("Charlie", 7), ("Dave", 2),
        ("Eve", 1), ("Frank", 3), ("Grace", 2), ("Heidi", 3),
        ("Ivan", 6), ("Judy", 9),
    ]
    print(allocate(requests))
    print(report(requests))


if __name__ == "__main__":
    main()

