def tally(commitments: Schedule) -> Counts:
    """Count how many dishes are promised for each category."""
    counts: Counts = {category: 0 for category in REQUIREMENTS}
    for _, category in commitments:
        counts[category] = counts.get(category, 0) + 1
    return counts


def deficient_categories(counts: Counts) -> Names:
    """Return the categories that do not reach their minimum count."""
    short: list[str] = []
    for category, needed in REQUIREMENTS.items():
        if counts.get(category, 0) < needed:
            short.append(category)
    return sorted(short)


def guest_list(commitments: Schedule) -> Names:
    """Unique guest names in alphabetical order."""
    names: set[str] = {name for name, _ in commitments}
    return sorted(names)


def organize(commitments: Schedule) -> tuple[Names, Names]:
    """Evaluate the potluck: missing categories and the guest roster."""
    counts = tally(commitments)
    return deficient_categories(counts), guest_list(commitments)


def shortfalls(counts: Counts) -> list[Gap]:
    """How many extra dishes each deficient category still needs."""
    gaps: list[Gap] = []
    for category in deficient_categories(counts):
        gaps.append((category, REQUIREMENTS[category] - counts.get(category, 0)))
    return gaps


def report(commitments: Schedule) -> str:
    """Human readable summary of a dinner plan."""
    missing, guests = organize(commitments)
    counts = tally(commitments)
    lines: list[str] = ["Guests: " + (", ".join(guests) or "none")]
    for category in sorted(counts):
        lines.append(f"  {category}: {counts[category]}")
