"""Find each user's longest run of consecutive days for any single habit."""

Record = tuple[str, str, int]
RecordLog = list[Record]
Pair = tuple[str, int]
Summary = list[Pair]
DayList = list[int]
HabitDays = dict[str, DayList]
StreakMap = dict[str, int]


def validate(records: RecordLog) -> RecordLog:
    """Normalise names and make sure every day number is a usable integer."""
    cleaned: RecordLog = []
    for user, habit, day in records:
        if isinstance(day, bool) or not isinstance(day, int):
            raise ValueError(f"day must be an integer, got {day!r}")
        cleaned.append((user.strip(), habit.strip(), day))
    return cleaned


def longest_streak(days: list[int]) -> int:
    """Longest chain of consecutive day numbers in a single habit's log."""
    ordered: DayList = sorted(set(days))
    if not ordered:
        return 0
    best = 1
    current = 1
    for previous, day in zip(ordered, ordered[1:]):
        if day == previous + 1:
            current += 1
            best = max(best, current)
        else:
            current = 1
    return best


def group_records(records: RecordLog) -> dict[str, HabitDays]:
    """Collect the completion days per user and per habit."""
    grouped: dict[str, HabitDays] = {}
    for user, habit, day in records:
        habits: HabitDays = grouped.setdefault(user, {})
        habits.setdefault(habit, []).append(day)
    return grouped


def best_streaks(grouped: dict[str, HabitDays]) -> StreakMap:
    """Reduce each user's habits down to their single best streak."""
    result: StreakMap = {}
    for user, habits in grouped.items():
        per_habit: dict[str, int] = {
            habit: longest_streak(days) for habit, days in habits.items()
        }
        result[user] = max(per_habit.values(), default=0)
    return result


def calculate(records: RecordLog) -> Summary:
    """Pair every user with their highest streak, sorted by user name."""
    streaks: StreakMap = best_streaks(group_records(validate(records)))
    return sorted(streaks.items())


def format_report(pairs: Summary) -> list[str]:
    """Render the result as aligned text lines for display."""
    width = max((len(user) for user, _ in pairs), default=0)
    return [f"{user.ljust(width)}  {streak} day(s)" for user, streak in pairs]


def main() -> None:
    log: RecordLog = [
        ("Leo", "run", 1),
        ("Leo", "run", 2),
        ("Leo", "read", 5),
        ("Ada", "read", 3),
        ("Ada", "read", 4),
        ("Ada", "read", 5),
        ("Ada", "swim", 9),
    ]
    summary: Summary = calculate(log)
    for line in format_report(summary):
        print(line)


if __name__ == "__main__":
    main()

