from __future__ import annotations

Ticket = tuple[str, str, int]
Assignment = list[str]

SKILL_ORDER: list[str] = ["billing", "technical", "general"]
AGENT_NAMES: list[str] = ["Agent-1", "Agent-2", "Agent-3"]


def parse_ticket(raw: str) -> Ticket:
    """Turn a "ident,skill,priority" record into a ticket tuple."""
    parts: list[str] = [field.strip() for field in raw.split(",")]
    if len(parts) != 3:
        raise ValueError(f"expected 3 fields, got {len(parts)}: {raw!r}")
    ident, skill, priority = parts
    skill = skill.lower()
    if skill not in SKILL_ORDER:
        raise ValueError(f"unknown skill {skill!r} in {raw!r}")
    return (ident, skill, int(priority))


def parse_tickets(
    records: list[str],
) -> list[Ticket]:
    """Parse every non-empty record into a ticket."""
    return [parse_ticket(record) for record in records if record.strip()]


def sort_key(ticket: Ticket) -> tuple[int, str]:
    """Priority descending, then identifier ascending."""
    ident, _, priority = ticket
    return (-priority, ident)


def route(
    tickets: list[Ticket],
) -> list[Assignment]:
    """Distribute tickets over the three agents by required skill."""
    buckets: dict[str, Assignment] = {skill: [] for skill in SKILL_ORDER}
    for ticket in sorted(tickets, key=sort_key):
        buckets[ticket[1]].append(ticket[0])
    return [buckets[skill] for skill in SKILL_ORDER]


def workload_counts(
    assignments: list[Assignment],
) -> dict[str, int]:
    """Map each agent name to the number of tickets it received."""
    return {name: len(queue) for name, queue in zip(AGENT_NAMES, assignments)}


def format_report(
    counts: dict[str, int],
) -> list[str]:
    """Render one "agent (skill): n ticket(s)" line per agent."""
    report: list[str] = []
    for name, skill in zip(AGENT_NAMES, SKILL_ORDER):
        total = counts[name]
        report.append(f"{name} ({skill}): {total} ticket(s)")
    return report


def main() -> None:
    records: list[str] = [
        "T1,billing,2",
        "T2,billing,5",
        "T3,technical,1",
        "T4,general,4",
        "T5,technical,1",
    ]
    tickets = parse_tickets(records)
    assignments: list[Assignment] = route(tickets)
    print(assignments)
    for line in format_report(workload_counts(assignments)):
        print(line)


if __name__ == "__main__":
    main()

