RECIPES = {
    "salad": ["lettuce", "tomato", "cucumber"],
    "soup": ["broth", "potato", "carrot"],
    "sandwich": ["bread", "cheese", "ham"],
}


def normalize(
    ingredients: list[str],
) -> list[str]:
    """Trim, lowercase and de-duplicate user-supplied ingredient names."""
    cleaned: list[str] = []
    for item in ingredients:
        name = item.strip().lower()
        if name and name not in cleaned:
            cleaned.append(name)
    return cleaned


def count_matches(
    available: list[str],
) -> dict[str, int]:
    """How many required ingredients each recipe already has."""
    counts: dict[str, int] = {}
    for recipe, required in RECIPES.items():
        counts[recipe] = sum(1 for item in required if item in available)
    return counts


def missing_for(
    recipe: str,
    available: list[str],
) -> list[str]:
    return [item for item in RECIPES[recipe] if item not in available]


def match(ingredients):
    available = normalize(ingredients)
    counts = count_matches(available)
    possible: list[str] = [
        recipe for recipe, found in counts.items() if found == len(RECIPES[recipe])
    ]
    return sorted(possible)


def ranking(
    counts: dict[str, int],
) -> list[str]:
    """Recipe names ordered by how close they are to being cookable."""
    return sorted(counts, key=lambda recipe: (-counts[recipe], recipe))


def report(
    ingredients: list[str],
) -> str:
    available = normalize(ingredients)
    counts = count_matches(available)
    lines: list[str] = ["Available: " + (", ".join(available) or "(nothing)")]
    possible = match(ingredients)
    if possible:
        lines.append("You can make: " + ", ".join(possible))
    else:
        lines.append("You can make: nothing yet")
    for recipe in ranking(counts):
        score: tuple[int, int] = (counts[recipe], len(RECIPES[recipe]))
        detail = f"  {recipe}: {score[0]}/{score[1]}"
        gaps = missing_for(recipe, available)
        if gaps:
            detail += " (need " + ", ".join(gaps) + ")"
        lines.append(detail)
    return "\n".join(lines)


def main() -> None:
    pantries = {
        "Lunchbox": ["bread", "cheese", "ham", "tomato"],
        "Garden": ["Lettuce", " tomato ", "cucumber", "broth"],
        "Empty": [],
    }
    for label, items in pantries.items():
        print(f"== {label} ==")
        print(report(items))
        print(f"match() -> {match(items)}")


if __name__ == "__main__":
    main()

