from math import inf

Observation = tuple[str, str, int]
ZoneTotals = dict[str, int]
Status = tuple[str, bool]

KINDS = ("predator", "prey")


def validate(zone: str, kind: str, count: int) -> None:
    """Reject observations that cannot be aggregated meaningfully."""
    if not zone:
        raise ValueError("zone name must not be empty")
    if kind not in KINDS:
        raise ValueError(f"unknown animal type: {kind!r}")
    if count < 0:
        raise ValueError(f"negative count for zone {zone!r}: {count}")


def aggregate(
    observations: list[Observation],
) -> tuple[ZoneTotals, ZoneTotals]:
    """Sum predator and prey counts per zone."""
    predators: ZoneTotals = {}
    prey: ZoneTotals = {}
    for zone, kind, count in observations:
        validate(zone, kind, count)
        bucket = predators if kind == "predator" else prey
        bucket[zone] = bucket.get(zone, 0) + count
        predators.setdefault(zone, 0)
        prey.setdefault(zone, 0)
    return predators, prey


def zone_names(predators: ZoneTotals, prey: ZoneTotals) -> list[str]:
    return sorted(set(predators) | set(prey))


def is_balanced(predator_count: int, prey_count: int) -> bool:
    return 2 * predator_count <= prey_count <= 5 * predator_count


def ratio_table(predators: ZoneTotals, prey: ZoneTotals) -> dict[str, float]:
    """Prey-per-predator ratio for each zone, infinite when predators are absent."""
    ratios: dict[str, float] = {}
    for zone in zone_names(predators, prey):
        hunters = predators[zone]
        ratios[zone] = prey[zone] / hunters if hunters else inf
    return ratios


def track(
    observations: list[Observation],
) -> list[Status]:
    predators, prey = aggregate(observations)
    return [
        (zone, is_balanced(predators[zone], prey[zone]))
        for zone in zone_names(predators, prey)
    ]


def format_report(
    statuses: list[Status],
    ratios: dict[str, float],
) -> list[str]:
    lines: list[str] = []
    for zone, balanced in statuses:
        label = "balanced" if balanced else "unbalanced"
        lines.append(f"{zone:<8} {label:<10} ratio={ratios[zone]:.2f}")
    return lines


def main() -> None:
    observations: list[Observation] = [
        ("North", "predator", 10),
        ("North", "prey", 30),
        ("South", "predator", 5),
        ("South", "prey", 5),
        ("East", "prey", 12),
    ]
    statuses = track(observations)
    print(statuses)
    predators, prey = aggregate(observations)
    for line in format_report(statuses, ratio_table(predators, prey)):
        print(line)


if __name__ == "__main__":
    main()

