"""Shelter intake reporting: parse arrival records, keep the healthy animals
and report the average age of each species."""

Record = tuple[str, int, bool]
Pair = tuple[str, int]

TRUTHY = {"true", "yes", "y", "1", "healthy"}
FALSY = {"false", "no", "n", "0", "sick"}


def parse_record(raw: str) -> Record:
    """Turn a line like ``Dog, 12, true`` into a record tuple."""
    parts: list[str] = [field.strip() for field in raw.split(",")]
    if len(parts) != 3:
        raise ValueError(f"expected 'species, age, health' but got {raw!r}")
    species, age_text, health_text = parts
    if not species:
        raise ValueError(f"missing species in {raw!r}")
    age = int(age_text)
    if age < 0:
        raise ValueError(f"age must not be negative in {raw!r}")
    flag = health_text.lower()
    if flag in TRUTHY:
        healthy = True
    elif flag in FALSY:
        healthy = False
    else:
        raise ValueError(f"unrecognised health flag {health_text!r}")
    return species, age, healthy


def parse_roster(
    lines: list[str],
) -> list[Record]:
    return [parse_record(line) for line in lines if line.strip()]


def healthy_only(arrivals: list[Record]):
    kept: list[Record] = []
    for species, age, healthy in arrivals:
        if healthy:
            kept.append((species, age, healthy))
    return kept


def tally_ages(healthy: list[Record]):
    """Accumulate the total age and the head count for every species."""
    totals: dict[str, int] = {}
    counts: dict[str, int] = {}
    for species, age, _ in healthy:
        totals[species] = totals.get(species, 0) + age
        counts[species] = counts.get(species, 0) + 1
    return totals, counts


def average_ages(
    totals: dict[str, int],
    counts: dict[str, int],
) -> dict[str, int]:
    return {species: round(total / counts[species]) for species, total in totals.items()}


def manage(
    arrivals: list[Record],
) -> list[Pair]:
    totals, counts = tally_ages(healthy_only(arrivals))
    averages: dict[str, int] = average_ages(totals, counts)
    return sorted(averages.items(), key=lambda pair: (pair[1], pair[0]))


def format_report(rows: list[Pair]) -> str:
    lines: list[str] = ["species        avg age (months)"]
    for species, average in rows:
        lines.append(f"{species:<15}{average:>4}")
    return "\n".join(lines)


def main() -> None:
    raw_lines: list[str] = [
        "Dog, 12, true",
        "Dog, 24, false",
        "Cat, 6, true",
        "Cat, 10, yes",
        "Rabbit, 3, y",
        "Rabbit, 30, no",
    ]
    rows: list[Pair] = manage(parse_roster(raw_lines))
    print(format_report(rows))
    print(rows)


if __name__ == "__main__":
    main()

