"""Find the hours in a school day when every student is free."""

DAY_START = 9
DAY_END = 17

Commitment = tuple[str, int, int]
Hours = list[int]


def parse_commitment(text: str) -> Commitment:
    name, start, end = (part.strip() for part in text.split(","))
    return name, int(start), int(end)


def parse_schedule(
    lines: list[str],
) -> list[Commitment]:
    return [parse_commitment(line) for line in lines if line.strip()]


def validate(commitments: list[Commitment]) -> None:
    for name, start, end in commitments:
        if start >= end:
            raise ValueError(f"{name}: a class must start before it ends")


def clamp_to_day(start: int, end: int) -> tuple[int, int]:
    return max(start, DAY_START), min(end, DAY_END)


def busy_hours(start: int, end: int) -> Hours:
    low, high = clamp_to_day(start, end)
    return list(range(low, high))


def busy_by_student(
    commitments: list[Commitment],
) -> dict[str, Hours]:
    busy: dict[str, Hours] = {}
    for name, start, end in commitments:
        hours = busy.setdefault(name, [])
        for hour in busy_hours(start, end):
            if hour not in hours:
                hours.append(hour)
    return busy


def schedule(commitments: list[Commitment]) -> list[int]:
    validate(commitments)
    busy = busy_by_student(commitments)
    free: list[int] = []
    for hour in range(DAY_START, DAY_END):
        if all(hour not in hours for hours in busy.values()):
            free.append(hour)
    return sorted(free)


def format_hours(hours: list[int]) -> str:
    return ", ".join(f"{hour:02d}:00" for hour in hours) or "none"


def format_report(
    commitments: list[Commitment],
) -> list[str]:
    busy = busy_by_student(commitments)
    lines: list[str] = []
    for name in sorted(busy):
        lines.append(f"{name} busy: {format_hours(sorted(busy[name]))}")
    lines.append(f"common free hours: {format_hours(schedule(commitments))}")
    return lines


def main() -> None:
    raw: list[str] = [
        "Dan, 9, 11",
        "Dan, 13, 15",
        "Eve, 10, 12",
    ]
    commitments = parse_schedule(raw)
    for line in format_report(commitments):
        print(line)


if __name__ == "__main__":
    main()

