from collections import defaultdict

ChapterSet = set[int]
LogEntry = tuple[str, str, int]
LogList = list[LogEntry]
ChapterMap = dict[str, ChapterSet]
ReaderBooks = dict[str, ChapterMap]
TitleList = list[str]
ReaderResult = tuple[str, TitleList]

REQUIRED_CHAPTERS: ChapterSet = {1, 2, 3, 4, 5}


def normalize_entry(entry: LogEntry) -> LogEntry:
    """Unpack and clean one log record."""
    reader, title, chapter = entry
    if not isinstance(chapter, int):
        raise TypeError(f"chapter must be an int, got {chapter!r}")
    return reader.strip(), title.strip(), chapter


def group_chapters(logs: LogList) -> ReaderBooks:
    """Map each reader to the set of unique chapters read per book."""
    grouped = defaultdict(lambda: defaultdict(set))
    for entry in logs:
        reader, title, chapter = normalize_entry(entry)
        grouped[reader][title].add(chapter)
    return {reader: dict(books) for reader, books in grouped.items()}


def finished_books(books: ChapterMap) -> TitleList:
    """Titles whose chapters one through five have all been read."""
    return sorted(
        title for title, chapters in books.items()
        if REQUIRED_CHAPTERS <= chapters
    )


def chapter_counts(books: ChapterMap) -> dict[str, int]:
    """How many distinct chapters were read for each book."""
    return {title: len(chapters) for title, chapters in sorted(books.items())}


def missing_chapters(books: ChapterMap, title: str) -> list[int]:
    """Required chapters still unread for one book."""
    return sorted(REQUIRED_CHAPTERS - books[title])


def track(logs: LogList) -> list[ReaderResult]:
    """Pair each reader with the sorted titles they have finished."""
    grouped = group_chapters(logs)
    return [(reader, finished_books(grouped[reader])) for reader in sorted(grouped)]


def format_report(logs: LogList) -> list[str]:
    """Human readable summary of completions and remaining gaps."""
    grouped = group_chapters(logs)
    lines: list[str] = []
    for reader, titles in track(logs):
        done = ", ".join(titles) if titles else "nothing"
        lines.append(f"{reader}: finished {done}")
        counts = chapter_counts(grouped[reader])
        for title, seen in counts.items():
            if title not in titles:
                gaps = missing_chapters(grouped[reader], title)
                lines.append(f"  {title}: {seen} read, missing {gaps}")
    return lines


def main() -> None:
    logs: LogList = [
        ("Mia", "Dune", 1), ("Mia", "Dune", 2), ("Mia", "Dune", 3),
        ("Mia", "Dune", 4), ("Mia", "Dune", 5), ("Mia", "Dune", 5),
        ("Mia", "Emma", 1), ("Mia", "Emma", 3),
        ("Abe", "Emma", 1), ("Abe", "Emma", 2), ("Abe", "Emma", 3),
        ("Abe", "Emma", 4), ("Abe", "Emma", 5),
    ]
    print(track(logs))
    for line in format_report(logs):
        print(line)


if __name__ == "__main__":
    main()

