Edge = tuple[str, str]
Neighbours = list[str]
Adjacency = dict[str, Neighbours]
Parents = dict[str, str]

START_ROOM = "start"
TREASURE_ROOM = "treasure"


def build_graph(paths: list[Edge]) -> Adjacency:
    """Turn bidirectional connections into an adjacency map."""
    graph: Adjacency = {}
    for first, second in paths:
        if first == second:
            continue
        graph.setdefault(first, []).append(second)
        graph.setdefault(second, []).append(first)
    return graph


def bfs_parents(graph: Adjacency, start: str) -> Parents:
    """Breadth-first search recording how each room was first reached."""
    parents: dict[str, str] = {start: start}
    queue: list[str] = [start]
    head = 0
    while head < len(queue):
        room = queue[head]
        head += 1
        for neighbour in graph.get(room, []):
            if neighbour not in parents:
                parents[neighbour] = room
                queue.append(neighbour)
    return parents


def trace_path(parents: Parents, goal: str) -> list[str]:
    """Walk the parent links backwards to rebuild the route to goal."""
    path: list[str] = [goal]
    room = goal
    while parents[room] != room:
        room = parents[room]
        path.append(room)
    path.reverse()
    return path


def navigate(paths: list[Edge]) -> int:
    graph = build_graph(paths)
    if START_ROOM not in graph or TREASURE_ROOM not in graph:
        return 0
    parents = bfs_parents(graph, START_ROOM)
    if TREASURE_ROOM not in parents:
        return 0
    return len(trace_path(parents, TREASURE_ROOM)) - 1


def room_degrees(graph: Adjacency) -> dict[str, int]:
    degrees: dict[str, int] = {}
    for room, neighbours in graph.items():
        degrees[room] = len(set(neighbours))
    return degrees


def maze_extent(graph: Adjacency) -> tuple[int, int]:
    degrees = room_degrees(graph)
    return len(degrees), sum(degrees.values()) // 2


def describe(paths: list[Edge]) -> str:
    graph = build_graph(paths)
    rooms, links = maze_extent(graph)
    steps = navigate(paths)
    if steps:
        route: list[str] = trace_path(bfs_parents(graph, START_ROOM), TREASURE_ROOM)
        journey = " -> ".join(route)
    else:
        journey = "no route"
    return f"{rooms} rooms, {links} links, {steps} steps ({journey})"


def main() -> None:
    simple: list[Edge] = [("start", "hall"), ("hall", "treasure")]
    branching: list[Edge] = [
        ("start", "hall"),
        ("hall", "library"),
        ("library", "treasure"),
        ("start", "cellar"),
        ("cellar", "treasure"),
    ]
    blocked: list[Edge] = [("start", "hall"), ("vault", "treasure")]
    for name, maze in (("simple", simple), ("branching", branching), ("blocked", blocked)):
        print(f"{name}: {describe(maze)}")
        degrees = room_degrees(build_graph(maze))
        busiest = max(degrees, key=lambda room: degrees[room])
        print(f"  busiest room: {busiest} ({degrees[busiest]} exits)")


if __name__ == "__main__":
    main()

