BRACKET_NAMES = ("youth", "open", "masters")

Runner = tuple[str, int, int]
Entry = tuple[str, int]
Bracket = list[Entry]


def validate(results: list[Runner]) -> None:
    """Reject entries that are not (name, age, time) with sane numbers."""
    for index, entry in enumerate(results):
        if len(entry) != 3:
            raise ValueError(f"entry {index} must hold name, age and time")
        name, age, time = entry
        if not isinstance(name, str) or not name:
            raise ValueError(f"entry {index} has an empty runner name")
        if age < 0:
            raise ValueError(f"runner {name} has a negative age")
        if time <= 0:
            raise ValueError(f"runner {name} has a non-positive time")


def age_bracket(age: int) -> str:
    if age < 20:
        return "youth"
    if age < 40:
        return "open"
    return "masters"


def group_by_bracket(
    results: list[Runner],
) -> dict[str, Bracket]:
    groups: dict[str, Bracket] = {name: [] for name in BRACKET_NAMES}
    for name, age, time in results:
        groups[age_bracket(age)].append((name, time))
    return groups


def fastest(entries: Bracket) -> str:
    if not entries:
        return ""
    winner = min(entries, key=lambda entry: (entry[1], entry[0]))
    return winner[0]


def bracket(
    results: list[Runner],
) -> list[str]:
    validate(results)
    groups = group_by_bracket(results)
    return [fastest(groups[name]) for name in BRACKET_NAMES]


def summarize(
    results: list[Runner],
) -> dict[str, int]:
    counts: dict[str, int] = {name: 0 for name in BRACKET_NAMES}
    for _, age, _time in results:
        counts[age_bracket(age)] += 1
    return counts


def format_report(
    winners: list[str],
    counts: dict[str, int],
) -> list[str]:
    lines = []
    for label, winner in zip(BRACKET_NAMES, winners):
        total = counts[label]
        champion = winner if winner else "no entrants"
        lines.append(f"{label:>8}: {champion} ({total} runners)")
    return lines


def main() -> None:
    results: list[Runner] = [
        ("Zoe", 18, 25),
        ("Max", 30, 20),
        ("Leo", 45, 22),
        ("Ada", 19, 25),
        ("Nia", 41, 22),
    ]
    winners = bracket(results)
    print(winners)
    for line in format_report(winners, summarize(results)):
        print(line)


if __name__ == "__main__":
    main()

