PLAN_COSTS: dict[str, int] = {"basic": 10, "pro": 20, "elite": 50}

VALID_ACTIONS: tuple[str, str] = ("subscribe", "cancel")

Event = tuple[str, str, str]

PlanRevenue = tuple[str, int]


def validate(
    events: list[Event],
) -> list[str]:
    """Return a list of human-readable problems found in the event stream."""
    problems: list[str] = []
    for index, event in enumerate(events):
        if len(event) != 3:
            problems.append(f"event {index}: expected 3 fields, got {len(event)}")
            continue
        user, plan, action = event
        if plan not in PLAN_COSTS:
            problems.append(f"event {index}: unknown plan {plan!r} for {user}")
        if action not in VALID_ACTIONS:
            problems.append(f"event {index}: unknown action {action!r} for {user}")
    return problems


def apply_events(
    events: list[Event],
) -> dict[str, str]:
    """Replay the events chronologically and return each user's active plan."""
    active: dict[str, str] = {}
    for user, plan, action in events:
        if action == "subscribe":
            active[user] = plan
        elif active.get(user) == plan:
            del active[user]
    return active


def plan_counts(
    active: dict[str, str],
) -> dict[str, int]:
    counts: dict[str, int] = {name: 0 for name in PLAN_COSTS}
    for plan in active.values():
        counts[plan] += 1
    return counts


def calculate(events) -> int:
    event_list = list(events)
    problems = validate(event_list)
    if problems:
        raise ValueError("; ".join(problems))
    active = apply_events(event_list)
    return sum(PLAN_COSTS[plan] for plan in active.values())


def revenue_breakdown(events: list[Event]) -> list[PlanRevenue]:
    """Revenue contributed by each plan, ordered from cheapest to priciest."""
    counts = plan_counts(apply_events(events))
    rows: list[PlanRevenue] = []
    for plan, cost in sorted(PLAN_COSTS.items(), key=lambda item: item[1]):
        rows.append((plan, counts[plan] * cost))
    return rows


def format_report(events: list[Event]) -> str:
    lines: list[str] = []
    counts = plan_counts(apply_events(events))
    for plan, revenue in revenue_breakdown(events):
        lines.append(f"{plan:<6} x{counts[plan]:<3} ${revenue}")
    lines.append(f"total  ${calculate(events)}")
    return "\n".join(lines)


def main() -> None:
    events: list[Event] = [
        ("Ivy", "pro", "subscribe"),
        ("Ivy", "pro", "cancel"),
        ("Jon", "basic", "subscribe"),
        ("Kim", "elite", "subscribe"),
        ("Jon", "basic", "cancel"),
        ("Jon", "pro", "subscribe"),
        ("Kim", "basic", "cancel"),
    ]
    print(format_report(events))
    print("active plans:", apply_events(events))


if __name__ == "__main__":
    main()

