"""Route a lift through a batch of passenger requests.

The lift starts at floor zero, sweeps upwards serving every passenger whose
destination is above their pick-up floor, then sweeps downwards for the rest.
"""

Request = tuple[str, int, int]


def validate(requests: list[Request]) -> None:
    for name, start, dest in requests:
        if start == dest:
            raise ValueError(f"{name} asked to travel from floor {start} to floor {start}")


def going_up(
    requests: list[Request],
) -> list[Request]:
    return [ride for ride in requests if ride[1] < ride[2]]


def going_down(
    requests: list[Request],
) -> list[Request]:
    return [ride for ride in requests if ride[1] > ride[2]]


def stops_for(
    rides: list[Request],
    descending: bool = False,
) -> list[int]:
    floors: set[int] = set()
    for _, start, dest in rides:
        floors.add(start)
        floors.add(dest)
    return sorted(floors, reverse=descending)


def dedupe_consecutive(
    floors: list[int],
) -> list[int]:
    trimmed: list[int] = []
    for floor in floors:
        if not trimmed or trimmed[-1] != floor:
            trimmed.append(floor)
    return trimmed


def sequence(
    requests: list[Request],
) -> list[int]:
    upward = stops_for(going_up(requests))
    downward = stops_for(going_down(requests), descending=True)
    return dedupe_consecutive(upward + downward)


def onboard_stops(
    stops: list[int],
    requests: list[Request],
) -> dict[str, int]:
    legs: dict[str, int] = {}
    for name, start, dest in requests:
        if start < dest:
            boarding = stops.index(start)
        else:
            # a descending pick-up floor may also be a stop of the upward sweep
            boarding = len(stops) - 1 - stops[::-1].index(start)
        legs[name] = stops.index(dest, boarding) - boarding
    return legs


def main() -> None:
    requests: list[Request] = [("Sam", 1, 4), ("Lee", 2, 5), ("Kim", 6, 3)]
    validate(requests)
    stops = sequence(requests)
    print("Stops:", stops)
    travelled: dict[str, int] = onboard_stops(stops, requests)
    for name in sorted(travelled):
        print(f"{name} stays on board for {travelled[name]} stop(s)")


if __name__ == "__main__":
    main()

