EXPIRY_LIMIT = 3

Record = tuple[str, str, int]
Inventory = list[Record]
Names = list[str]
Entry = tuple[str, Names]
Report = list[Entry]
Expiry = dict[str, int]


def parse_record(raw: str) -> Record:
    name, department, days = (part.strip() for part in raw.split(","))
    return name, department, int(days)


def parse_inventory(lines: list[str]) -> Inventory:
    return [parse_record(line) for line in lines if line.strip()]


def departments(medications: Inventory) -> list[str]:
    return sorted({department for _, department, _ in medications})


def expiring_in(medications: Inventory, department: str) -> Expiry:
    expiry: Expiry = {}
    for name, dept, days in medications:
        if dept == department and days <= EXPIRY_LIMIT:
            expiry[name] = days
    return expiry


def order_by_days(expiry: Expiry) -> Names:
    ordered = sorted(expiry.items(), key=lambda item: item[1])
    return [name for name, _ in ordered]


def check(medications: Inventory) -> Report:
    report: Report = []
    for department in departments(medications):
        expiry = expiring_in(medications, department)
        report.append((department, order_by_days(expiry)))
    return report


def urgency(medications: Inventory) -> dict[str, int]:
    soonest: Expiry = {}
    for _, department, days in medications:
        if days <= EXPIRY_LIMIT:
            current = soonest.get(department)
            if current is None or days < current:
                soonest[department] = days
    return soonest


def format_report(report: Report, soonest: Expiry) -> list[str]:
    lines: list[str] = []
    for department, names in report:
        if names:
            joined = ", ".join(names)
            lines.append(f"{department}: {joined} (next in {soonest[department]} day(s))")
        else:
            lines.append(f"{department}: nothing expiring soon")
    return lines


def main() -> None:
    raw_inventory = [
        "Aspirin, general, 2",
        "Vitamins, general, 10",
        "Ibuprofen, general, 1",
        "Antibiotic, restricted, 1",
        "Morphine, restricted, 3",
        "Saline, storage, 40",
    ]
    medications = parse_inventory(raw_inventory)
    report = check(medications)
    print(report)
    for line in format_report(report, urgency(medications)):
        print(line)


if __name__ == "__main__":
    main()

