def late_fee(days_kept: int) -> int:
    """Fee owed for a single tool kept `days_kept` days."""
    overdue = days_kept - RENTAL_PERIOD_DAYS
    if overdue <= 0:
        return 0
    return overdue * LATE_FEE_PER_DAY


def validate(returns: Ledger) -> None:
    """Reject records that cannot produce a meaningful charge."""
    for index, record in enumerate(returns):
        if len(record) != 3:
