        if not isinstance(days, int) or days < 0:
            raise ValueError(f"record {index} has invalid days: {days!r}")


def total_fees(returns: Ledger) -> Totals:
    """Sum the late fees owed by every customer appearing in `returns`."""
    totals: Totals = {}
