}


class ArtifactCatalog:
    """Keeps track of artifacts grouped by the era they belong to."""

    def __init__(self) -> None:
        self.era_counts: dict[str, int] = {}
        self.restoration: list[str] = []
        self.ages: list[int] = []

    def register(self, era: str, age: int) -> None:
        self.era_counts[era] = self.era_counts.get(era, 0) + 1
        self.ages.append(age)

    def flag_for_restoration(self, name: str) -> None:
        if name not in self.restoration:
            self.restoration.append(name)

    def known_eras(self) -> list[str]:
        return list(self.era_counts)

    def recorded_ages(self) -> list[int]:
        return list(self.ages)

    def pending_restoration(self) -> list[str]:
        return list(self.restoration)

    def era_totals(self) -> dict[str, int]:
        return dict(self.era_counts)


def split_discoveries(text: str) -> list[str]:
    """Break a report of discoveries (separated by ';') into single entries."""
    return [chunk.strip(" .") for chunk in text.split(";") if chunk.strip(" .")]


def word_to_age(spelled: str) -> int:
    total = 0
    current = 0
    tokens = [word for word in (raw.strip(".,") for raw in spelled.replace("-", " ").split()) if word]
    for token in tokens:
        if token.isdigit():
            current = int(token)
        elif token == "hundred":
            current = max(current, 1) * 100
        elif token == "thousand":
            total += max(current, 1) * 1000
            current = 0
        elif token in WORD_VALUES:
            current += WORD_VALUES[token]
        else:
            raise ValueError(f"unreadable age word: {token!r}")
    return total + current


def parse_discovery(entry: str) -> tuple[str, int]:
    """Turn 'bronze, three thousand' into ('bronze', 3000)."""
    era, _, spelled = entry.partition(",")
    if not spelled.strip(" ."):
        raise ValueError(f"missing age in discovery: {entry!r}")
    return era.strip().lower(), word_to_age(spelled.strip().lower())


def build_catalog(records: str) -> ArtifactCatalog:
    cat = ArtifactCatalog()
    for entry in split_discoveries(records):
        era, age = parse_discovery(entry)
        cat.register(era, age)
        if age >= 3000:
            cat.flag_for_restoration(f"{era} artifact")
    return cat


def catalog(records: str) -> str:
    cat = build_catalog(records)
    totals: dict[str, int] = cat.era_totals()
    if not totals:
        return ""
    order: list[str] = cat.known_eras()
    return max(order, key=lambda era: (totals[era], -order.index(era)))


def main() -> None:
    report = "bronze, three thousand; iron, two thousand."
    print(f"dominant era: {catalog(report)}")
    found = build_catalog(report)
    ages: list[int] = found.recorded_ages()
    print(f"ages: {ages}")
    print(f"needs restoration: {', '.join(found.pending_restoration())}")


if __name__ == "__main__":
    main()

