def parse_amount(text: str) -> int:
    tokens: list[str] = text.lower().replace("-", " ").split()
    total = 0
    current = 0
    for token in tokens:
        if token.isdigit():
            current += int(token)
        elif token in WORD_VALUES:
            current += WORD_VALUES[token]
        elif token in SCALES:
            scale = SCALES[token]
