}


class ComicCollection:
    """Tracks issues per publisher, mint titles and publication years."""

    def __init__(self) -> None:
        self.publisher_counts: dict[str, int] = {}
        self.mint_titles: list[str] = []
        self.years: list[int] = []
        self.latest_year: dict[str, int] = {}

    def add_issue(self, publisher: str, year: int) -> None:
        self.publisher_counts[publisher] = self.publisher_counts.get(publisher, 0) + 1
        self.latest_year[publisher] = max(self.latest_year.get(publisher, year), year)
        self.years.append(year)

    def tag_mint(self, title: str) -> None:
        if title not in self.mint_titles:
            self.mint_titles.append(title)

    def publishers(self) -> list[str]:
        return list(self.publisher_counts)

    def mint_condition(self) -> list[str]:
        return list(self.mint_titles)

    def publication_years(self) -> list[int]:
        return sorted(self.years)

    def leader(self) -> str:
        if not self.publisher_counts:
            return ""
        return max(
            self.publisher_counts,
            key=lambda name: (self.publisher_counts[name], self.latest_year[name]),
        )


def split_inventory(text: str) -> list[str]:
    return [chunk.strip() for chunk in text.split(";") if chunk.strip()]


def parse_year(token: str) -> int:
    word = token.strip().lower()
    if word in DECADE_WORDS:
        return DECADE_WORDS[word]
    return int(word)


def parse_entry(entry: str) -> tuple[str, int]:
    fields: list[str] = [field.strip() for field in entry.split(",")]
    return fields[0].lower(), parse_year(fields[1])


def build_collection(comics: str) -> ComicCollection:
    collection = ComicCollection()
    for entry in split_inventory(comics):
        publisher, year = parse_entry(entry)
        collection.add_issue(publisher, year)
        if "mint" in entry.lower():
            collection.tag_mint(f"{publisher} {year}")
    return collection


def inventory(comics: str) -> str:
    return build_collection(comics).leader()


def main() -> None:
    text = "marvel, sixty, mint; dc, seventy; dc, eighty"
    collection = build_collection(text)
    names: list[str] = collection.publishers()
    mint: list[str] = collection.mint_condition()
    years: list[int] = collection.publication_years()
    print("publishers:", ", ".join(names))
    print("mint:", ", ".join(mint) if mint else "none")
    print("years:", " ".join(str(year) for year in years))
    print("top publisher:", inventory(text))


if __name__ == "__main__":
    main()

