"""Pediatric growth tracking: percentile updates and dietary review flags."""

_UNITS: dict[str, int] = {
    "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
    "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10,
}

_TENS: dict[str, int] = {
    "twenty": 20, "thirty": 30, "forty": 40, "fifty": 50,
    "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90,
}


def split_clinical_data(data: str) -> list[str]:
    """Break a string of clinical entries separated by ';' into entries."""
    return [chunk.strip() for chunk in data.split(";") if chunk.strip()]


def _height_in_cm(text: str) -> int:
    if text.isdigit():
        return int(text)
    total = 0
    for word in text.replace("-", " ").split():
        if word in _TENS:
            total += _TENS[word]
        elif word in _UNITS:
            total += _UNITS[word]
        else:
            raise ValueError(f"unrecognised height value: {text!r}")
    return total


def parse_entry(entry: str) -> tuple[str, int]:
    """Parse 'name, height' into the patient name and the height in cm."""
    fields: list[str] = [part.strip() for part in entry.split(",")]
    if len(fields) != 2:
        raise ValueError(f"malformed clinical entry: {entry!r}")
    return fields[0].lower(), _height_in_cm(fields[1].lower())


class GrowthTracker:
    def __init__(self) -> None:
        self.percentiles: dict[str, int] = {}
        self.dietary_review: list[str] = []
        self.heights: list[int] = []

    def update_percentile(self, name: str, height: int) -> int:
        self.heights.append(height)
        ranked: list[int] = sorted(self.heights)
        below = sum(1 for value in ranked if value < height)
        percentile = round(100 * below / len(ranked))
        self.percentiles[name] = percentile
        return percentile

    def flag_for_review(self, name: str) -> None:
        if name not in self.dietary_review:
            self.dietary_review.append(name)

    def patient_names(self) -> list[str]:
        return list(self.percentiles)

    def flagged_patients(self) -> list[str]:
        return list(self.dietary_review)

    def recorded_heights(self) -> list[int]:
        return list(self.heights)


def build_tracker(records: str) -> GrowthTracker:
    tracker = GrowthTracker()
    for entry in split_clinical_data(records):
        name, height = parse_entry(entry)
        if tracker.update_percentile(name, height) < 25:
            tracker.flag_for_review(name)
    return tracker


def format_report(tracker: GrowthTracker) -> list[str]:
    lines: list[str] = []
    for name in tracker.patient_names():
        lines.append(f"{name}: percentile {tracker.percentiles[name]}")
    flagged: list[str] = tracker.flagged_patients()
    if flagged:
        lines.append("dietary review needed: " + ", ".join(flagged))
    heights: list[int] = tracker.recorded_heights()
    lines.append(f"heights on file (cm): {heights}")
    return lines


def evaluate(records: str) -> str:
    tracker = build_tracker(records)
    names: list[str] = tracker.patient_names()
    heights: list[int] = tracker.recorded_heights()
    tallest: tuple[str, int] = ("", -1)
    for name, height in zip(names, heights):
        if height > tallest[1]:
            tallest = (name, height)
    return tallest[0]


if __name__ == "__main__":
    sample = "alice, forty; bob, thirty"
    for line in format_report(build_tracker(sample)):
        print(line)
    print("tallest patient:", evaluate(sample))

