    chunks = text.replace("\n", ";").split(";")
    return [chunk.strip() for chunk in chunks if chunk.strip()]


def parse_appraisal(entry: str) -> tuple[str, int]:
    fields: list[str] = [field.strip() for field in entry.split(",")]
    kind = fields[0].lower()
    word = fields[1].lower() if len(fields) > 1 else "0"
    if word in WORD_VALUES:
        return kind, WORD_VALUES[word]
    return kind, int(word)


