    log = AppraisalLog()
    for entry in split_appraisals(items):
        kind, value = parse_appraisal(entry)
        log.appraise_item(kind, value)
        fields = [field.strip() for field in entry.split(",")]
        if len(fields) > 2 and fields[2].isdigit():
            log.record_age(int(fields[2]))
        if value < RESTORE_THRESHOLD:
            log.mark_for_restoration(kind)
    return log


def appraise(items: str) -> str:
    log = build_log(items)
    kinds: list[str] = log.furniture_types()
    if not kinds:
        return ""
    return max(kinds, key=lambda kind: log.totals[kind])


