def split_scan_logs(text: str) -> List[str]:
    """Divide a semicolon separated scan log into single scan strings."""
    pieces: List[str] = [part.strip() for part in text.split(";")]
    return [piece for piece in pieces if piece]


def parse_scan(entry: str) -> Tuple[str, int]:
    """Turn one scan string such as 'summit, nine' into (lift name, hour)."""
    fields: List[str] = [field.strip() for field in entry.split(",")]
    if len(fields) != 2:
        raise ValueError(f"malformed scan: {entry!r}")
    name, raw_time = fields
    if raw_time.lower() in WORD_TIMES:
        return name.lower(), WORD_TIMES[raw_time.lower()]
    return name.lower(), int(raw_time)


class LiftTracker:
    def __init__(self) -> None:
        self.passengers: Dict[str, int] = {}
        self.expired: List[str] = []
        self.times: List[int] = []

    def record_scan(self, lift: str, scan_time: int) -> None:
        self.passengers[lift] = self.passengers.get(lift, 0) + 1
        self.times.append(scan_time)

    def log_expired(self, holder: str) -> None:
        self.expired.append(holder)

    def lift_names(self) -> List[str]:
        return sorted(self.passengers)

    def expired_holders(self) -> List[str]:
        return list(self.expired)

    def scan_times(self) -> List[int]:
        return list(self.times)

    def most_popular(self) -> str:
        if not self.passengers:
            return ""
        return max(self.lift_names(), key=lambda lift: self.passengers[lift])


def build_tracker(scans: str) -> LiftTracker:
    tracker = LiftTracker()
    for entry in split_scan_logs(scans):
        if entry.lower().startswith("expired:"):
            tracker.log_expired(entry.split(":", 1)[1].strip())
            continue
        pair: Tuple[str, int] = parse_scan(entry)
        tracker.record_scan(*pair)
    return tracker


def format_report(
    passengers: Dict[str, int],
    holders: List[str],
) -> List[str]:
    lines = [f"{lift}: {count}" for lift, count in sorted(passengers.items())]
    if holders:
        lines.append("expired passes: " + ", ".join(holders))
    return lines


def monitor(scans: str) -> str:
    return build_tracker(scans).most_popular()


def main() -> None:
    log = "summit, nine; base, eight; summit, ten; expired: Dana"
    tracker = build_tracker(log)
    for line in format_report(tracker.passengers, tracker.expired_holders()):
        print(line)
    hours: List[int] = tracker.scan_times()
    print(f"scan hours: {hours}")
    print(f"most popular: {tracker.most_popular()}")


if __name__ == "__main__":
    main()

