}


def split_findings(text: str) -> list[str]:
    """Break a newline- (or semicolon-) delimited report into single findings."""
    raw = text.replace(";", "\n").splitlines()
    return [line.strip() for line in raw if line.strip()]


def parse_finding(line: str) -> tuple[str, int]:
    """Turn 'valley, five' into ('valley', 5)."""
    site_part, separator, depth_part = line.partition(",")
    site = site_part.strip().lower()
    if not site or not separator:
        raise ValueError(f"malformed finding: {line!r}")
    tokens: list[str] = re.findall(r"[a-z0-9]+", depth_part.lower())
    for token in tokens:
        if token.isdigit():
            return site, int(token)
        if token in WORD_NUMBERS:
            return site, WORD_NUMBERS[token]
    raise ValueError(f"no depth found in finding: {line!r}")


class FossilCatalogue:
    def __init__(self) -> None:
        self.site_counts: dict[str, int] = {}
        self.fragile: list[str] = []
        self.depths: list[int] = []

    def record(self, site: str, depth: int) -> None:
        self.site_counts[site] = self.site_counts.get(site, 0) + 1
        self.depths.append(depth)

    def mark_fragile(self, site: str) -> None:
        if site not in self.fragile:
            self.fragile.append(site)

    def dig_sites(self) -> list[str]:
        return sorted(self.site_counts)

    def fragile_fossils(self) -> list[str]:
        return list(self.fragile)

    def all_depths(self) -> list[int]:
        return list(self.depths)


def depth_span(
    depths: list[int],
) -> tuple[int, int]:
    """Shallowest and deepest recorded discovery."""
    return min(depths), max(depths)


def catalogue(findings: str) -> str:
    book = FossilCatalogue()
    for entry in split_findings(findings):
        site, depth = parse_finding(entry)
        book.record(site, depth)
        if "fragile" in entry.lower():
            book.mark_fragile(site)
    counts: dict[str, int] = book.site_counts
    if not counts:
        raise ValueError("no findings to catalogue")
    shallowest, deepest = depth_span(book.all_depths())
    print(f"sites: {', '.join(book.dig_sites())}")
    print(f"depth range: {shallowest}-{deepest}")
    print(f"fragile: {', '.join(book.fragile_fossils()) or 'none'}")
    return max(book.dig_sites(), key=lambda name: counts[name])


def main() -> None:
    report = "valley, five; ridge, ten\nridge, twelve (fragile)"
    print("richest site:", catalogue(report))


