Reservation = tuple[str, int]
RowNames = list[str]
Seating = list[RowNames]
Sizes = dict[str, int]


def parse_reservations(
    raw: list[str],
) -> list[Reservation]:
    """Turn 'name:count' text entries into (name, size) pairs."""
    parsed: list[Reservation] = []
    for entry in raw:
        name, separator, count = entry.partition(":")
        if not separator:
            raise ValueError(f"malformed reservation: {entry!r}")
        parsed.append((name.strip(), int(count)))
    return parsed


def seat(reservations, rows) -> Seating:
    """Place each group in the frontmost row where it still fits, together."""
    seating: Seating = [[] for _ in rows]
    free: list[int] = list(rows)
    for name, size in reservations:
        for index, capacity in enumerate(free):
            if size <= capacity:
                seating[index].append(name)
                free[index] = capacity - size
                break
    return seating


def group_sizes(reservations: list[Reservation]) -> Sizes:
    sizes: Sizes = {}
    for name, size in reservations:
        sizes[name] = size
    return sizes


def remaining_seats(
    rows: list[int],
    seating: Seating,
    sizes: Sizes,
) -> list[int]:
    """Seats still empty in each row after the assignment."""
    free: list[int] = []
    for capacity, names in zip(rows, seating):
        taken = sum(sizes[name] for name in names)
        free.append(capacity - taken)
    return free


def skipped_groups(reservations, seating: Seating) -> list[str]:
    placed = {name for row in seating for name in row}
    return [name for name, _ in reservations if name not in placed]


def format_report(
    seating: Seating,
    free: list[int],
) -> list[str]:
    lines: list[str] = []
    for number, (names, left) in enumerate(zip(seating, free), start=1):
        occupants = ", ".join(names) if names else "(empty)"
        lines.append(f"Row {number}: {occupants} - {left} free")
    return lines


def main() -> None:
    raw: list[str] = ["smith:3", "jones:2", "davis:4", "patel:5", "kim:1"]
    rows: list[int] = [4, 5, 2]
    reservations = parse_reservations(raw)
    seating = seat(reservations, rows)
    sizes = group_sizes(reservations)
    free = remaining_seats(rows, seating, sizes)
    for line in format_report(seating, free):
        print(line)
    turned_away: list[str] = skipped_groups(reservations, seating)
    if turned_away:
        print("Not seated: " + ", ".join(turned_away))


if __name__ == "__main__":
    main()

