Member = tuple[str, str]
Drop = tuple[str, str]
Party = list[Member]
LootTable = list[Drop]
Haul = list[str]
Allocation = tuple[str, Haul]
Ledger = list[Allocation]
Slots = list[int]
ClassIndex = dict[str, Slots]
Counts = dict[int, int]


def group_by_class(party: Party) -> ClassIndex:
    """Map every class name to the party positions able to claim its loot."""
    index: ClassIndex = {}
    for position, (_, role) in enumerate(party):
        index.setdefault(role, []).append(position)
    return index


def pick_holder(candidates: Slots, counts: Counts) -> int:
    """Next member in the round-robin: fewest items so far, earliest on ties."""
    chosen = candidates[0]
    for position in candidates[1:]:
        if counts[position] < counts[chosen]:
            chosen = position
    return chosen


def distribute(party: Party, loot: LootTable) -> Ledger:
    index = group_by_class(party)
    hauls: list[Haul] = [[] for _ in party]
    counts: Counts = {position: 0 for position in range(len(party))}
    for item, role in loot:
        candidates = index.get(role, [])
        if not candidates:
            continue
        holder = pick_holder(candidates, counts)
        hauls[holder].append(item)
        counts[holder] += 1
    return [(name, hauls[position]) for position, (name, _) in enumerate(party)]


def unmatched(party: Party, loot: LootTable) -> Haul:
    """Items whose intended class is not represented in the party."""
    roles = {role for _, role in party}
    return [item for item, role in loot if role not in roles]


def tally(ledger: Ledger) -> dict[str, int]:
    return {name: len(haul) for name, haul in ledger}


def format_report(ledger: Ledger) -> list[str]:
    lines: list[str] = []
    for name, haul in ledger:
        lines.append(f"{name:<10} {', '.join(haul) if haul else '(nothing)'}")
    return lines


def main() -> None:
    party: Party = [
        ("gimli", "fighter"),
        ("legolas", "archer"),
        ("boromir", "fighter"),
        ("gandalf", "mage"),
    ]
    loot: LootTable = [
        ("axe", "fighter"),
        ("bow", "archer"),
        ("sword", "fighter"),
        ("greataxe", "fighter"),
        ("lockpicks", "rogue"),
        ("staff", "mage"),
    ]
    ledger = distribute(party, loot)
    for line in format_report(ledger):
        print(line)

    totals: dict[str, int] = tally(ledger)
    richest = max(totals, key=lambda name: (totals[name], -party.index((name, dict(party)[name]))))
    print(f"largest haul: {richest} ({totals[richest]} items)")

    leftovers: Haul = unmatched(party, loot)
    if leftovers:
        print(f"unclaimed: {', '.join(leftovers)}")


if __name__ == "__main__":
    main()

