from typing import Dict, List, Tuple

Item = Tuple[str, int]
Assignment = List[str]


def validate(
    items: List[Item],
    holds: List[int],
) -> None:
    for name, weight in items:
        if not name:
            raise ValueError("cargo identifier must not be empty")
        if weight <= 0:
            raise ValueError(f"weight of {name!r} must be positive")
    for capacity in holds:
        if capacity < 0:
            raise ValueError("hold capacity must not be negative")


def weight_index(items: List[Item]) -> Dict[str, int]:
    index: Dict[str, int] = {}
    for name, weight in items:
        if name in index:
            raise ValueError(f"duplicate cargo identifier {name!r}")
        index[name] = weight
    return index


def load(items, holds):
    validate(items, holds)
    assignments: List[Assignment] = [[] for _ in holds]
    free: List[int] = list(holds)
    for name, weight in sorted(items, key=lambda item: -item[1]):
        for position, space in enumerate(free):
            if space >= weight:
                assignments[position].append(name)
                free[position] = space - weight
                break
    return assignments


def remaining_capacity(
    holds: List[int],
    assignments: List[Assignment],
    weights: Dict[str, int],
) -> List[int]:
    return [
        capacity - sum(weights[name] for name in names)
        for capacity, names in zip(holds, assignments)
    ]


def unplaced(
    items: List[Item],
    assignments: List[Assignment],
) -> List[str]:
    placed = {name for names in assignments for name in names}
    return [item[0] for item in items if item[0] not in placed]


def utilisation(
    holds: List[int],
