Seed = tuple[str, int]
Matchup = tuple[str, str]


def validate_seeds(players: list[Seed]) -> None:
    """Reject empty names, duplicated names and duplicated rankings."""
    seen: dict[str, int] = {}
    for name, rank in players:
        if not name.strip():
            raise ValueError("player names must not be blank")
        if name in seen:
            raise ValueError(f"duplicate player name: {name}")
        seen[name] = rank
    if len(set(seen.values())) != len(seen):
        raise ValueError("rankings must be unique")


def sorted_names(
    players: list[Seed],
) -> list[str]:
    """Return the player names ordered from best rank to worst rank."""
    ordered = sorted(players, key=lambda seed: seed[1])
    return [name for name, _ in ordered]


def bracket(
    players: list[Seed],
) -> list[Matchup]:
    """Pair best against worst; the top seed gets a bye when the count is odd."""
    validate_seeds(players)
    names: list[str] = sorted_names(players)
    matchups: list[Matchup] = []
    if len(names) % 2 == 1:
        matchups.append((names[0], BYE))
        names = names[1:]
    left, right = 0, len(names) - 1
    while left < right:
        matchups.append((names[left], names[right]))
        left += 1
        right -= 1
    return matchups


