) -> list[str]:
    """Render each matchup as a printable line, showing seeds where known."""
    lines: list[str] = []
    for index, (home, away) in enumerate(matchups, start=1):
        if away == BYE:
            lines.append(f"{index}. {home} (#{ranks[home]}) advances on a bye")
        else:
            lines.append(
                f"{index}. {home} (#{ranks[home]}) vs {away} (#{ranks[away]})"
            )
    return lines


def main() -> None:
    odd_roster: list[Seed] = [("alice", 1), ("bob", 3), ("charlie", 2)]
