Unit = tuple[str, int, int]
Survivor = tuple[str, int]
Army = list[Unit]
Roster = list[Survivor]
Outcome = tuple[str, Roster]


def _validate(army: list[Unit], label: str) -> None:
    for index, unit in enumerate(army):
        if len(unit) != 3:
            raise ValueError(f"{label}[{index}] must hold name, attack and health")
        name, attack, health = unit
        if not isinstance(name, str) or not name:
            raise ValueError(f"{label}[{index}] has an empty name")
        if attack <= 0 or health <= 0:
            raise ValueError(f"{label}[{index}] ({name}) needs positive attack and health")


def clash(attackers: Army, defenders: Army) -> Outcome:
    _validate(attackers, "attackers")
    _validate(defenders, "defenders")
    left: list[Unit] = list(attackers)
    right = list(defenders)
    while left and right:
        a_name, a_attack, a_health = left[0]
        d_name, d_attack, d_health = right[0]
        d_health -= a_attack
        if d_health <= 0:
            right.pop(0)
            continue
        right[0] = (d_name, d_attack, d_health)
        a_health -= d_attack
        if a_health <= 0:
            left.pop(0)
        else:
            left[0] = (a_name, a_attack, a_health)
    winner = "attackers" if left else "defenders"
    field: list[Unit] = left or right
    survivors: Roster = [(name, health) for name, _, health in field]
    return winner, survivors


def casualty_report(before: Army, survivors: Roster) -> dict[str, int]:
    remaining: dict[str, int] = {}
    for name, _ in survivors:
        remaining[name] = remaining.get(name, 0) + 1
    losses: dict[str, int] = {}
    for name, _, _ in before:
        if remaining.get(name, 0) > 0:
            remaining[name] -= 1
        else:
            losses[name] = losses.get(name, 0) + 1
    return losses


def format_survivors(survivors: list[Survivor]) -> str:
    if not survivors:
        return "none"
    return ", ".join(f"{name} ({health} hp)" for name, health in survivors)


def describe(attackers: Army, defenders: Army) -> list[str]:
    winner, survivors = clash(attackers, defenders)
    lines = [f"{winner} win", f"  survivors: {format_survivors(survivors)}"]
    losses = casualty_report(attackers + defenders, survivors)
    for name, count in sorted(losses.items()):
        lines.append(f"  lost: {name} x{count}")
    return lines


def main() -> None:
    duel_attackers: list[Unit] = [("spearman", 3, 10)]
    duel_defenders: Army = [("militia", 1, 5)]
    print(clash(duel_attackers, duel_defenders))
    vanguard: Army = [("spearman", 3, 10), ("archer", 2, 6), ("knight", 6, 14)]
    garrison: Army = [("militia", 1, 5), ("guard", 4, 12), ("captain", 5, 18)]
    for line in describe(vanguard, garrison):
        print(line)
    for line in describe(garrison, vanguard):
        print(line)


if __name__ == "__main__":
    main()

