Slot = tuple[str, int]
Capacity = tuple[str, int, int]
Request = tuple[str, str, int]
Grant = tuple[str, str, int]


def build_capacity_map(
    capacities: list[Capacity],
) -> dict[Slot, int]:
    """Collapse the capacity table into a lookup keyed by (ride, hour)."""
    limits: dict[Slot, int] = {}
    for ride, hour, maximum in capacities:
        if maximum < 0:
            raise ValueError(f"negative capacity for {ride} at hour {hour}")
        limits[(ride, hour)] = maximum
    return limits


def schedule(
    requests: list[Request],
    capacities: list[Capacity],
) -> list[Grant]:
    """Grant fastpasses in request order while capacity remains."""
    limits = build_capacity_map(capacities)
    used: dict[Slot, int] = {}
    granted: list[Grant] = []
    for name, ride, hour in requests:
        key = (ride, hour)
        taken = used.get(key, 0)
        if taken < limits.get(key, 0):
            used[key] = taken + 1
            granted.append((name, ride, hour))
    return granted


def unfulfilled(
    requests: list[Request],
    granted: list[Grant],
) -> list[Request]:
    """Requests that did not receive a fastpass, in their original order."""
    outstanding: list[Grant] = list(granted)
    rejected = []
    for request in requests:
        if request in outstanding:
            outstanding.remove(request)
        else:
            rejected.append(request)
    return rejected


def count_by_ride(
    granted: list[Grant],
) -> dict[str, int]:
    """Total fastpasses handed out per ride."""
    totals: dict[str, int] = {}
    for _, ride, _ in granted:
        totals[ride] = totals.get(ride, 0) + 1
    return totals


def active_hours(
    granted: list[Grant],
) -> list[int]:
    """Sorted hour slots that saw at least one granted fastpass."""
    return sorted({hour for _, _, hour in granted})


def format_report(
    granted: list[Grant],
    rejected: list[Request],
) -> list[str]:
    totals = count_by_ride(granted)
    lines: list[str] = []
    for ride in sorted(totals):
        lines.append(f"{ride}: {totals[ride]} fastpass(es)")
    lines.append("hours in use: " + ", ".join(str(h) for h in active_hours(granted)))
    for name, ride, hour in rejected:
        lines.append(f"waitlisted {name} for {ride} at {hour}:00")
    return lines


def main() -> None:
    requests: list[Request] = [
        ("tom", "coaster", 10),
        ("sue", "coaster", 10),
        ("ann", "coaster", 11),
        ("bob", "flume", 10),
        ("kim", "flume", 10),
    ]
    capacities: list[Capacity] = [("coaster", 10, 1), ("coaster", 11, 2), ("flume", 10, 2)]
    granted = schedule(requests, capacities)
    print(granted)
    for line in format_report(granted, unfulfilled(requests, granted)):
        print(line)


if __name__ == "__main__":
    main()

