) -> Dict[str, int]:
    limits: Dict[str, int] = {}
    for name, maximum in rules:
        if maximum < 0:
            raise ValueError(f"negative limit for {name!r}")
        if name in limits:
            limits[name] = min(limits[name], maximum)
        else:
            limits[name] = maximum
    return limits


def validate(deck, rules):
    counts = count_cards(deck)
    limits = normalize_rules(rules)
    violations: List[Violation] = []
    for name, limit in limits.items():
        excess = counts.get(name, 0) - limit
        if excess > 0:
            violations.append((name, excess))
    violations.sort(key=lambda item: item[0])
    return violations


def parse_deck_list(
    lines: List[str],
) -> List[str]:
    deck: List[str] = []
    for line in lines:
        text = line.strip()
        if not text or text.startswith("#"):
            continue
        quantity, _, name = text.partition(" ")
        if quantity.isdigit():
            deck.extend([name.strip()] * int(quantity))
        else:
            deck.append(text)
    return deck


def parse_rules(
    lines: List[str],
) -> List[Rule]:
    rules: List[Rule] = []
    for line in lines:
        name, _, limit = line.strip().rpartition(":")
        rules.append((name.strip(), int(limit)))
    return rules


def format_report(violations: List[Violation]) -> str:
    if not violations:
        return "deck is legal"
    parts: List[str] = []
    for name, excess in violations:
        parts.append(f"{name}: {excess} too many")
    return "\n".join(parts)


def main() -> None:
    deck_lines: List[str] = [
        "# main deck",
        "3 goblin",
        "1 dragon",
        "5 forest",
        "",
        "2 lightning bolt",
    ]
    rule_lines = ["goblin: 2", "dragon: 1", "forest: 4", "lightning bolt: 3"]
    deck = parse_deck_list(deck_lines)
    rules = parse_rules(rule_lines)
    counts: Dict[str, int] = count_cards(deck)
    print(f"deck size: {sum(counts.values())} cards, {len(counts)} distinct")
    print(format_report(validate(deck, rules)))


if __name__ == "__main__":
    main()

