"""Group animals into enclosures so that no two hostile animals share one."""

HostileNames = list[str]
Animal = tuple[str, HostileNames]
Enclosure = list[str]
Habitat = list[Enclosure]
NameSet = set[str]
HostilityMap = dict[str, NameSet]
Report = list[str]


def build_hostility_map(animals: list[Animal]) -> HostilityMap:
    """Map every animal name to the set of animals it is hostile towards."""
    hostility: HostilityMap = {}
    for name, enemies in animals:
        hostility.setdefault(name, set()).update(enemies)
    return hostility


def validate(animals: list[Animal]) -> Report:
    """Report inconsistencies that would make the grouping meaningless."""
    problems: Report = []
    occurrences: dict[str, int] = {}
    for name, enemies in animals:
        occurrences[name] = occurrences.get(name, 0) + 1
        if name in enemies:
            problems.append(f"{name} is listed as hostile towards itself")
    for name, count in occurrences.items():
        if count > 1:
            problems.append(f"{name} appears {count} times in the input")
    return problems


def is_safe(occupants: Enclosure, name: str, hostility: HostilityMap) -> bool:
    enemies = hostility.get(name, set())
    for occupant in occupants:
        if occupant in enemies or name in hostility.get(occupant, set()):
            return False
    return True


def enclose(animals: list[Animal]) -> Habitat:
    hostility = build_hostility_map(animals)
    names: list[str] = [name for name, _ in animals]
    enclosures: Habitat = []
    for name in names:
        for occupants in enclosures:
            if is_safe(occupants, name, hostility):
                occupants.append(name)
                break
        else:
            enclosures.append([name])
    return enclosures


def occupancy(enclosures: Habitat) -> dict[str, int]:
    counts: dict[str, int] = {}
    for index, occupants in enumerate(enclosures, start=1):
        counts[f"Enclosure {index}"] = len(occupants)
    return counts


def largest_enclosure(enclosures: Habitat) -> tuple[int, int]:
    """Return the (1-based index, size) of the most crowded enclosure."""
    best: tuple[int, int] = (0, 0)
    for index, occupants in enumerate(enclosures, start=1):
        if len(occupants) > best[1]:
            best = (index, len(occupants))
    return best


def format_report(enclosures: Habitat) -> Report:
    counts = occupancy(enclosures)
    lines: Report = []
    for index, occupants in enumerate(enclosures, start=1):
        label = f"Enclosure {index}"
        lines.append(f"{label} ({counts[label]}): {', '.join(occupants)}")
    return lines


def main() -> None:
    zoo: list[Animal] = [
        ("lion", ["zebra", "gazelle"]),
        ("zebra", ["lion"]),
        ("elephant", []),
        ("gazelle", []),
        ("hyena", ["elephant"]),
    ]
    problems = validate(zoo)
    if problems:
        raise ValueError("; ".join(problems))
    enclosures = enclose(zoo)
    print(enclosures)
    for line in format_report(enclosures):
        print(line)
    index, size = largest_enclosure(enclosures)
    print(f"Most crowded: enclosure {index} with {size} animals")


if __name__ == "__main__":
    main()

