Painting = tuple[str, str, int]
ThemeItem = tuple[str, int]
ThemeItems = list[ThemeItem]
ThemeGroups = dict[str, ThemeItems]
WallNames = list[str]
Layout = list[WallNames]


def group_by_theme(paintings: list[Painting]) -> ThemeGroups:
    """Collect (name, width) pairs per theme, narrowest painting first."""
    groups: ThemeGroups = {}
    for name, theme, width in paintings:
        groups.setdefault(theme, []).append((name, width))
    for items in groups.values():
        items.sort(key=lambda item: item[1])
    return groups


def first_fit(width: int, remaining: list[int]) -> int:
    """Index of the first wall with enough free width, or -1 if none fits."""
    for index, free in enumerate(remaining):
        if width <= free:
            return index
    return -1


def hang(
    paintings: list[Painting],
    walls: list[int],
) -> Layout:
    layout: Layout = [[] for _ in walls]
    remaining: list[int] = list(walls)
    groups = group_by_theme(paintings)
    for theme in sorted(groups):
        for name, width in groups[theme]:
            index = first_fit(width, remaining)
            if index >= 0:
                remaining[index] -= width
                layout[index].append(name)
    return layout


def width_lookup(
    paintings: list[Painting],
) -> dict[str, int]:
    return {name: width for name, _theme, width in paintings}


def used_widths(
    layout: Layout,
    widths: dict[str, int],
) -> list[int]:
    return [sum(widths[name] for name in names) for names in layout]


def unhung(paintings: list[Painting], layout: Layout) -> WallNames:
    hung = {name for names in layout for name in names}
    return [name for name, _theme, _width in paintings if name not in hung]


def format_report(
    layout: Layout,
    walls: list[int],
    used: list[int],
) -> list[str]:
    lines: list[str] = []
    for index, names in enumerate(layout):
        shown = ", ".join(names) if names else "(empty)"
        lines.append(f"Wall {index}: {shown} [{used[index]}/{walls[index]}]")
    return lines


def main() -> None:
    paintings: list[Painting] = [
        ("starry", "sky", 5),
        ("sunflower", "nature", 4),
        ("dunes", "nature", 3),
        ("eclipse", "sky", 9),
        ("reeds", "nature", 2),
    ]
    walls: list[int] = [6, 6, 4]
    layout = hang(paintings, walls)
    widths = width_lookup(paintings)
    for line in format_report(layout, walls, used_widths(layout, widths)):
        print(line)
    skipped = unhung(paintings, layout)
    if skipped:
        print("Not hung: " + ", ".join(skipped))


if __name__ == "__main__":
    main()

