Passenger = tuple[str, int, int]
Assignment = tuple[str, int]


def parse_passengers(
    rows: list[str],
) -> list[Passenger]:
    """Parse "name,points,tier" records into passenger tuples."""
    passengers: list[Passenger] = []
    for row in rows:
        fields: list[str] = [field.strip() for field in row.split(",")]
        if len(fields) != 3:
            raise ValueError(f"malformed passenger record: {row!r}")
        name, points, tier = fields
        passengers.append((name, int(points), int(tier)))
    return passengers


def pick_cabin(current_tier: int, pool: list[int]) -> int | None:
    """Index of the best cabin strictly better than current_tier, if any."""
    for index, tier in enumerate(pool):
        if tier > current_tier:
            return index
    return None


def upgrade(
    passengers: list[Passenger],
    availability: list[int],
) -> list[Assignment]:
    pool: list[int] = sorted(availability, reverse=True)
    ranked: list[Passenger] = sorted(passengers, key=lambda p: -p[1])
    assignments: list[Assignment] = []
    for name, _points, tier in ranked:
        index = pick_cabin(tier, pool)
        if index is None:
            assignments.append((name, tier))
        else:
            assignments.append((name, pool.pop(index)))
    return assignments


def remaining_cabins(
    availability: list[int],
    assignments: list[Assignment],
    current: dict[str, int],
) -> list[int]:
    leftover: list[int] = sorted(availability, reverse=True)
    for name, tier in assignments:
        if tier > current[name]:
            leftover.remove(tier)
    return leftover


def tier_counts(
    cabins: list[int],
) -> dict[str, int]:
    counts: dict[str, int] = {}
    for tier in sorted(cabins, reverse=True):
        label = f"tier {tier}"
        counts[label] = counts.get(label, 0) + 1
    return counts


def format_report(
    assignments: list[Assignment],
    current: dict[str, int],
) -> list[str]:
    lines: list[str] = []
    for name, tier in assignments:
        old = current[name]
        if tier > old:
            lines.append(f"{name}: tier {old} -> tier {tier}")
        else:
            lines.append(f"{name}: stays in tier {old}")
    return lines


def main() -> None:
    rows: list[str] = ["alice,100,1", "bob,50,2", "carol,80,2", "dan,120,3"]
    passengers = parse_passengers(rows)
    availability: list[int] = [3, 2, 4, 2]
    current: dict[str, int] = {name: tier for name, _, tier in passengers}
    assignments = upgrade(passengers, availability)
    for line in format_report(assignments, current):
        print(line)
    leftover = remaining_cabins(availability, assignments, current)
    for label, count in tier_counts(leftover).items():
        print(f"{label}: {count} still free")


if __name__ == "__main__":
    main()

