Meteor = tuple[str, int, int]
Catalog = list[Meteor]
Shower = list[str]
Showers = list[Shower]
Centroid = tuple[int, int]
Index = dict[str, Meteor]
Report = list[str]

MAX_ANGLE_GAP = 5
MAX_SPEED_GAP = 10


def parse_line(text: str) -> Meteor:
    parts: list[str] = text.split()
    if len(parts) != 3:
        raise ValueError(f"malformed observation: {text!r}")
    name, angle, speed = parts
    return (name, int(angle), int(speed))


def load_catalog(lines: list[str]) -> Catalog:
    return [parse_line(line) for line in lines if line.strip()]


def _find(parent: dict[str, str], name: str) -> str:
    root = name
    while parent[root] != root:
        root = parent[root]
    while parent[name] != root:
        parent[name], name = root, parent[name]
    return root


def _union(parent: dict[str, str], left: str, right: str) -> None:
    root_left, root_right = _find(parent, left), _find(parent, right)
    if root_left != root_right:
        parent[root_right] = root_left


def same_shower(first: Meteor, second: Meteor) -> bool:
    return (abs(first[1] - second[1]) <= MAX_ANGLE_GAP
            and abs(first[2] - second[2]) <= MAX_SPEED_GAP)


def cluster(meteors: Catalog) -> Showers:
    parent: dict[str, str] = {meteor[0]: meteor[0] for meteor in meteors}
    for position, first in enumerate(meteors):
        for second in meteors[position + 1:]:
            if same_shower(first, second):
                _union(parent, first[0], second[0])
    groups: dict[str, Shower] = {}
    for name in list(parent):
        groups.setdefault(_find(parent, name), []).append(name)
    showers: Showers = [sorted(members) for members in groups.values()]
    showers.sort(key=lambda members: (-len(members), members))
    return showers


def centroid(members: Shower, index: Index) -> Centroid:
    angles: list[int] = [index[name][1] for name in members]
    speeds: list[int] = [index[name][2] for name in members]
    return (round(sum(angles) / len(angles)), round(sum(speeds) / len(speeds)))


def size_table(showers: Showers) -> dict[str, int]:
    return {members[0]: len(members) for members in showers}


def format_report(showers: Showers, index: Index) -> Report:
    sizes: dict[str, int] = size_table(showers)
    report: Report = []
    for members in showers:
        angle, speed = centroid(members, index)
        report.append(f"shower {members[0]} (n={sizes[members[0]]}): "
                      f"angle~{angle} speed~{speed} :: {', '.join(members)}")
    return report


def main() -> None:
    records: list[str] = [
        "m1 45 60", "m2 48 65", "m3 90 20",
        "m4 50 70", "m5 92 25", "m6 12 100",
    ]
    catalog: Catalog = load_catalog(records)
    index: Index = {meteor[0]: meteor for meteor in catalog}
    showers = cluster(catalog)
    print(showers)
    for line in format_report(showers, index):
        print(line)


if __name__ == "__main__":
    main()

