    for name in list(parent):
        groups.setdefault(_find(parent, name), []).append(name)
    showers: Showers = [sorted(members) for members in groups.values()]
    showers.sort(key=lambda members: (-len(members), members))
    return showers


def centroid(members: Shower, index: Index) -> Centroid:
    angles: List[int] = [index[name][1] for name in members]
    speeds: List[int] = [index[name][2] for name in members]
    return (round(sum(angles) / len(angles)), round(sum(speeds) / len(speeds)))


def size_table(showers: Showers) -> Dict[str, int]:
    return {members[0]: len(members) for members in showers}


def format_report(showers: Showers, index: Index) -> Report:
    sizes: Dict[str, int] = size_table(showers)
    report: Report = []
    for members in showers:
        angle, speed = centroid(members, index)
        report.append(f"shower {members[0]} (n={sizes[members[0]]}): "
                      f"angle~{angle} speed~{speed} :: {', '.join(members)}")
    return report


def main() -> None:
    records: List[str] = [
        "m1 45 60", "m2 48 65", "m3 90 20",
        "m4 50 70", "m5 92 25", "m6 12 100",
    ]
    catalog: Catalog = load_catalog(records)
    index: Index = {meteor[0]: meteor for meteor in catalog}
    showers = cluster(catalog)
    print(showers)
    for line in format_report(showers, index):
        print(line)


if __name__ == "__main__":
    main()

