Result = tuple[str, int]
Ranking = list[Result]
Round = list[Jump]


def trimmed_marks(marks: JudgeMarks) -> int:
    """Sum the judges' marks after dropping one highest and one lowest."""
    if len(marks) != 5:
        raise ValueError(f"expected 5 marks, got {len(marks)}")
    ordered: list[int] = sorted(marks)
    return sum(ordered[1:-1])


def score(jumps: list[Jump]) -> Ranking:
    """Rank a round of jumps, best score first."""
    results: list[Result] = []
    for name, distance, marks in jumps:
        results.append((name, distance + trimmed_marks(marks)))
    results.sort(key=lambda result: (-result[1], result[0]))
    return results


def combine_rounds(rounds: list[Round]) -> Ranking:
    """Add every jumper's per-round scores together into overall standings."""
    totals: dict[str, int] = {}
    for jumps in rounds:
        for name, points in score(jumps):
            totals[name] = totals.get(name, 0) + points
    return sorted(totals.items(), key=lambda entry: (-entry[1], entry[0]))


def score_spread(ranking: Ranking) -> tuple[int, int]:
    """Return the leading and trailing scores of a ranking."""
    if not ranking:
        raise ValueError("cannot measure the spread of an empty ranking")
    points: list[int] = [value for _, value in ranking]
    return max(points), min(points)


def format_ranking(ranking: Ranking) -> list[str]:
    width = max((len(name) for name, _ in ranking), default=0)
    lines: list[str] = []
    for place, (name, points) in enumerate(ranking, start=1):
        lines.append(f"{place}. {name:<{width}}  {points}")
    return lines


def main() -> None:
    round_one: Round = [
        ("eddie", 100, [10, 12, 14, 15, 12]),
        ("matti", 110, [18, 19, 19, 20, 18]),
        ("gregor", 105, [17, 18, 18, 19, 17]),
