    for line in format_ranking(score(round_one)):
        print(line)

    standings: Ranking = combine_rounds([round_one, round_two])
    print("\nOverall standings:")
    for line in format_ranking(standings):
        print(line)

    leader, trailer = score_spread(standings)
    print(f"\nGap between first and last: {leader - trailer} points")


if __name__ == "__main__":
