Splits = list[int]
TeamEntry = tuple[str, Splits]
TeamResult = tuple[str, int, Splits]


def validate(teams: list[TeamEntry]) -> None:
    seen: set[str] = set()
    for name, leg_times in teams:
        if not leg_times:
            raise ValueError(f"team {name!r} has no legs")
        if any(t <= 0 for t in leg_times):
            raise ValueError(f"team {name!r} has a non-positive leg time")
        if name in seen:
            raise ValueError(f"duplicate team name {name!r}")
        seen.add(name)


def cumulative_splits(leg_times: list[int]) -> Splits:
    splits: list[int] = []
    running = 0
    for leg in leg_times:
        running += leg
        splits.append(running)
    return splits


def relay(
    teams: list[TeamEntry],
) -> list[TeamResult]:
    validate(teams)
    results: list[TeamResult] = []
    for name, leg_times in teams:
        splits = cumulative_splits(leg_times)
        results.append((name, splits[-1], splits))
    results.sort(key=lambda entry: entry[1])
    return results


def leg_times_from_splits(splits: Splits) -> list[int]:
    previous = 0
    legs: list[int] = []
    for split in splits:
        legs.append(split - previous)
        previous = split
    return legs


def fastest_leg(splits: Splits) -> tuple[int, int]:
    legs = leg_times_from_splits(splits)
    best = min(legs)
    return legs.index(best) + 1, best


def rankings(
    results: list[TeamResult],
) -> dict[str, int]:
    rank_of: dict[str, int] = {}
    previous_total = None
    rank = 0
    for position, (name, total, _) in enumerate(results, start=1):
        if total != previous_total:
            rank = position
            previous_total = total
        rank_of[name] = rank
    return rank_of


def gaps_behind_winner(
    results: list[TeamResult],
) -> dict[str, int]:
    winning_time = results[0][1]
    return {name: total - winning_time for name, total, _ in results}


def format_report(
    results: list[TeamResult],
) -> list[str]:
    ranks = rankings(results)
    gaps = gaps_behind_winner(results)
    lines: list[str] = []
    for name, total, splits in results:
        leg_number, leg_time = fastest_leg(splits)
        margin = "winner" if gaps[name] == 0 else f"+{gaps[name]}"
        lines.append(
            f"{ranks[name]}. {name}: total {total} ({margin}), "
            f"splits {splits}, best leg {leg_number} in {leg_time}"
        )
    return lines


def main() -> None:
    teams: list[TeamEntry] = [
        ("red", [10, 12]),
        ("blue", [9, 14]),
        ("green", [11, 11]),
    ]
    results = relay(teams)
    print(results)
    for line in format_report(results):
        print(line)


if __name__ == "__main__":
    main()

