Ping = tuple[str, int, int]
Contact = tuple[str, int]
Thresholds = tuple[int, int]


def parse_ping(raw: str) -> Ping:
    """Parse a raw sonar record of the form 'sector,frequency,intensity'."""
    parts = raw.split(",")
    if len(parts) != 3:
        raise ValueError(f"malformed ping record: {raw!r}")
    sector = parts[0].strip().lower()
    if not sector:
        raise ValueError(f"missing sector in record: {raw!r}")
    return sector, int(parts[1]), int(parts[2])


def read_pings(
    records: list[str],
) -> list[Ping]:
    """Turn raw text records into structured pings."""
    pings = []
    for raw in records:
        if raw.strip():
            pings.append(parse_ping(raw))
    return pings


def significant(
    pings: list[Ping],
    thresholds: Thresholds,
) -> list[Ping]:
    """Keep pings meeting or exceeding both the frequency and intensity floors."""
    min_freq, min_intensity = thresholds
    return [p for p in pings if p[1] >= min_freq and p[2] >= min_intensity]


def count_by_sector(
    pings: list[Ping],
) -> dict[str, int]:
    """Count how many pings fall in each sector."""
    counts: dict[str, int] = {}
    for sector, _freq, _intensity in pings:
        counts[sector] = counts.get(sector, 0) + 1
    return counts


def classify(pings, thresholds):
    """Return (sector, count) pairs for significant pings, sorted by sector."""
    counts = count_by_sector(significant(list(pings), tuple(thresholds)))
    return sorted(counts.items())


def peak_intensities(
    pings: list[Ping],
) -> dict[str, int]:
    """Highest intensity recorded per sector."""
    peaks: dict[str, int] = {}
    for sector, _freq, intensity in pings:
        if intensity > peaks.get(sector, 0):
            peaks[sector] = intensity
    return peaks


def format_report(
    contacts: list[Contact],
    peaks: dict[str, int],
) -> list[str]:
    """Render one aligned line per sector with contacts and peak intensity."""
    if not contacts:
        return ["no significant contacts"]
    width = max(len(sector) for sector, _count in contacts)
    lines = []
    for sector, count in contacts:
        lines.append(f"{sector:<{width}}  contacts={count:<3} peak={peaks[sector]}")
    return lines


def main() -> None:
    records: list[str] = [
        "north,500,80",
        "north,100,20",
        "north,720,95",
        "south,600,90",
        "west,410,68",
        "east,999,71",
    ]
    thresholds: Thresholds = (400, 70)
    pings = read_pings(records)
    contacts = classify(pings, thresholds)
    peaks = peak_intensities(significant(pings, thresholds))
    print(contacts)
    for line in format_report(contacts, peaks):
        print(line)


if __name__ == "__main__":
    main()

