RISK_THRESHOLD = 29.0

Measurement = tuple[str, float]
TempSeries = list[float]


def group_by_reef(
    measurements: list[Measurement],
) -> dict[str, TempSeries]:
    """Collect every temperature reading under the name of its reef."""
    groups: dict[str, TempSeries] = {}
    for reef, temperature in measurements:
        name = reef.strip()
        if not name:
            raise ValueError("reef name must not be empty")
        groups.setdefault(name, []).append(float(temperature))
    return groups


def average_temperatures(
    groups: dict[str, TempSeries],
) -> dict[str, float]:
    """Mean temperature per reef over the readings supplied for it."""
    averages: dict[str, float] = {}
    for reef, temps in groups.items():
        averages[reef] = sum(temps) / len(temps)
    return averages


def count_readings(
    groups: dict[str, TempSeries],
) -> dict[str, int]:
    """How many readings back the average of each reef."""
    return {reef: len(temps) for reef, temps in groups.items()}


def reefs_at_risk(
    averages: dict[str, float],
) -> list[str]:
    """Names of reefs whose average temperature exceeds the threshold."""
    names = [reef for reef, mean in averages.items() if mean > RISK_THRESHOLD]
    return sorted(names)


def risk_summary(
    averages: dict[str, float],
) -> tuple[int, int]:
    """Pair of (reefs at risk, reefs monitored)."""
    at_risk = len(reefs_at_risk(averages))
    return at_risk, len(averages)


def format_report(
    averages: dict[str, float],
    counts: dict[str, int],
) -> list[str]:
    """One human readable line per reef, plus a closing tally."""
    lines: list[str] = []
    for reef in sorted(averages):
        flag = "BLEACHING RISK" if averages[reef] > RISK_THRESHOLD else "ok"
        lines.append(
            f"{reef}: {averages[reef]:.2f} C over {counts[reef]} readings -> {flag}"
        )
    at_risk, total = risk_summary(averages)
    lines.append(f"{at_risk} of {total} reefs above {RISK_THRESHOLD:.1f} C")
    return lines


def evaluate(
    measurements: list[Measurement],
) -> list[str]:
    """Return the alphabetical names of reefs at risk of bleaching."""
    groups = group_by_reef(measurements)
    return reefs_at_risk(average_temperatures(groups))


def main() -> None:
    readings: list[Measurement] = [
        ("Alpha", 28.0),
        ("Beta", 30.0),
        ("Alpha", 29.0),
        ("Beta", 31.0),
        ("Coral Gardens", 29.4),
    ]
    grouped = group_by_reef(readings)
    for line in format_report(average_temperatures(grouped), count_readings(grouped)):
        print(line)
    print("At risk:", evaluate(readings))


if __name__ == "__main__":
    main()

