Observation = tuple[str, int, float]
Reading = tuple[int, float]
Track = list[Reading]


def group_by_asteroid(
    observations: list[Observation],
) -> dict[str, Track]:
    """Collect observations per asteroid, each group sorted by observation day."""
    groups: dict[str, Track] = {}
    for identifier, day, distance in observations:
        groups.setdefault(identifier, []).append((day, distance))
    for track in groups.values():
        track.sort(key=lambda entry: entry[0])
    return groups


def daily_changes(track: Track) -> list[float]:
    """Average change in distance per day between consecutive observations."""
    changes: list[float] = []
    for (day_a, dist_a), (day_b, dist_b) in zip(track, track[1:]):
        span = day_b - day_a
        if span <= 0:
            raise ValueError("duplicate observation day in track")
        changes.append((dist_b - dist_a) / span)
    return changes


def is_threatening(changes: list[float]) -> bool:
    """True when every daily change closes the gap by at least 1 Mkm/day."""
    if not changes:
        return False
    return all(change <= -1.0 for change in changes)


def predict(
    observations: list[Observation],
) -> list[str]:
    """Identifiers of asteroids that approach steadily, alphabetically sorted."""
    threats: list[str] = []
    for identifier, track in group_by_asteroid(observations).items():
        if is_threatening(daily_changes(track)):
            threats.append(identifier)
    return sorted(threats)


def closing_speeds(
    observations: list[Observation],
) -> dict[str, float]:
    """Fastest closing speed (Mkm/day) observed for each asteroid."""
    speeds: dict[str, float] = {}
    for identifier, track in group_by_asteroid(observations).items():
        changes = daily_changes(track)
        if changes:
            speeds[identifier] = -min(changes)
    return speeds


def format_report(
    observations: list[Observation],
) -> list[str]:
    """One report line per asteroid, threats first, then alphabetical order."""
    groups = group_by_asteroid(observations)
    speeds = closing_speeds(observations)
    threats = set(predict(observations))
    lines: list[str] = []
    for identifier in sorted(groups, key=lambda name: (name not in threats, name)):
        speed = speeds.get(identifier, 0.0)
        status = "THREAT" if identifier in threats else "safe"
        lines.append(
            f"{identifier}: {len(groups[identifier])} obs, "
            f"closing {speed:+.2f} Mkm/day -> {status}"
        )
    return lines


def main() -> None:
    survey: list[Observation] = [
        ("X1", 1, 10.0),
        ("X1", 2, 8.0),
        ("Y2", 1, 5.0),
        ("Y2", 2, 6.0),
        ("Z9", 3, 40.0),
        ("Z9", 1, 55.0),
        ("Z9", 5, 30.0),
    ]
    print("Threatening asteroids:", predict(survey))
    for line in format_report(survey):
        print(line)


if __name__ == "__main__":
    main()

