Packet = tuple[str, int, int]
Score = tuple[str, int]


def _validate(packets: list[Packet]) -> None:
    """Reject malformed packets before any aggregation happens."""
    for index, packet in enumerate(packets):
        if len(packet) != 3:
            raise ValueError(f"packet {index} must have 3 fields, got {len(packet)}")
        name, code, severity = packet
        if not isinstance(name, str) or not name:
            raise ValueError(f"packet {index} has an empty subsystem name")
        if not isinstance(code, int) or not isinstance(severity, int):
            raise ValueError(f"packet {index} has non-integer code or severity")
        if severity < 0:
            raise ValueError(f"packet {index} has negative severity {severity}")


def faulty_only(
    packets: list[Packet],
) -> list[Packet]:
    """Drop every packet whose status code is the nominal value zero."""
    return [packet for packet in packets if packet[1] != 0]


def severity_by_subsystem(
    packets: list[Packet],
) -> dict[str, int]:
    """Total the severity levels of faulty packets, grouped by subsystem."""
    totals: dict[str, int] = {}
    for name, _code, severity in faulty_only(packets):
        totals[name] = totals.get(name, 0) + severity
    return totals


def analyze(
    packets: list[Packet],
) -> list[Score]:
    """Summarize faults as (subsystem, total severity), worst first."""
    _validate(packets)
    totals = severity_by_subsystem(packets)
    return sorted(totals.items(), key=lambda item: (-item[1], item[0]))


def status_code_counts(
    packets: list[Packet],
) -> dict[int, int]:
    """Count how often each distinct fault code was reported."""
    counts: dict[int, int] = {}
    for _name, code, _severity in faulty_only(packets):
        counts[code] = counts.get(code, 0) + 1
    return counts


def worst_subsystem(summary: list[Score]) -> Score | None:
    """Return the highest-scoring entry of an ordered summary, if any."""
    if not summary:
        return None
    return summary[0]


def format_report(
    summary: list[Score],
    counts: dict[int, int],
) -> str:
    lines = ["FAULT SUMMARY", "-" * 13]
    if not summary:
        lines.append("no faults reported")
    for name, score in summary:
        lines.append(f"{name:<8} severity {score}")
    top = worst_subsystem(summary)
    if top is not None:
        lines.append(f"critical: {top[0]} ({top[1]})")
    for code in sorted(counts):
        lines.append(f"code {code} seen {counts[code]}x")
    return "\n".join(lines)


def main() -> None:
    telemetry: list[Packet] = [
        ("Power", 0, 0),
        ("Drive", 404, 5),
        ("Drive", 500, 3),
        ("Comm", 0, 0),
        ("Comm", 500, 7),
        ("Thermal", 301, 2),
    ]
    print(format_report(analyze(telemetry), status_code_counts(telemetry)))


if __name__ == "__main__":
    main()

