Measurement = tuple[int, bool]
Flags = list[bool]
Groups = dict[int, Flags]
Counts = tuple[int, int]
Tallies = dict[int, Counts]
Rates = dict[int, float]

THRESHOLD = 0.1


def parse_log(
    lines: list[str],
) -> list[Measurement]:
    """Turn raw log lines of the form "<qubit>,<ok|error>" into measurements."""
    parsed: list[Measurement] = []
    for lineno, line in enumerate(lines, start=1):
        text = line.strip()
        if not text:
            continue
        index_text, _, flag_text = text.partition(",")
        flag_text = flag_text.strip().lower()
        if flag_text not in ("ok", "error"):
            raise ValueError(f"line {lineno}: unknown result {flag_text!r}")
        parsed.append((int(index_text), flag_text == "error"))
    return parsed


def group_measurements(
    measurements: list[Measurement],
) -> Groups:
    """Group the error flags by qubit index."""
    grouped: Groups = {}
    for qubit, errored in measurements:
        if qubit < 0:
            raise ValueError(f"invalid qubit index: {qubit}")
        grouped.setdefault(qubit, []).append(errored)
    return grouped


def tally(grouped: Groups) -> Tallies:
    """Reduce each group to an (errors, total) pair."""
    counts: Tallies = {}
    for qubit, flags in grouped.items():
        counts[qubit] = (sum(flags), len(flags))
    return counts


def error_rates(counts: Tallies) -> Rates:
    rates: Rates = {}
    for qubit, pair in counts.items():
        errors, total = pair
        rates[qubit] = errors / total
    return rates


def calibrate(
    measurements: list[Measurement],
) -> list[int]:
    """Return the sorted qubit indices whose error rate exceeds the threshold."""
    rates = error_rates(tally(group_measurements(measurements)))
    flagged = [qubit for qubit, rate in rates.items() if rate > THRESHOLD]
    return sorted(flagged)


def format_report(counts: Tallies) -> list[str]:
    lines = []
    for qubit in sorted(counts):
        errors, total = counts[qubit]
        rate = errors / total
        status = "RECALIBRATE" if rate > THRESHOLD else "ok"
        lines.append(f"qubit {qubit}: {errors}/{total} errors ({rate:.2%}) -> {status}")
    return lines


def main() -> None:
    raw: list[str] = [
        "0,ok",
        "0,error",
        "1,ok",
        "1,ok",
        "0,ok",
        "0,ok",
    ]
    measurements = parse_log(raw)
    for line in format_report(tally(group_measurements(measurements))):
        print(line)
    print("needs calibration:", calibrate(measurements))


if __name__ == "__main__":
    main()

