text_nat:
Interaction = tuple[str, str]
InteractionLog = list[Interaction]
ContactList = list[str]
ContactMap = dict[str, ContactList]
ExposureCounts = dict[str, int]
ExposureRange = tuple[int, int]
RankedContact = tuple[str, int]
Ranking = list[RankedContact]


def build_contact_map(interactions: InteractionLog) -> ContactMap:
    """Map each infected person to the list of their unique contacts, in order."""
    contact_map: ContactMap = {}
    for infected, contact in interactions:
        contacts = contact_map.setdefault(infected, [])
        if contact not in contacts:
            contacts.append(contact)
    return contact_map


def count_exposures(contact_map: ContactMap) -> ExposureCounts:
    """Count how many distinct infected individuals name each person as a contact."""
    exposures: ExposureCounts = {}
    for contacts in contact_map.values():
        for contact in contacts:
            exposures[contact] = exposures.get(contact, 0) + 1
    return exposures


def trace(interactions):
    """Return the alphabetically sorted people exposed to more than two infected individuals."""
    exposures = count_exposures(build_contact_map(interactions))
    spreaders: list[str] = [name for name, hits in exposures.items() if hits > 2]
    return sorted(spreaders)


def exposure_extremes(exposures: ExposureCounts) -> ExposureRange:
    """Return the smallest and largest exposure counts observed."""
    counts = sorted(exposures.values())
    return counts[0], counts[-1]


def format_contact_lines(contact_map: ContactMap) -> ContactList:
    """Render one readable line per infected person and their contacts."""
    lines: ContactList = []
    for infected in sorted(contact_map):
        names = ", ".join(sorted(contact_map[infected]))
        lines.append(f"{infected} -> {names}")
    return lines


def rank_by_exposure(exposures: ExposureCounts) -> Ranking:
    """Order contacts by descending exposure count, breaking ties alphabetically."""
    return sorted(exposures.items(), key=lambda item: (-item[1], item[0]))


def main() -> None:
    interactions: InteractionLog = [
        ("Alice", "Bob"),
        ("Charlie", "Bob"),
        ("Dave", "Bob"),
        ("Alice", "Eve"),
        ("Charlie", "Eve"),
        ("Dave", "Eve"),
        ("Alice", "Bob"),
        ("Frank", "Gina"),
    ]

    contact_map = build_contact_map(interactions)
    for line in format_contact_lines(contact_map):
        print(line)

    exposures = count_exposures(contact_map)
    low, high = exposure_extremes(exposures)
    print(f"exposure counts range from {low} to {high}")

    for name, hits in rank_by_exposure(exposures):
        print(f"{name:<8}{hits}")

    print("super spreader nodes:", trace(interactions))


if __name__ == "__main__":
    main()

