Shift = tuple[str, str, int]
ShiftLog = list[Shift]
FaultTotals = dict[str, int]
ZoneTotal = tuple[str, int]
Ranking = list[ZoneTotal]
Shares = dict[str, float]

LATERAL_DIRECTIONS = frozenset({"lateral", "left-lateral", "right-lateral"})


def filter_lateral(shifts: ShiftLog) -> ShiftLog:
    """Keep only the records whose direction describes lateral motion."""
    lateral: ShiftLog = []
    for name, direction, distance in shifts:
        if direction.strip().lower() in LATERAL_DIRECTIONS:
            lateral.append((name, direction, distance))
    return lateral


def accumulate(shifts: ShiftLog) -> FaultTotals:
    """Sum displacement per fault name."""
    totals: FaultTotals = {}
    for name, _direction, distance in shifts:
        totals[name] = totals.get(name, 0) + distance
    return totals


def rank(totals: FaultTotals) -> Ranking:
    """Order faults by total displacement, descending, then by name."""
    return sorted(totals.items(), key=lambda item: (-item[1], item[0]))


def process(shifts: ShiftLog) -> Ranking:
    return rank(accumulate(filter_lateral(shifts)))


def validate(shifts: ShiftLog) -> list[str]:
    """Report records that cannot be interpreted as GPS shift measurements."""
    problems: list[str] = []
    for index, record in enumerate(shifts):
        if len(record) != 3:
            problems.append(f"record {index}: expected 3 fields, got {len(record)}")
            continue
        name, direction, distance = record
        if not isinstance(name, str) or not name:
            problems.append(f"record {index}: fault name must be a non-empty string")
        if not isinstance(direction, str):
            problems.append(f"record {index}: direction must be a string")
        if not isinstance(distance, int) or distance < 0:
            problems.append(f"record {index}: displacement must be a non-negative integer")
    return problems


def zone_shares(ranking: Ranking) -> Shares:
    """Percentage of the overall lateral movement attributable to each fault."""
    overall = sum(distance for _name, distance in ranking)
    if overall == 0:
        return {name: 0.0 for name, _distance in ranking}
    return {name: 100.0 * distance / overall for name, distance in ranking}


def format_report(ranking: Ranking) -> str:
    shares: Shares = zone_shares(ranking)
    lines: list[str] = ["Fault              Lateral (mm)   Share"]
    for name, distance in ranking:
        lines.append(f"{name:<18} {distance:>12}  {shares[name]:>5.1f}%")
    return "\n".join(lines)


def main() -> None:
    measurements: ShiftLog = [
        ("SanAndreas", "lateral", 30),
        ("SanAndreas", "vertical", 10),
        ("Alpine", "lateral", 40),
        ("Alpine", "right-lateral", 15),
        ("Denali", "left-lateral", 22),
        ("Denali", "oblique", 8),
    ]
    for problem in validate(measurements):
        print("warning:", problem)
    ranking: Ranking = process(measurements)
    print(ranking)
    print(format_report(ranking))


if __name__ == "__main__":
    main()

