DEPLETION_THRESHOLD = 220

Reading = tuple[int, int, int]
ReadingList = list[Reading]
YearCount = tuple[int, int]
MonthList = list[int]
MonthsByYear = dict[int, MonthList]

MONTH_NAMES: dict[int, str] = {
    1: "Jan", 2: "Feb", 3: "Mar", 4: "Apr", 5: "May", 6: "Jun",
    7: "Jul", 8: "Aug", 9: "Sep", 10: "Oct", 11: "Nov", 12: "Dec",
}


def validate(readings: ReadingList) -> None:
    """Reject malformed satellite records before any aggregation happens."""
    for year, month, thickness in readings:
        if month < 1 or month > 12:
            raise ValueError(f"invalid month {month} in year {year}")
        if thickness < 0:
            raise ValueError(f"negative ozone thickness {thickness} in {year}-{month}")


def depleted_months(readings: ReadingList) -> MonthsByYear:
    """Map each year to the sorted months whose column reading shows depletion."""
    grouped: MonthsByYear = {}
    for year, month, thickness in readings:
        if thickness < DEPLETION_THRESHOLD:
            grouped.setdefault(year, []).append(month)
    for months in grouped.values():
        months.sort()
    return grouped


def monitor(readings: ReadingList) -> list[YearCount]:
    """Count depleted months per year, chronologically ordered."""
    validate(readings)
    grouped = depleted_months(readings)
    return [(year, len(grouped[year])) for year in sorted(grouped)]


def month_labels(months: MonthList) -> str:
    return ", ".join(MONTH_NAMES[month] for month in months)


def format_report(
    counts: list[YearCount],
    grouped: MonthsByYear,
) -> list[str]:
    lines: list[str] = []
    for year, count in counts:
        plural = "month" if count == 1 else "months"
        lines.append(f"{year}: {count} {plural} depleted ({month_labels(grouped[year])})")
    return lines


def worst_years(
    counts: list[YearCount],
) -> list[int]:
    """Years tied for the highest number of depleted months."""
    if not counts:
        return []
    peak = max(count for _, count in counts)
    return [year for year, count in counts if count == peak]


def main() -> None:
    readings: ReadingList = [
        (2000, 9, 200), (2000, 10, 210), (2000, 11, 250), (2001, 9, 190),
        (2001, 10, 205), (2001, 11, 219), (2002, 9, 230), (2002, 10, 221),
        (2003, 8, 218), (2003, 9, 175), (2003, 10, 199), (2003, 11, 240),
    ]
    counts = monitor(readings)
    grouped = depleted_months(readings)
    print(f"Ozone depletion summary (threshold {DEPLETION_THRESHOLD} units)")
    for line in format_report(counts, grouped):
        print("  " + line)
    total = sum(count for _, count in counts)
    print(f"Total depleted months: {total}")
    print("Worst years: " + ", ".join(str(year) for year in worst_years(counts)))
    print("Raw result:", counts)


if __name__ == "__main__":
    main()

