THRESHOLD = 50

Reading = tuple[str, int, int]
Sample = tuple[int, int]
Onset = tuple[str, int]
Series = list[Sample]
SeriesByStation = dict[str, Series]


def group_by_station(
    amplitudes: list[Reading],
) -> SeriesByStation:
    """Group (timestamp, amplitude) readings by station identifier."""
    grouped: SeriesByStation = {}
    for station, timestamp, amplitude in amplitudes:
        grouped.setdefault(station, []).append((timestamp, amplitude))
    return grouped


def find_onset(readings: Series) -> int | None:
    """Return the earliest timestamp whose amplitude exceeds the threshold."""
    onset: int | None = None
    for timestamp, amplitude in sorted(readings):
        if amplitude > THRESHOLD:
            onset = timestamp
            break
    return onset


def detect(
    amplitudes: list[Reading],
) -> list[Onset]:
    """Isolate the primary-wave onset per station, earliest onset first."""
    onsets: list[Onset] = []
    for station, readings in group_by_station(amplitudes).items():
        onset = find_onset(readings)
        if onset is not None:
            onsets.append((station, onset))
    onsets.sort(key=lambda entry: entry[1])
    return onsets


def relative_delays(
    onsets: list[Onset],
) -> dict[str, int]:
    """Delay of each station's onset relative to the first station to trigger."""
    if not onsets:
        return {}
    reference = onsets[0][1]
    return {station: onset - reference for station, onset in onsets}


def peak_amplitudes(
    amplitudes: list[Reading],
) -> dict[str, int]:
    """Largest amplitude recorded at each station."""
    peaks: dict[str, int] = {}
    for station, _, amplitude in amplitudes:
        if amplitude > peaks.get(station, 0):
            peaks[station] = amplitude
    return peaks


def format_report(
    onsets: list[Onset],
    peaks: dict[str, int],
) -> list[str]:
    delays = relative_delays(onsets)
    lines: list[str] = []
    for station, onset in onsets:
        lines.append(
            f"{station}: onset t={onset}, +{delays[station]}s, peak {peaks[station]}"
        )
    return lines


def main() -> None:
    readings: list[Reading] = [
        ("S1", 100, 10),
        ("S1", 105, 60),
        ("S2", 102, 55),
        ("S2", 108, 71),
        ("S3", 101, 22),
        ("S3", 111, 90),
    ]
    onsets = detect(readings)
    print(onsets)
    for line in format_report(onsets, peaks=peak_amplitudes(readings)):
        print(line)


if __name__ == "__main__":
    main()

