Reading = tuple[str, float, float]
SiteProfile = list[Reading]
ThawResult = tuple[str, float]


def parse_readings(
    lines: list[str],
) -> list[Reading]:
    """Turn 'site,depth,temperature' text rows into borehole readings."""
    readings: list[Reading] = []
    for line in lines:
        fields = line.split(",")
        if len(fields) != 3:
            raise ValueError(f"expected 3 fields, got {len(fields)}: {line!r}")
        site = fields[0].strip()
        depth = float(fields[1])
        temperature = float(fields[2])
        if not site:
            raise ValueError(f"missing site name: {line!r}")
        if depth < 0.0:
            raise ValueError(f"depth must not be negative: {depth}")
        readings.append((site, depth, temperature))
    return readings


def group_by_site(
    boreholes: list[Reading],
) -> dict[str, SiteProfile]:
    """Collect every reading belonging to the same site."""
    grouped: dict[str, SiteProfile] = {}
    for reading in boreholes:
        grouped.setdefault(reading[0], []).append(reading)
    return grouped


def max_thaw_depth(profile: SiteProfile) -> float:
    """Deepest measurement above freezing, or -1.0 if the site stayed frozen."""
    thawed: list[float] = [depth for _, depth, temp in profile if temp > 0.0]
    return max(thawed, default=-1.0)


def track(
    boreholes: list[Reading],
) -> list[ThawResult]:
    grouped = group_by_site(boreholes)
    results: list[ThawResult] = []
    for site in sorted(grouped):
        depth = max_thaw_depth(grouped[site])
        if depth >= 0.0:
            results.append((site, depth))
    return results


def count_thawed_layers(
    grouped: dict[str, SiteProfile],
) -> dict[str, int]:
    """How many individual readings are above freezing at each site."""
    counts: dict[str, int] = {}
    for site, profile in grouped.items():
        counts[site] = sum(1 for _, _, temp in profile if temp > 0.0)
    return counts


def format_report(
    results: list[ThawResult],
    counts: dict[str, int],
) -> list[str]:
    lines: list[str] = []
    for site, depth in results:
        lines.append(f"{site}: thaw depth {depth:.2f} m ({counts[site]} thawed layers)")
    return lines


def main() -> None:
    raw_rows: list[str] = [
        "SiteA,1.0,2.5",
        "SiteA,2.0,-1.0",
        "SiteB,1.5,0.5",
        "SiteB,0.5,3.1",
        "SiteC,1.0,-0.4",
    ]
    boreholes = parse_readings(raw_rows)
    results = track(boreholes)
    counts = count_thawed_layers(group_by_site(boreholes))
    print(results)
    for line in format_report(results, counts):
        print(line)


if __name__ == "__main__":
    main()

