Record = tuple[str, int, int]
DaySample = tuple[int, int]
DamSeries = list[DaySample]
DamGroups = dict[str, DamSeries]

THRESHOLD = 1000


def parse_record(line: str) -> Record:
    parts = [part.strip() for part in line.split(",")]
    if len(parts) != 3:
        raise ValueError(f"malformed inflow record: {line!r}")
    name, day, rate = parts
    return name, int(day), int(rate)


def parse_records(
    lines: list[str],
) -> list[Record]:
    return [parse_record(line) for line in lines if line.strip()]


def group_by_dam(
    inflows: list[Record],
) -> DamGroups:
    groups: DamGroups = {}
    for name, day, rate in inflows:
        groups.setdefault(name, []).append((day, rate))
    for series in groups.values():
        series.sort(key=lambda sample: sample[0])
    return groups


def rolling_totals(series: DamSeries) -> list[int]:
    totals: list[int] = []
    running = 0
    for _day, rate in series:
        running += rate
        totals.append(running)
    return totals


def peak_totals(groups: DamGroups) -> dict[str, int]:
    return {
        name: max(rolling_totals(series), default=0)
        for name, series in groups.items()
    }


def optimize(
    inflows: list[Record],
) -> list[str]:
    groups = group_by_dam(inflows)
    exceeded: list[str] = []
    for name in sorted(groups):
        if any(total > THRESHOLD for total in rolling_totals(groups[name])):
            exceeded.append(name)
    return exceeded


def format_report(
    peaks: dict[str, int],
    exceeded: list[str],
) -> list[str]:
    flagged = set(exceeded)
    lines: list[str] = []
    for name in sorted(peaks):
        action = "release water" if name in flagged else "hold"
        lines.append(f"{name}: peak {peaks[name]} units -> {action}")
    return lines


def main() -> None:
    raw_lines: list[str] = [
        "Dam1, 1, 600",
        "Dam1, 2, 500",
        "Dam2, 1, 400",
        "Dam3, 3, 700",
        "Dam3, 1, 250",
        "Dam3, 2, 120",
    ]
    records = parse_records(raw_lines)
    exceeded = optimize(records)
    peaks: dict[str, int] = peak_totals(group_by_dam(records))
    for line in format_report(peaks, exceeded):
        print(line)
    print("dams over threshold:", exceeded)


if __name__ == "__main__":
    main()

