Reading = tuple[str, int]
Readings = list[int]
WellLog = dict[str, Readings]


def group_readings(pressures: list[Reading]) -> WellLog:
    """Collect every pressure reading under its well identifier."""
    grouped: WellLog = {}
    for well, pressure in pressures:
        grouped.setdefault(well, []).append(pressure)
    return grouped


def median_pressure(readings: Readings) -> int:
    """Median of a well's readings: sort, then take the middle value."""
    ordered = sorted(readings)
    middle = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) // 2


def estimate(pressures):
    """Return (well, median pressure) for productive wells, best first."""
    grouped = group_readings(pressures)
    medians: list[Reading] = []
    for well, readings in grouped.items():
        value = median_pressure(readings)
        if value > 50:
            medians.append((well, value))
    medians.sort(key=lambda item: (-item[1], item[0]))
    return medians


def pressure_range(readings: Readings) -> tuple[int, int]:
    """Lowest and highest pressure recorded for a single well."""
    return min(readings), max(readings)


def reading_counts(
    pressures: list[Reading],
) -> dict[str, int]:
    """How many readings each well contributed."""
    counts: dict[str, int] = {}
    for well, _pressure in pressures:
        counts[well] = counts.get(well, 0) + 1
    return counts


def format_report(
    pressures: list[Reading],
) -> list[str]:
    """Human readable summary of the productive wells."""
    grouped = group_readings(pressures)
    counts = reading_counts(pressures)
    lines: list[str] = []
    for well, value in estimate(pressures):
        low, high = pressure_range(grouped[well])
        lines.append(
            f"{well}: median {value} bar from {counts[well]} readings "
            f"(range {low}-{high})"
        )
    if not lines:
        lines.append("No well reached a median pressure above 50 bar.")
    return lines


def main() -> None:
    field_data: list[Reading] = [
        ("W1", 40),
        ("W1", 60),
        ("W1", 80),
        ("W2", 30),
        ("W3", 55),
        ("W3", 95),
        ("W3", 70),
        ("W4", 51),
    ]
    productive: list[Reading] = estimate(field_data)
    print(productive)
    for line in format_report(field_data):
        print(line)


if __name__ == "__main__":
    main()

