    for timeline in grouped.values():
        timeline.sort()
    return grouped


def longest_storm(timeline: Timeline) -> int:
    best = 0
    current = 0
    previous_hour: int | None = None
    for hour, score in timeline:
        if score > STORM_THRESHOLD:
            if previous_hour is not None and hour == previous_hour + 1:
                current += 1
            else:
                current = 1
            best = max(best, current)
        else:
            current = 0
        previous_hour = hour
    return best


def track(
    readings: List[Reading],
) -> List[StormSummary]:
    validate(readings)
    grouped = group_by_satellite(readings)
    summaries = [(name, longest_storm(tl)) for name, tl in grouped.items()]
    summaries.sort(key=lambda item: (-item[1], item[0]))
    return summaries


def count_readings(
    grouped: Dict[str, Timeline],
) -> Dict[str, int]:
    return {name: len(timeline) for name, timeline in grouped.items()}


def peak_scores(
    grouped: Dict[str, Timeline],
) -> Dict[str, int]:
    return {name: max(score for _, score in timeline) for name, timeline in grouped.items()}


def format_report(
    summaries: List[StormSummary],
    hours_seen: Dict[str, int],
    peaks: Dict[str, int],
) -> List[str]:
    return [
        f"{name}: longest storm {duration}h, "
        f"{hours_seen[name]} readings, peak {peaks[name]}"
        for name, duration in summaries
    ]


def main() -> None:
    readings: List[Reading] = [
        ("Sat1", 1, 60),
        ("Sat1", 2, 70),
        ("Sat1", 3, 40),
        ("Sat2", 1, 80),
        ("Sat3", 5, 95),
        ("Sat3", 6, 51),
        ("Sat3", 7, 88),
        ("Sat3", 9, 99),
    ]
    summaries = track(readings)
    print(summaries)
    grouped = group_by_satellite(readings)
    for line in format_report(summaries, count_readings(grouped), peak_scores(grouped)):
        print(line)


if __name__ == "__main__":
    main()

