Effect = tuple[int, str, int]


def parse_effects(
    rows: list[str],
) -> list[Effect]:
    effects: list[Effect] = []
    for row in rows:
        time_text, kind, radius_text = (part.strip() for part in row.split(","))
        effects.append((int(time_text), kind, int(radius_text)))
    return effects


def validate(effects: list[Effect]) -> None:
    for ignition_time, kind, radius in effects:
        if ignition_time < 0:
            raise ValueError(f"negative ignition time for {kind}: {ignition_time}")
        if radius <= 0:
            raise ValueError(f"non-positive burst radius for {kind}: {radius}")


def interval_start(ignition_time: int) -> int:
    return ignition_time - ignition_time % 10


def best_by_interval(effects: list[Effect]):
    best: dict[int, Effect] = {}
    for effect in effects:
        start = interval_start(effect[0])
        current = best.get(start)
        if current is None or effect[2] > current[2]:
            best[start] = effect
    return best


def sequence(effects: list[Effect]):
    validate(effects)
    best = best_by_interval(effects)
    chosen: list[str] = []
    radii: dict[int, int] = {}
    for start in sorted(best):
        _, kind, radius = best[start]
        chosen.append(kind)
        radii[start] = radius
    return chosen, radii


def dropped_counts(
    effects: list[Effect],
    radii: dict[int, int],
) -> dict[str, int]:
    dropped: dict[str, int] = {}
    for ignition_time, kind, radius in effects:
        if radii.get(interval_start(ignition_time)) != radius:
            dropped[kind] = dropped.get(kind, 0) + 1
    return dropped


def format_report(
    chosen: list[str],
    radii: dict[int, int],
    dropped: dict[str, int],
) -> list[str]:
    lines: list[str] = []
    for kind, start in zip(chosen, sorted(radii)):
        lines.append(f"t={start:>3}s  {kind:<7} radius {radii[start]}m")
    for kind in sorted(dropped):
        lines.append(f"skipped {dropped[kind]}x {kind}")
    return lines


def main() -> None:
    rows: list[str] = [
        "2, red, 15",
        "5, blue, 20",
        "12, green, 10",
        "17, silver, 30",
        "34, gold, 25",
    ]
    effects = parse_effects(rows)
    chosen, radii = sequence(effects)
    for line in format_report(chosen, radii, dropped_counts(effects, radii)):
        print(line)


if __name__ == "__main__":
    main()

