Crease = tuple[int, int, str]
CreaseList = list[Crease]
Groups = dict[int, CreaseList]
FoldCounts = dict[str, int]
Violations = list[int]
Totals = dict[int, int]
Result = tuple[Violations, Totals]

FOLD_TYPES = ("mountain", "valley")
MAX_IMBALANCE = 2


def parse_pattern(rows: list[str]) -> CreaseList:
    """Turn textual rows like '1 101 mountain' into crease tuples."""
    creases: CreaseList = []
    for row in rows:
        parts = row.split()
        if len(parts) != 3:
            raise ValueError(f"malformed crease row: {row!r}")
        point, identifier, fold = parts
        creases.append((int(point), int(identifier), fold.lower()))
    return creases


def find_duplicate_ids(creases: CreaseList) -> list[int]:
    """Crease identifiers must be unique across the whole pattern."""
    owners: dict[int, int] = {}
    duplicates: list[int] = []
    for point, identifier, _ in creases:
        if identifier in owners:
            duplicates.append(identifier)
        else:
            owners[identifier] = point
    return duplicates


def group_by_point(creases: CreaseList) -> Groups:
    groups: Groups = {}
    for point, identifier, fold in creases:
        if fold not in FOLD_TYPES:
            raise ValueError(f"unknown fold type {fold!r} for crease {identifier}")
        groups.setdefault(point, []).append((point, identifier, fold))
    return groups


def count_folds(folds: CreaseList) -> FoldCounts:
    tally: dict[str, int] = {name: 0 for name in FOLD_TYPES}
    for _, _, fold in folds:
        tally[fold] += 1
    return tally


def validate(creases) -> Result:
    """A vertex lies flat while its mountain and valley counts stay within two."""
    groups = group_by_point(creases)
    violations: Violations = []
    totals: Totals = {}
    for point in sorted(groups):
        folds = groups[point]
        tally = count_folds(folds)
        if abs(tally["mountain"] - tally["valley"]) <= MAX_IMBALANCE:
            totals[point] = len(folds)
        else:
            violations.append(point)
    return violations, totals


def format_report(violations: Violations, totals: Totals) -> list[str]:
    lines: list[str] = []
    for point, count in sorted(totals.items()):
        lines.append(f"vertex {point}: flat-foldable with {count} creases")
    for point in violations:
        lines.append(f"vertex {point}: mountain/valley counts too unbalanced")
    return lines


def main() -> None:
    pattern: list[str] = [
        "1 101 mountain",
        "1 102 mountain",
        "1 103 valley",
        "2 201 mountain",
        "2 202 valley",
        "3 301 mountain",
        "3 302 mountain",
        "3 303 mountain",
        "3 304 valley",
        "4 401 mountain",
        "4 402 mountain",
        "4 403 mountain",
        "4 404 mountain",
    ]
    creases = parse_pattern(pattern)
    duplicates = find_duplicate_ids(creases)
    if duplicates:
        raise ValueError(f"duplicate crease identifiers: {duplicates}")
    violations, totals = validate(creases)
    print((violations, totals))
    for line in format_report(violations, totals):
        print(line)


if __name__ == "__main__":
    main()

