from __future__ import annotations

Triple = tuple[int, int, int]
Neighbours = list[int]
SafeMap = dict[int, Neighbours]
UnsafeIds = list[int]
Pair = tuple[int, int]

MAX_AGE_GAP = 2


def build_age_limits(
    zones: list[Triple],
) -> dict[int, int]:
    """Map every zone identifier to the age limit declared for it."""
    ages: dict[int, int] = {}
    for zone_id, _adjacent, limit in zones:
        ages[zone_id] = limit
    return ages


def validate(
    zones: list[Triple],
    ages: dict[int, int],
) -> None:
    missing: list[int] = [adjacent for _, adjacent, _ in zones if adjacent not in ages]
    if missing:
        raise ValueError(f"no age limit declared for zones: {sorted(set(missing))}")


def build_adjacency(
    zones: list[Triple],
) -> dict[int, Neighbours]:
    adjacency: SafeMap = {}
    for zone_id, adjacent, _limit in zones:
        neighbours: list[int] = adjacency.setdefault(zone_id, [])
        if adjacent not in neighbours:
            neighbours.append(adjacent)
    return adjacency


def unsafe_pairs(
    zones: list[Triple],
    ages: dict[int, int],
) -> list[Pair]:
    pairs: list[Pair] = []
    for zone_id, adjacent, limit in zones:
        if abs(limit - ages[adjacent]) > MAX_AGE_GAP:
            pairs.append((zone_id, adjacent))
    return pairs


def unsafe_ids(pairs: list[Pair]) -> UnsafeIds:
    flagged: list[int] = []
    for first, second in pairs:
        for zone_id in (first, second):
            if zone_id not in flagged:
                flagged.append(zone_id)
    return sorted(flagged)


def safe_layout(
    adjacency: dict[int, Neighbours],
    flagged: list[int],
) -> SafeMap:
    safe: SafeMap = {}
    for zone_id, neighbours in sorted(adjacency.items()):
        if zone_id not in flagged:
            safe[zone_id] = sorted(neighbours)
    return safe


def layout(
    zones: list[Triple],
) -> tuple[UnsafeIds, SafeMap]:
    ages = build_age_limits(zones)
    validate(zones, ages)
    flagged = unsafe_ids(unsafe_pairs(zones, ages))
    return flagged, safe_layout(build_adjacency(zones), flagged)


def format_report(flagged: UnsafeIds, safe: SafeMap) -> str:
    lines: list[str] = ["unsafe zones: " + (", ".join(map(str, flagged)) or "none")]
    for zone_id, neighbours in safe.items():
        lines.append(f"zone {zone_id} safely connects to {neighbours}")
    return "\n".join(lines)


def main() -> None:
    park: list[Triple] = [(1, 2, 8), (2, 1, 12), (3, 4, 10), (4, 3, 11), (4, 5, 11), (5, 4, 9)]
    flagged, safe = layout(park)
    print(format_report(flagged, safe))


if __name__ == "__main__":
    main()

