    """Turn a "index,pressure,angle" record into a stroke tuple."""
    parts: list[str] = [field.strip() for field in raw.split(",")]
    if len(parts) != 3:
        raise ValueError(f"malformed stroke record: {raw!r}")
    index, pressure, angle = int(parts[0]), float(parts[1]), int(parts[2])
    if pressure < 0.0:
        raise ValueError(f"negative pressure in record: {raw!r}")
    if not 0 <= angle <= 360:
        raise ValueError(f"angle out of range in record: {raw!r}")
    return index, pressure, angle


def load_strokes(
    records: list[str],
) -> list[Stroke]:
    """Parse every raw record of a capture session."""
    return [parse_stroke(record) for record in records]


def split_characters(
    strokes: list[Stroke],
) -> list[Block]:
    """Zero-pressure strokes are pen lifts; they separate characters."""
    blocks: list[Block] = []
    current: Block = []
    for stroke in strokes:
        if stroke[1] == 0.0:
            if current:
                blocks.append(current)
                current = []
            continue
        current.append(stroke)
    if current:
