Jet = tuple[int, int, int]
Schedule = list[Jet]
Totals = dict[int, int]
IdGroup = list[int]
Groups = dict[int, IdGroup]


def validate_jets(jets: Schedule) -> None:
    """Ensure every jet record is a triple of non-negative integers."""
    seen: set[int] = set()
    for record in jets:
        if len(record) != 3:
            raise ValueError(f"jet record must have 3 fields: {record!r}")
        jet_id, height, delay = record
        if not all(isinstance(value, int) for value in record):
            raise TypeError(f"jet fields must be integers: {record!r}")
        if height < 0 or delay < 0:
            raise ValueError(f"height and delay must be non-negative: {record!r}")
        if jet_id in seen:
            raise ValueError(f"duplicate jet identifier: {jet_id}")
        seen.add(jet_id)


def group_by_delay(jets: Schedule) -> Groups:
    """Map each activation delay to the identifiers of the jets that use it."""
    groups: Groups = {}
    for jet_id, _height, delay in jets:
        groups.setdefault(delay, []).append(jet_id)
    return groups


def total_heights(jets: Schedule) -> Totals:
    """Sum the maximum heights of the jets sharing each activation delay."""
    totals: Totals = {}
    for _jet_id, height, delay in jets:
        totals[delay] = totals.get(delay, 0) + height
    return totals


def strongest_delay(totals: Totals) -> int:
    """Return the delay whose jets reach the greatest combined height."""
    return min(totals, key=lambda delay: (-totals[delay], delay))


def synchronize(jets: Schedule) -> tuple[IdGroup, Totals]:
    validate_jets(jets)
    totals = total_heights(jets)
    if not totals:
        return [], totals
    groups = group_by_delay(jets)
    return groups[strongest_delay(totals)], totals


def format_report(leaders: IdGroup, totals: Totals) -> str:
    """Render a human readable summary of the synchronization result."""
    lines: list[str] = []
    peak = max(totals.values(), default=0)
    for delay in sorted(totals):
        marker = "*" if totals[delay] == peak else " "
        lines.append(f"{marker} delay {delay:>3}s -> total height {totals[delay]:>4}")
    lines.append("lead group: " + ", ".join(f"jet {jet_id}" for jet_id in leaders))
    return "\n".join(lines)


def main() -> None:
    show: Schedule = [
        (1, 10, 5),
        (2, 15, 5),
        (3, 20, 10),
        (4, 8, 10),
        (5, 30, 2),
    ]
    leaders, totals = synchronize(show)
    print(leaders, totals)
    print(format_report(leaders, totals))


if __name__ == "__main__":
    main()

