from itertools import combinations

Point = tuple[int, int]
Track = list[Point]
Paths = dict[int, Track]
DronePair = tuple[int, int]
PairList = list[DronePair]
RiskMap = dict[int, PairList]
StepList = list[int]
Result = tuple[StepList, RiskMap]


def _common_length(paths: Paths) -> int:
    """Number of time steps that every drone actually reports."""
    if not paths:
        raise ValueError("at least one drone path is required")
    lengths: list[int] = [len(track) for track in paths.values()]
    return min(lengths)


def _positions_at(paths: Paths, step: int) -> dict[int, Point]:
    """Coordinates of every drone at a single time step."""
    return {drone: track[step] for drone, track in paths.items()}


def _colliding_pairs(positions: dict[int, Point]) -> PairList:
    """Every unique drone pair sharing one coordinate at this instant."""
    pairs: PairList = []
    for first, second in combinations(sorted(positions), 2):
        if positions[first] == positions[second]:
            pairs.append((first, second))
    return pairs


def calculate(paths: Paths) -> Result:
    limit = _common_length(paths)
    risky_steps: StepList = []
    risks: RiskMap = {}
    for step in range(limit):
        pairs = _colliding_pairs(_positions_at(paths, step))
        if pairs:
            risky_steps.append(step)
            risks[step] = pairs
    return risky_steps, risks


def count_risks_per_drone(risks: RiskMap) -> dict[str, int]:
    """How many collision risks each drone is involved in."""
    counts: dict[str, int] = {}
    for pairs in risks.values():
        for first, second in pairs:
            for drone in (first, second):
                label = f"drone-{drone}"
                counts[label] = counts.get(label, 0) + 1
    return counts


def format_report(risky_steps: StepList, risks: RiskMap) -> list[str]:
    lines: list[str] = []
    for step in risky_steps:
        for first, second in risks[step]:
            lines.append(f"t={step}: drones {first} and {second} share a position")
    if not lines:
        lines.append("no collision risk detected")
    involved: dict[str, int] = count_risks_per_drone(risks)
    for label, total in sorted(involved.items()):
        lines.append(f"{label} involved in {total} risk(s)")
    return lines


def main() -> None:
    display: Paths = {
        1: [(0, 0), (1, 1), (2, 2), (3, 3)],
        2: [(0, 1), (1, 1), (2, 3), (3, 3)],
        3: [(5, 5), (4, 4), (2, 3), (1, 0)],
    }
    risky_steps, risks = calculate(display)
    print(risky_steps, risks)
    for line in format_report(risky_steps, risks):
        print(line)


if __name__ == "__main__":
    main()

