"""Analyze the scoring progression of a tactical match."""

Event = tuple[int, str, int]
Action = tuple[int, str]
Timeline = list[Action]
PlayerResult = tuple[int, bool]
Summary = dict[int, PlayerResult]
Ranking = list[int]
Report = tuple[Ranking, Summary]

CAPTURE_POINTS: dict[str, int] = {"capture": 10}
VALID_ACTIONS = ("capture", "elimination")


def validate_events(events: list[Event]) -> None:
    for timestamp, action, player in events:
        if action not in VALID_ACTIONS:
            raise ValueError(
                f"unknown action {action!r} at t={timestamp} for player {player}"
            )


def collect_players(
    events: list[Event],
) -> list[int]:
    players: list[int] = []
    for _, _, player in events:
        if player not in players:
            players.append(player)
    return players


def player_timeline(events: list[Event], player: int) -> Timeline:
    timeline: Timeline = [(t, a) for t, a, p in events if p == player]
    timeline.sort()
    return timeline


def resolve_score(timeline: Timeline) -> PlayerResult:
    total = 0
    eliminated = False
    for _, action in timeline:
        if action == "elimination":
            eliminated = True
            break
        total += CAPTURE_POINTS[action]
    return total, eliminated


def score(events: list[Event]) -> Report:
    validate_events(events)
    summary: Summary = {}
    for player in collect_players(events):
        summary[player] = resolve_score(player_timeline(events, player))
    ranking: Ranking = sorted(summary, key=lambda p: (-summary[p][0], p))
    return ranking, summary


def format_report(ranking: Ranking, summary: Summary) -> list[str]:
    lines: list[str] = []
    for rank, player in enumerate(ranking, start=1):
        total, eliminated = summary[player]
        state = "eliminated" if eliminated else "active"
        lines.append(f"{rank}. player {player}: {total} pts ({state})")
    return lines


def status_counts(summary: Summary) -> dict[str, int]:
    counts: dict[str, int] = {"active": 0, "eliminated": 0}
    for _, eliminated in summary.values():
        counts["eliminated" if eliminated else "active"] += 1
    return counts


def main() -> None:
    events: list[Event] = [
        (1, "capture", 101),
        (2, "elimination", 101),
        (3, "capture", 101),
        (1, "capture", 102),
        (4, "capture", 102),
        (5, "capture", 103),
        (6, "elimination", 103),
    ]
    ranking, summary = score(events)
    print(ranking)
    print(summary)
    for line in format_report(ranking, summary):
        print(line)
    counts: dict[str, int] = status_counts(summary)
    print(f"active={counts['active']} eliminated={counts['eliminated']}")


if __name__ == "__main__":
    main()

