from typing import Dict, List, Tuple

Reading = Tuple[int, int, int]
Starts = List[int]
Averages = Dict[int, float]

_SECTORS = ("N", "NE", "E", "SE", "S", "SW", "W", "NW")


def parse_reading(line: str) -> Reading:
    fields: List[str] = [part.strip() for part in line.split(",")]
    if len(fields) != 3:
        raise ValueError(f"expected 'time, speed, direction' but got {line!r}")
    time, speed, direction = (int(field) for field in fields)
    if speed < 0:
        raise ValueError(f"wind speed cannot be negative: {speed}")
    return time, speed, direction


def load_readings(
    lines: List[str],
) -> List[Reading]:
    readings = [parse_reading(line) for line in lines if line.strip()]
    return sorted(readings, key=lambda reading: reading[0])


def speeds_of(
    window: List[Reading],
) -> List[int]:
    return [speed for _, speed, _ in window]


def is_stable(block: List[int]) -> bool:
    return all(abs(later - earlier) <= 2 for earlier, later in zip(block, block[1:]))


def mean_speed(block: List[int]) -> float:
    return sum(block) / len(block)


def analyze(
    readings: List[Reading],
) -> Tuple[Starts, Averages]:
    starts: List[int] = []
    averages: Dict[int, float] = {}
    for index in range(len(readings) - 2):
        window = readings[index:index + 3]
        block = speeds_of(window)
        if is_stable(block):
            start_time = window[0][0]
            starts.append(start_time)
            averages[start_time] = mean_speed(block)
    return starts, averages


def direction_label(degrees: int) -> str:
    sector = round((degrees % 360) / 45) % 8
    return _SECTORS[sector]


def start_directions(
    readings: List[Reading],
    starts: List[int],
) -> Dict[int, str]:
    by_time = {time: direction for time, _, direction in readings}
    return {start: direction_label(by_time[start]) for start in starts}


def format_report(
    starts: List[int],
    averages: Dict[int, float],
    directions: Dict[int, str],
) -> List[str]:
    if not starts:
        return ["no stable periods found"]
    return [
        f"t={start}: avg {averages[start]:.2f} units from {directions[start]}"
        for start in starts
    ]


def main() -> None:
    raw: List[str] = [
        "1, 10, 90",
        "2, 11, 90",
        "3, 10, 95",
        "4, 18, 100",
        "5, 19, 110",
        "6, 20, 115",
    ]
    readings = load_readings(raw)
    starts, averages = analyze(readings)
    print((starts, averages))
    for line in format_report(starts, averages, start_directions(readings, starts)):
        print(line)


if __name__ == "__main__":
    main()

