from typing import Iterable

BOBBLE = "bobble"

Instruction = tuple[int, str, int]
ColorChanges = list[int]
StitchTotals = dict[str, int]
TrackResult = tuple[ColorChanges, StitchTotals]
RowTotals = dict[int, int]


def validate(instructions: Iterable[Instruction]) -> list[Instruction]:
    """Return the instructions as a list, rejecting malformed entries."""
    checked: list[Instruction] = []
    for entry in instructions:
        row, stitch, count = entry
        if not isinstance(row, int) or not isinstance(count, int):
            raise TypeError(f"row and count must be integers: {entry!r}")
        if not stitch:
            raise ValueError(f"stitch type must be non-empty: {entry!r}")
        if count < 0:
            raise ValueError(f"stitch count must not be negative: {entry!r}")
        checked.append((row, stitch, count))
    return checked


def tally_stitches(instructions: list[Instruction]) -> StitchTotals:
    """Accumulate the stitch counts per stitch type over all rows."""
    totals: dict[str, int] = {}
    for _, stitch, count in instructions:
        totals[stitch] = totals.get(stitch, 0) + count
    return totals


def find_color_changes(instructions: list[Instruction]) -> ColorChanges:
    """Collect, in order, the rows containing at least one bobble stitch."""
    rows: list[int] = []
    for row, stitch, _ in instructions:
        if stitch == BOBBLE and row not in rows:
            rows.append(row)
    return rows


def stitches_per_row(instructions: list[Instruction]) -> RowTotals:
    """Total number of stitches worked in each row."""
    per_row: dict[int, int] = {}
    for row, _, count in instructions:
        per_row[row] = per_row.get(row, 0) + count
    return per_row


def format_report(
    changes: list[int],
    totals: dict[str, int],
    per_row: RowTotals,
) -> list[str]:
    lines: list[str] = ["Pattern report"]
    for row in sorted(per_row):
        marker = " <- yarn color change" if row in changes else ""
        lines.append(f"  row {row}: {per_row[row]} stitches{marker}")
    for stitch in sorted(totals):
        lines.append(f"  {stitch}: {totals[stitch]} total")
    return lines


def track(instructions: Iterable[Instruction]) -> TrackResult:
    checked = validate(instructions)
    return find_color_changes(checked), tally_stitches(checked)


def main() -> None:
    pattern: list[Instruction] = [
        (1, "knit", 10),
        (2, "bobble", 5),
        (2, "purl", 7),
        (3, "knit", 10),
        (4, "bobble", 3),
    ]
    changes, totals = track(pattern)
    for line in format_report(changes, totals, stitches_per_row(pattern)):
        print(line)


if __name__ == "__main__":
    main()

