"""Coordinate the pouring sequence for layered scents.

Hotter waxes are poured first; waxes that share a melting point are poured
together as a single blended layer.
"""

WaxEntry = tuple[str, int, int]
WaxBatch = list[WaxEntry]
WaxNames = list[str]
MeltingOrder = list[int]
MeltingGroup = tuple[int, WaxNames]
PourPlan = dict[int, MeltingGroup]


def validate_waxes(waxes: WaxBatch) -> None:
    for position, entry in enumerate(waxes):
        if len(entry) != 3:
            raise ValueError(f"wax entry {position} needs a type, melting point and volume")
        wax_type, melting_point, volume = entry
        if not isinstance(wax_type, str) or not wax_type.strip():
            raise ValueError(f"wax entry {position} has an empty wax type")
        if melting_point <= 0:
            raise ValueError(f"{wax_type} has a non-positive melting point")
        if volume <= 0:
            raise ValueError(f"{wax_type} has a non-positive pour volume")


def combined_volumes(waxes: WaxBatch) -> dict[int, int]:
    totals: dict[int, int] = {}
    for _, melting_point, volume in waxes:
        totals[melting_point] = totals.get(melting_point, 0) + volume
    return totals


def types_by_melting_point(waxes: WaxBatch) -> dict[int, WaxNames]:
    grouped: dict[int, WaxNames] = {}
    for wax_type, melting_point, _ in waxes:
        grouped.setdefault(melting_point, []).append(wax_type)
    return grouped


def layer(waxes: WaxBatch) -> tuple[MeltingOrder, PourPlan]:
    validate_waxes(waxes)
    volumes = combined_volumes(waxes)
    names = types_by_melting_point(waxes)
    order: list[int] = sorted(volumes, reverse=True)
    plan: PourPlan = {point: (volumes[point], names[point]) for point in order}
    return order, plan


def batch_totals(plan: PourPlan) -> tuple[int, int]:
    layers = len(plan)
    poured = sum(volume for volume, _ in plan.values())
    return layers, poured


def describe_pour_sequence(order: MeltingOrder, plan: PourPlan) -> list[str]:
    lines: list[str] = []
    for step, melting_point in enumerate(order, start=1):
        volume, wax_types = plan[melting_point]
        blend = " + ".join(wax_types)
        lines.append(f"{step}. {melting_point}C -> {volume}ml ({blend})")
    layers, poured = batch_totals(plan)
    lines.append(f"{layers} layers, {poured}ml total")
    return lines


def main() -> None:
    batch: list[WaxEntry] = [
        ("soy", 120, 50),
        ("beeswax", 145, 30),
        ("paraffin", 120, 20),
        ("coconut", 98, 40),
    ]
    order, plan = layer(batch)
    print(order)
    print(plan)
    for line in describe_pour_sequence(order, plan):
        print(line)


if __name__ == "__main__":
    main()

