"""Stability assessment for packed granular structures."""

MoistureList = list[float]
LayerData = tuple[int, int, float]
Layers = list[LayerData]
Grouped = dict[int, MoistureList]
Heights = list[int]
Result = tuple[Heights, Grouped]

MIN_MOISTURE = 5.0


def validate(layers: Layers) -> None:
    """Reject malformed layer records before they are interpreted."""
    for index, layer in enumerate(layers):
        if len(layer) != 3:
            raise ValueError(f"layer {index} must hold height, grain size and moisture")
        height, grain, moisture = layer
        if height <= 0 or grain <= 0:
            raise ValueError(f"layer {index} has a non-positive height or grain size")
        if not 0.0 <= moisture <= 100.0:
            raise ValueError(f"layer {index} has moisture outside 0-100 percent")


def find_unstable(layers: Layers) -> list[int]:
    """Walk bottom to top and collect the heights of the unstable layers."""
    unstable: list[int] = []
    previous_grain: int | None = None
    for height, grain, moisture in layers:
        too_dry = moisture < MIN_MOISTURE
        too_coarse = previous_grain is not None and grain > previous_grain
        if too_dry or too_coarse:
            unstable.append(height)
        previous_grain = grain
    return unstable


def group_moisture(layers: Layers) -> Grouped:
    """Map every grain size to the moisture readings observed for it."""
    grouped: dict[int, MoistureList] = {}
    for _, grain, moisture in layers:
        readings: MoistureList = grouped.setdefault(grain, [])
        readings.append(moisture)
    return grouped


def assess(layers: Layers) -> Result:
    validate(layers)
    return find_unstable(layers), group_moisture(layers)


def driest_grain(grouped: Grouped) -> tuple[int, float]:
    """Return the grain size with the lowest mean moisture and that mean."""
    means: dict[int, float] = {
        grain: sum(readings) / len(readings) for grain, readings in grouped.items()
    }
    grain = min(means, key=lambda size: (means[size], size))
    return grain, means[grain]


def format_report(
    unstable: list[int],
    grouped: Grouped,
) -> list[str]:
    """Turn an assessment into human readable report lines."""
    lines: list[str] = []
    if unstable:
        lines.append("unstable heights: " + ", ".join(str(h) for h in unstable))
    else:
        lines.append("unstable heights: none")
    for grain in sorted(grouped):
        readings: MoistureList = grouped[grain]
        mean = sum(readings) / len(readings)
        lines.append(f"grain {grain}: {len(readings)} layer(s), mean moisture {mean:.1f}%")
    grain, mean = driest_grain(grouped)
    lines.append(f"driest grain size: {grain} at {mean:.1f}%")
    return lines


def main() -> None:
    sample: Layers = [(1, 2, 10.0), (2, 3, 12.0), (3, 1, 4.0)]
    unstable, grouped = assess(sample)
    print((unstable, grouped))
    for line in format_report(unstable, grouped):
        print(line)


if __name__ == "__main__":
    main()

