"""Categorize the repair materials needed for the horses of a carousel."""

MissingParts = list[str]
Positions = list[int]
PartCount = tuple[str, int]

Horses = dict[int, MissingParts]
Tally = list[PartCount]
Schedule = dict[int, Positions]
Report = tuple[Tally, Schedule]


def validate(horses: Horses) -> None:
    """Reject horse positions that cannot exist on a carousel."""
    bad: list[int] = [pos for pos in horses if pos < 1]
    if bad:
        raise ValueError(f"invalid horse positions: {sorted(bad)}")


def tally_parts(horses: Horses) -> dict[str, int]:
    """Count how often every part is missing across all horses."""
    counts: dict[str, int] = {}
    for parts in horses.values():
        for part in parts:
            counts[part] = counts.get(part, 0) + 1
    return counts


def order_parts(counts: dict[str, int]) -> Tally:
    """Sort parts by count descending, breaking ties alphabetically."""
    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))


def group_by_workload(horses: Horses) -> Schedule:
    """Map the number of missing parts to the horses that need that work."""
    schedule: dict[int, Positions] = {}
    for position, parts in sorted(horses.items()):
        schedule.setdefault(len(parts), []).append(position)
    return schedule


def restore(horses: Horses) -> Report:
    validate(horses)
    counts = tally_parts(horses)
    return order_parts(counts), group_by_workload(horses)


def format_shopping_list(tally: Tally) -> list[str]:
    lines = ["Parts to purchase:"]
    for part, count in tally:
        lines.append(f"  {count:>3} x {part}")
    return lines


def format_schedule(schedule: Schedule) -> list[str]:
    lines = ["Labor schedule (heaviest first):"]
    for missing in sorted(schedule, reverse=True):
        positions: Positions = schedule[missing]
        joined = ", ".join(str(pos) for pos in positions)
        lines.append(f"  {missing} part(s) missing -> horses {joined}")
    return lines


def main() -> None:
    carousel: Horses = {
        1: ["tail", "ear", "saddle"],
        2: ["tail"],
        3: ["tail", "ear"],
        4: [],
        5: ["mane", "saddle"],
    }
    tally, schedule = restore(carousel)
    for line in format_shopping_list(tally) + format_schedule(schedule):
        print(line)
    total = sum(count for _part, count in tally)
    print(f"Total parts needed: {total}")


if __name__ == "__main__":
    main()

