Strands = list[int]
Cross = tuple[int, int]
Crosses = list[Cross]
Knots = list[int]
Groups = dict[int, Knots]
WeaveResult = tuple[Knots, Groups]


def validate(strands: Strands, crosses: Crosses) -> None:
    """Reject weaves that reference a horizontal strand which does not exist."""
    if not strands:
        raise ValueError("at least one horizontal strand is required")
    for index, vertical in crosses:
        if not 0 <= index < len(strands):
            raise IndexError(f"cross weave at strand {index} is off the loom")
        if vertical < 0:
            raise ValueError(f"vertical strength {vertical} must not be negative")


def knot_integrity(horizontal: int, vertical: int) -> int:
    """Integrity of a single crossing: horizontal strand plus vertical strand."""
    return horizontal + vertical


def group_by_strand(crosses: Crosses, integrities: Knots) -> Groups:
    """Collect the knot integrities that sit on each horizontal strand."""
    groups: Groups = {}
    for (index, _vertical), integrity in zip(crosses, integrities):
        groups.setdefault(index, []).append(integrity)
    return groups


def weave(strands: Strands, crosses: Crosses) -> WeaveResult:
    """Evaluate every cross weave and group the results by horizontal index."""
    validate(strands, crosses)
    integrities: Knots = [
        knot_integrity(strands[index], vertical) for index, vertical in crosses
    ]
    return integrities, group_by_strand(crosses, integrities)


def strand_totals(groups: Groups) -> dict[int, int]:
    """Total load carried by each woven strand."""
    return {index: sum(values) for index, values in groups.items()}


def weakest_knot(
    integrities: Knots,
) -> tuple[int, int]:
    """Position and value of the least sturdy knot in the weave."""
    position, value = min(enumerate(integrities), key=lambda pair: pair[1])
    return position, value


def format_report(integrities: Knots, groups: Groups) -> list[str]:
    """Render a human readable summary of the evaluated weave."""
    lines = [f"knots evaluated: {len(integrities)}"]
    totals: dict[int, int] = strand_totals(groups)
    for index in sorted(groups):
        knots = ", ".join(str(value) for value in groups[index])
        lines.append(f"strand {index}: [{knots}] total={totals[index]}")
    position, value = weakest_knot(integrities)
    lines.append(f"weakest knot: #{position} with integrity {value}")
    return lines


def main() -> None:
    strands: Strands = [10, 20, 35]
    crosses: Crosses = [(0, 5), (1, 8), (0, 7), (2, 4), (1, 12)]
    integrities, groups = weave(strands, crosses)
    print(integrities)
    print(groups)
    for line in format_report(integrities, groups):
        print(line)


if __name__ == "__main__":
    main()

