from typing import Callable, Iterable, Sequence, Union

Number = Union[int, float]
Evaluation = tuple[str, Union[Number, str]]

OPERATIONS: dict[str, Callable[[Number, Number], Number]] = {
    "+": lambda a, b: a + b,
    "-": lambda a, b: a - b,
    "*": lambda a, b: a * b,
    "/": lambda a, b: a / b,
}


def simple_calculator(num1: Number, operator: str, num2: Number) -> Union[Number, str]:
    """Apply one of +, -, *, / to two numbers, returning 'Error' on bad input."""
    operation = OPERATIONS.get(operator)
    if operation is None:
        return "Error"
    if operator == "/" and num2 == 0:
        return "Error"
    return operation(num1, num2)


def to_number(token: str) -> Number:
    if "." in token:
        return float(token)
    return int(token)


def parse_expression(text: str) -> tuple[Number, str, Number]:
    """Split a string like '10 / 4' into its numeric and operator parts."""
    parts: list[str] = text.split()
    if len(parts) != 3:
        raise ValueError(f"cannot parse expression: {text!r}")
    left, operator, right = parts
    return to_number(left), operator, to_number(right)


def evaluate_all(expressions: Iterable[str]) -> list[Evaluation]:
    """Evaluate each textual expression, pairing it with its result."""
    results: list[Evaluation] = []
    for text in expressions:
        num1, operator, num2 = parse_expression(text)
        results.append((text, simple_calculator(num1, operator, num2)))
    return results


def count_operators(expressions: Iterable[str]) -> dict[str, int]:
    """Count how often each operator appears in the given expressions."""
    tally: dict[str, int] = {}
    for text in expressions:
        operator = parse_expression(text)[1]
        tally[operator] = tally.get(operator, 0) + 1
    return tally


def summarize(results: Sequence[Evaluation]) -> tuple[int, int]:
    """Return the number of successful and failed evaluations."""
    failures = sum(1 for _, value in results if value == "Error")
    return len(results) - failures, failures


def format_report(results: Sequence[Evaluation]) -> str:
    lines: list[str] = [f"{text} = {value}" for text, value in results]
    ok, failed = summarize(results)
    lines.append(f"{ok} succeeded, {failed} failed")
    return "\n".join(lines)


def main() -> None:
    expressions: list[str] = [
        "10 + 5",
        "10 / 0",
        "7.5 * 4",
        "9 - 12",
        "10 / 4",
        "3 % 2",
    ]
    print(format_report(evaluate_all(expressions)))
    for operator, count in sorted(count_operators(expressions).items()):
        print(f"operator {operator!r} used {count} time(s)")


if __name__ == "__main__":
    main()

