def list_intersection(
    list1: list[int],
    list2: list[int],
) -> list[int]:
    """Return the elements of list1 that also occur in list2, without duplicates."""
    remaining = set(list2)
    common: list[int] = []
    for value in list1:
        if value in remaining:
            remaining.discard(value)
            common.append(value)
    return common


def tally(
    values: list[int],
) -> dict[int, int]:
    """Count how often each value occurs."""
    counts: dict[int, int] = {}
    for value in values:
        counts[value] = counts.get(value, 0) + 1
    return counts


def multiset_intersection(
    list1: list[int],
    list2: list[int],
) -> list[int]:
    """Keep duplicates: a value appears min(count1, count2) times."""
    left = tally(list1)
    right = tally(list2)
    shared: list[int] = []
    for value in list1:
        if left[value] and right.get(value, 0):
            left[value] -= 1
            right[value] -= 1
            shared.append(value)
    return shared


def sizes(
    list1: list[int],
    list2: list[int],
) -> tuple[int, int]:
    """Return the number of distinct values in each list."""
    return len(set(list1)), len(set(list2))


def describe(
    list1: list[int],
    list2: list[int],
) -> str:
    common = list_intersection(list1, list2)
    repeated = multiset_intersection(list1, list2)
    left_size, right_size = sizes(list1, list2)
    parts: list[str] = [
        f"{list1} & {list2} -> {common}",
        f"distinct sizes {left_size}/{right_size}",
        f"with duplicates {repeated}",
    ]
    return " | ".join(parts)


def main() -> None:
    cases = [
        ([1, 2, 3], [3, 4, 5]),
        ([1, 2], [3, 4]),
        ([1, 1, 2, 2, 3], [2, 2, 3, 3]),
        ([], [7, 8]),
    ]
    for first, second in cases:
        print(describe(first, second))

    totals: dict[int, int] = tally([v for pair in cases for v in pair[0]])
    for value in sorted(totals):
        print(f"value {value} appears {totals[value]} time(s) in the left lists")


if __name__ == "__main__":
    main()

