"""Merge dictionaries of integer values and report what the merge changed."""

Scores = dict[str, int]
Change = tuple[int, int]


def update_dict(
    dict1: dict[str, int],
    dict2: dict[str, int],
) -> dict[str, int]:
    """Merge dict2 into a copy of dict1, overwriting overlapping keys."""
    merged_dict = dict(dict1)
    for key, value in dict2.items():
        merged_dict[key] = value
    return merged_dict


def overlapping_keys(
    dict1: dict[str, int],
    dict2: dict[str, int],
) -> list[str]:
    """Keys present in both dictionaries, in the order they appear in dict1."""
    return [key for key in dict1 if key in dict2]


def added_keys(
    dict1: dict[str, int],
    dict2: dict[str, int],
) -> list[str]:
    """Keys contributed only by the second dictionary."""
    return [key for key in dict2 if key not in dict1]


def changed_values(
    dict1: dict[str, int],
    dict2: dict[str, int],
) -> dict[str, Change]:
    """Map each overwritten key to its (old, new) pair of values."""
    changes: dict[str, Change] = {}
    for key in overlapping_keys(dict1, dict2):
        if dict1[key] != dict2[key]:
            changes[key] = (dict1[key], dict2[key])
    return changes


def merge_all(dicts: list[Scores]) -> Scores:
    """Fold a sequence of dictionaries left to right with update_dict."""
    result: Scores = {}
    for current in dicts:
        result = update_dict(result, current)
    return result


def format_merge(
    dict1: dict[str, int],
    dict2: dict[str, int],
) -> list[str]:
    """Human readable lines describing the merge of dict1 and dict2."""
    lines = ["merged: " + repr(update_dict(dict1, dict2))]
    for key, (old, new) in changed_values(dict1, dict2).items():
        lines.append(f"  {key}: {old} -> {new}")
    for key in added_keys(dict1, dict2):
        lines.append(f"  {key}: added as {dict2[key]}")
    return lines


def main() -> None:
    base: dict[str, int] = {"a": 1, "b": 2}
    patch: dict[str, int] = {"b": 3, "c": 4}
    for line in format_merge(base, patch):
        print(line)
    coords: dict[str, int] = {"x": 10}
    extra: dict[str, int] = {"y": 20}
    for line in format_merge(coords, extra):
        print(line)
    inventory: list[Scores] = [
        {"apples": 3, "pears": 5},
        {"pears": 7, "plums": 2},
        {"apples": 4},
    ]
    print("combined:", merge_all(inventory))


if __name__ == "__main__":
    main()

