import random

FACES: list[str] = ["Heads", "Tails"]


def simulate_coin_flip() -> str:
    """Flip a fair coin once and return 'Heads' or 'Tails'."""
    result = random.choice(FACES)
    return result


def flip_many(n: int) -> list[str]:
    """Flip the coin n times and collect the outcomes in order."""
    if n < 0:
        raise ValueError("number of flips must be non-negative")
    return [simulate_coin_flip() for _ in range(n)]


def tally(
    flips: list[str],
) -> dict[str, int]:
    """Count how often each face came up."""
    counts = {face: 0 for face in FACES}
    for face in flips:
        counts[face] += 1
    return counts


def longest_streaks(
    flips: list[str],
) -> tuple[int, int]:
    """Return the longest run of Heads and the longest run of Tails."""
    best = {face: 0 for face in FACES}
    current = 0
    previous = ""
    for face in flips:
        current = current + 1 if face == previous else 1
        if current > best[face]:
            best[face] = current
        previous = face
    return best["Heads"], best["Tails"]


def alternation_points(
    flips: list[str],
) -> list[int]:
    """Indices where the outcome differs from the preceding flip."""
    return [i for i in range(1, len(flips)) if flips[i] != flips[i - 1]]


def percentages(
    counts: dict[str, int],
) -> dict[str, float]:
    """Convert raw counts into percentages of the total."""
    total = sum(counts.values())
    if total == 0:
        return {face: 0.0 for face in counts}
    return {face: 100.0 * value / total for face, value in counts.items()}


def format_report(flips: list[str]) -> str:
    """Summarise a sequence of flips as human-readable text."""
    counts = tally(flips)
    shares = percentages(counts)
    heads_streak, tails_streak = longest_streaks(flips)
    switches = alternation_points(flips)
    lines = [f"Flips: {len(flips)}"]
    for face in FACES:
        lines.append(f"{face}: {counts[face]} ({shares[face]:.1f}%)")
    lines.append(f"Longest streaks -> Heads: {heads_streak}, Tails: {tails_streak}")
    lines.append(f"Switches: {len(switches)}")
    if switches:
        lines.append("First switch at flip " + str(switches[0] + 1))
    return "\n".join(lines)


def main() -> None:
    print("Single flip:", simulate_coin_flip())
    flips = flip_many(40)
    print(" ".join("H" if face == "Heads" else "T" for face in flips))
    print(format_report(flips))
    if max(longest_streaks(flips)) >= 5:
        print("A streak of at least five identical flips occurred.")


if __name__ == "__main__":
    main()

