def calculate_stock_profit(buy_price: float, sell_price: float, quantity: int) -> float:
    """Return the profit (positive) or loss (negative) of one stock transaction."""
    if quantity < 0:
        raise ValueError("quantity must not be negative")
    if buy_price < 0 or sell_price < 0:
        raise ValueError("prices must not be negative")
    return (sell_price - buy_price) * quantity


def parse_trade(line: str) -> tuple[str, float, float, int]:
    """Parse a 'SYMBOL,buy,sell,qty' record into its typed components."""
    parts = [field.strip() for field in line.split(",")]
    if len(parts) != 4:
        raise ValueError(f"malformed trade record: {line!r}")
    symbol, buy, sell, qty = parts
    return symbol.upper(), float(buy), float(sell), int(qty)


def trade_profits(
    records: list[str],
) -> list[float]:
    """Compute the profit/loss of every trade record, in order."""
    profits: list[float] = []
    for line in records:
        buy, sell, qty = parse_trade(line)[1:]
        profits.append(calculate_stock_profit(buy, sell, qty))
    return profits


def profit_by_symbol(
    records: list[str],
) -> dict[str, float]:
    """Aggregate profit/loss per ticker symbol."""
    totals: dict[str, float] = {}
    for line in records:
        symbol, buy, sell, qty = parse_trade(line)
        totals[symbol] = totals.get(symbol, 0.0) + calculate_stock_profit(buy, sell, qty)
    return totals


def shares_by_symbol(
    records: list[str],
) -> dict[str, int]:
    """Total quantity traded per ticker symbol."""
    volume: dict[str, int] = {}
    for line in records:
        record = parse_trade(line)
        volume[record[0]] = volume.get(record[0], 0) + record[3]
    return volume


def win_loss_count(
    profits: list[float],
) -> tuple[int, int]:
    """Return (number of profitable trades, number of losing trades)."""
    wins = sum(1 for value in profits if value > 0)
    losses = sum(1 for value in profits if value < 0)
    return wins, losses


def format_report(
    totals: dict[str, float],
    volume: dict[str, int],
) -> list[str]:
    """Build one aligned text line per symbol, best performer first."""
    lines: list[str] = []
    for symbol, profit in sorted(totals.items(), key=lambda item: -item[1]):
        lines.append(f"{symbol:<6}{volume[symbol]:>8} shares{profit:>12.2f}")
    return lines


def main() -> None:
    records: list[str] = [
        "AAPL,10.0,12.0,100",
        "MSFT,15.0,13.0,50",
        "AAPL,12.5,12.0,40",
        "NVDA,100.0,118.25,12",
    ]
    totals = profit_by_symbol(records)
    volume = shares_by_symbol(records)
    for line in format_report(totals, volume):
        print(line)
    profits = trade_profits(records)
    wins, losses = win_loss_count(profits)
    print(f"wins={wins} losses={losses} net={sum(profits):.2f}")


if __name__ == "__main__":
    main()

