STATUS_OK = "200 OK"


def check_website_status(url: str) -> str:
    """Simulate an HTTP request for *url* and return the status line."""
    return STATUS_OK


def parse_status(status: str) -> tuple[int, str]:
    """Split a status line such as '200 OK' into its code and reason phrase."""
    code, _, reason = status.partition(" ")
    return int(code), reason.strip()


def host_of(url: str) -> str:
    """Return the host part of *url*, without scheme, path or query."""
    rest = url.split("://", 1)[-1]
    return rest.split("/", 1)[0]


def check_many(
    urls: list[str],
) -> dict[str, str]:
    """Check every url and map it to the status line that was returned."""
    results: dict[str, str] = {}
    for url in urls:
        results[url] = check_website_status(url)
    return results


def status_codes(
    results: dict[str, str],
) -> list[int]:
    """Extract the numeric code of each result, in insertion order."""
    codes: list[int] = []
    for status in results.values():
        code, _ = parse_status(status)
        codes.append(code)
    return codes


def unique_hosts(
    urls: list[str],
) -> list[str]:
    """List the hosts contacted, keeping the order of first appearance."""
    seen: list[str] = []
    for url in urls:
        host = host_of(url)
        if host not in seen:
            seen.append(host)
    return seen


def format_report(results: dict[str, str]) -> str:
    """Render a batch of results as a small text table with a summary."""
    width = max(len(host_of(url)) for url in results)
    lines = []
    for url, status in results.items():
        code, reason = parse_status(status)
        lines.append(f"{host_of(url).ljust(width)}  {code} {reason}")
    codes = status_codes(results)
    distinct = ", ".join(str(code) for code in sorted(set(codes)))
    lines.append(f"{len(codes)} checked, codes seen: {distinct}")
    lines.append(f"hosts: {', '.join(unique_hosts(list(results)))}")
    return "\n".join(lines)


def main() -> None:
    sites: list[str] = [
        "http://example.com",
        "https://google.com",
        "https://python.org/downloads",
    ]
    print(check_website_status(sites[0]))
    print(check_website_status(sites[1]))
    print(format_report(check_many(sites)))


if __name__ == "__main__":
    main()

