"""Group a list of words into families of mutual anagrams."""

Words = list[str]
Groups = list[Words]
Tally = dict[str, int]


def signature(word: str) -> str:
    """Return the canonical anagram key of a word (case-insensitive)."""
    return "".join(sorted(word.lower()))


def letter_counts(word: str) -> Tally:
    """Count the letters of a word, ignoring case."""
    counts: Tally = {}
    for char in word.lower():
        counts[char] = counts.get(char, 0) + 1
    return counts


def group_anagrams(words: Words) -> Groups:
    """Group the given words so that each inner list holds mutual anagrams."""
    buckets: dict[str, Words] = {}
    for word in words:
        buckets.setdefault(signature(word), []).append(word)
    return list(buckets.values())


def group_sizes(groups: Groups) -> Tally:
    """Map each group's anagram key to the number of words it contains."""
    sizes: Tally = {}
    for group in groups:
        sizes[signature(group[0])] = len(group)
    return sizes


def largest_group(groups: Groups) -> tuple[int, int]:
    """Return the (index, size) of the biggest group, ties going to the first."""
    best: tuple[int, int] = (-1, 0)
    for index, group in enumerate(groups):
        if len(group) > best[1]:
            best = (index, len(group))
    return best


def size_histogram(groups: Groups) -> dict[int, int]:
    """Count how many groups have each size."""
    histogram: dict[int, int] = {}
    for size in group_sizes(groups).values():
        histogram[size] = histogram.get(size, 0) + 1
    return histogram


def format_groups(groups: Groups) -> list[str]:
    """Render each group as 'key: word, word' with words in stable order."""
    lines = []
    for group in groups:
        lines.append("{}: {}".format(signature(group[0]), ", ".join(group)))
    return lines


def main() -> None:
    samples: list[Words] = [
        ["eat", "tea", "tan", "ate", "nat", "bat"],
        ["a", "b"],
    ]
    for words in samples:
        groups = group_anagrams(words)
        print("input:", words)
        for line in format_groups(groups):
            print("  " + line)
        index, size = largest_group(groups)
        print("  largest group: #{} with {} word(s)".format(index, size))
        print("  letters of representative:", letter_counts(groups[index][0]))
        histogram = size_histogram(groups)
        for group_size in sorted(histogram):
            print("  size {} -> {} group(s)".format(group_size, histogram[group_size]))


if __name__ == "__main__":
    main()

