"""Helpers for merging small string-to-integer dictionaries."""
from typing import Dict, List, Tuple

Stage = Dict[str, int]
Change = Tuple[int, int]


def merge_dicts(
    dict1: Dict[str, int],
    dict2: Dict[str, int],
) -> Dict[str, int]:
    """Merge two dictionaries; values from dict2 win on conflicting keys."""
    merged: Dict[str, int] = {}
    merged.update(dict1)
    merged.update(dict2)
    return merged


def conflicting_keys(
    dict1: Dict[str, int],
    dict2: Dict[str, int],
) -> List[str]:
    """Keys present in both inputs, in the order they appear in dict1."""
    shared: List[str] = []
    for key in dict1:
        if key in dict2:
            shared.append(key)
    return shared


def overwrite_pairs(
    dict1: Stage,
    dict2: Stage,
) -> List[Change]:
    """For every conflicting key, the (old, new) value pair after merging."""
    pairs: List[Change] = []
    for key in conflicting_keys(dict1, dict2):
        pairs.append((dict1[key], dict2[key]))
    return pairs


