VOWELS = "aeiou"


def count_vowels(text: str) -> int:
    """Return the number of vowels (a, e, i, o, u) in text, case-insensitively."""
    total = 0
    for char in text.lower():
        if char in VOWELS:
            total += 1
    return total


def vowel_histogram(text: str) -> dict[str, int]:
    """Map each vowel to how many times it occurs in text."""
    counts: dict[str, int] = {vowel: 0 for vowel in VOWELS}
    for char in text.lower():
        if char in counts:
            counts[char] += 1
    return counts


def vowel_positions(text: str) -> list[int]:
    """Return the indices at which vowels appear in text."""
    positions: list[int] = []
    for index, char in enumerate(text.lower()):
        if char in VOWELS:
            positions.append(index)
    return positions


def vowel_consonant_split(text: str) -> tuple[int, int]:
    """Return (vowel count, consonant count) for the letters in text."""
    vowels = count_vowels(text)
    letters = sum(1 for char in text if char.isalpha())
    return vowels, letters - vowels


def count_vowels_per_word(text: str) -> dict[str, int]:
    """Map every whitespace-separated word to its vowel count."""
    return {word: count_vowels(word) for word in text.split()}


def most_common_vowels(text: str, limit: int = 3) -> list[str]:
    """Return the most frequent vowels, ties broken alphabetically."""
    present = [(v, n) for v, n in vowel_histogram(text).items() if n > 0]
    present.sort(key=lambda item: (-item[1], item[0]))
    return [f"{vowel}={n}" for vowel, n in present[:limit]]


def format_report(text: str) -> str:
    """Build a short multi-line summary of the vowel statistics of text."""
    split: tuple[int, int] = vowel_consonant_split(text)
    indices: list[int] = vowel_positions(text)
    lines = [
        f"text: {text!r}",
        f"vowels: {split[0]}, consonants: {split[1]}",
        f"positions: {indices}",
        "top vowels: " + ", ".join(most_common_vowels(text)),
    ]
    per_word: dict[str, int] = count_vowels_per_word(text)
    for word, n in per_word.items():
        lines.append(f"  {word}: {n}")
    return "\n".join(lines)


def main() -> None:
    samples: list[str] = ["Hello World", "Python", "Queueing is unusual"]
    for sample in samples:
        print(format_report(sample))
        print("-" * 32)
    totals: dict[str, int] = {s: count_vowels(s) for s in samples}
    print("totals:", totals)


if __name__ == "__main__":
    main()

