from typing import Dict, List, Tuple

Command = Tuple[str, str]


class ToDoList:
    """A simple to-do list tracking task completion in insertion order."""

    def __init__(self) -> None:
        self._completed: Dict[str, bool] = {}
        self._order: List[str] = []

    def add_task(self, task_name: str) -> None:
        name = task_name.strip()
        if not name:
            raise ValueError("task name must not be empty")
        if name not in self._completed:
            self._order.append(name)
        self._completed[name] = False

    def mark_completed(self, task_name: str) -> bool:
        name = task_name.strip()
        if name not in self._completed:
            return False
        self._completed[name] = True
        return True

    def get_pending_tasks(self) -> List[str]:
        return [name for name in self._order if not self._completed[name]]

    def get_completed_tasks(self) -> List[str]:
        return [name for name in self._order if self._completed[name]]

    def counts(self) -> Tuple[int, int]:
        completed = sum(1 for done in self._completed.values() if done)
        return len(self._completed) - completed, completed


def parse_commands(
    lines: List[str],
) -> List[Command]:
    commands = []
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        verb, _, argument = stripped.partition(":")
        commands.append((verb.strip().lower(), argument.strip()))
    return commands


def apply_commands(
    todo: ToDoList,
    commands: List[Command],
) -> List[str]:
    problems = []
    for verb, argument in commands:
        if verb == "add":
            todo.add_task(argument)
        elif verb == "done":
            if not todo.mark_completed(argument):
                problems.append(f"unknown task: {argument}")
        else:
            problems.append(f"unknown command: {verb}")
    return problems


def group_by_initial(
    task_names: List[str],
) -> Dict[str, int]:
    groups = {}
    for name in task_names:
        initial = name[0].upper()
        groups[initial] = groups.get(initial, 0) + 1
    return groups


def format_report(todo: ToDoList) -> str:
    pending, completed = todo.counts()
    lines = [f"{pending} pending / {completed} completed"]
    for name in todo.get_pending_tasks():
        lines.append(f"  [ ] {name}")
    for name in todo.get_completed_tasks():
        lines.append(f"  [x] {name}")
    grouped = group_by_initial(todo.get_pending_tasks())
    for initial in sorted(grouped):
        lines.append(f"  {initial}: {grouped[initial]}")
    return "\n".join(lines)


def main() -> None:
    script = [
        "add: Buy milk",
        "add: Walk dog",
        "# weekly chores",
        "add: Wash car",
        "done: Buy milk",
        "done: Call plumber",
    ]
    todo = ToDoList()
    problems = apply_commands(todo, parse_commands(script))
    print(todo.get_pending_tasks())
    print(format_report(todo))
    for problem in problems:
        print(f"warning: {problem}")


if __name__ == "__main__":
    main()

