import re
from typing import Iterable

LOG_PATTERN = re.compile(
    r"^(?P<timestamp>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) "
    r"(?P<level>[A-Z]+): (?P<message>.*)$"
)

LogRecord = dict[str, str]
LevelCounts = dict[str, int]
Clock = tuple[int, int, int]
Span = tuple[int, int]


def parse_log_line(line: str) -> LogRecord:
    match = LOG_PATTERN.match(line.strip())
    if match is None:
        raise ValueError(f"malformed log line: {line!r}")
    return match.groupdict()


def parse_log_lines(lines: Iterable[str]) -> list[LogRecord]:
    records: list[LogRecord] = []
    for line in lines:
        if line.strip():
            records.append(parse_log_line(line))
    return records


def count_levels(records: list[LogRecord]) -> LevelCounts:
    counts: LevelCounts = {}
    for record in records:
        level = record["level"]
        counts[level] = counts.get(level, 0) + 1
    return counts


def split_timestamp(timestamp: str) -> tuple[str, Clock]:
    date_part, time_part = timestamp.split(" ")
    hour, minute, second = (int(piece) for piece in time_part.split(":"))
    return date_part, (hour, minute, second)


def seconds_span(records: list[LogRecord]) -> Span:
    moments: list[int] = []
    for record in records:
        _, (hour, minute, second) = split_timestamp(record["timestamp"])
        moments.append(hour * 3600 + minute * 60 + second)
    return min(moments), max(moments)


def format_report(records: list[LogRecord]) -> str:
    counts = count_levels(records)
    first, last = seconds_span(records)
    lines: list[str] = [f"{len(records)} records spanning {last - first} seconds"]
    for level in sorted(counts):
        lines.append(f"  {level:<7} {counts[level]}")
    for record in records:
        date_part, clock = split_timestamp(record["timestamp"])
        hour, minute, _ = clock
        lines.append(f"{date_part} {hour:02d}:{minute:02d} [{record['level']}] {record['message']}")
    return "\n".join(lines)


def main() -> None:
    raw: list[str] = [
        "2023-10-26 14:30:00 INFO: User logged in.",
        "2023-10-26 14:35:15 ERROR: File not found.",
        "2023-10-26 14:35:40 WARNING: Retrying download.",
        "2023-10-26 14:36:02 INFO: Download complete.",
    ]
    print(parse_log_line(raw[0]))
    print(parse_log_line(raw[1]))
    print(format_report(parse_log_lines(raw)))


if __name__ == "__main__":
    main()

