EventList = list[str]
Calendar = dict[str, EventList]
MonthKey = tuple[int, int]
ScheduleEntry = tuple[str, str]


def parse_date(date_str: str) -> tuple[int, int, int]:
    """Split 'YYYY-MM-DD' into numeric parts, raising ValueError when malformed."""
    parts = date_str.split('-')
    if len(parts) != 3:
        raise ValueError(f"date must look like YYYY-MM-DD, got {date_str!r}")
    numbers: list[int] = []
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"non-numeric component in {date_str!r}")
        numbers.append(int(part))
    year, month, day = numbers
    if not 1 <= month <= 12 or not 1 <= day <= 31:
        raise ValueError(f"date out of range: {date_str!r}")
    return year, month, day


def add_calendar_event(calendar: Calendar, date_str: str,
                       event_description: str) -> None:
    """Append an event description to the list of events stored for a date."""
    parse_date(date_str)
    if date_str not in calendar:
        calendar[date_str] = []
    calendar[date_str].append(event_description)


def event_counts(calendar: Calendar) -> dict[str, int]:
    """Map each date to the number of events scheduled on it."""
    counts: dict[str, int] = {}
    for date_str, events in calendar.items():
        counts[date_str] = len(events)
    return counts


def busiest_dates(calendar: Calendar) -> list[str]:
    """Dates holding the maximum number of events, in chronological order."""
    counts = event_counts(calendar)
    if not counts:
        return []
    top = max(counts.values())
    hits = [date_str for date_str, total in counts.items() if total == top]
    return sorted(hits, key=parse_date)


def month_totals(calendar: Calendar) -> dict[MonthKey, int]:
    """Aggregate event counts by (year, month)."""
    totals: dict[MonthKey, int] = {}
    for date_str, events in calendar.items():
        year, month, _ = parse_date(date_str)
        key: MonthKey = (year, month)
        totals[key] = totals.get(key, 0) + len(events)
    return totals


def format_agenda(calendar: Calendar) -> list[str]:
    """Render the calendar as one readable line per date."""
    lines: list[str] = []
    for date_str in sorted(calendar, key=parse_date):
        lines.append(f"{date_str}: " + ", ".join(calendar[date_str]))
    return lines


def main() -> None:
    calendar: Calendar = {}
    schedule: list[ScheduleEntry] = [
        ('2023-10-26', 'Meeting'),
        ('2023-10-26', 'Lunch'),
        ('2023-11-02', 'Dentist'),
        ('2023-10-27', 'Code review'),
    ]
    for date_str, description in schedule:
        add_calendar_event(calendar, date_str, description)

    for line in format_agenda(calendar):
        print(line)

    print("busiest:", ", ".join(busiest_dates(calendar)))
    for (year, month), total in sorted(month_totals(calendar).items()):
        print(f"{year}-{month:02d} has {total} event(s)")


if __name__ == '__main__':
    main()

