    min_length: int,
) -> list[str]:
    """Return the strings strictly longer than min_length."""
    if min_length < 0:
        raise ValueError("min_length must be non-negative")
    return [text for text in strings if len(text) > min_length]


def lengths_of(
    strings: list[str],
) -> list[int]:
    """Return the length of every string, in the original order."""
    return [len(text) for text in strings]


