import string


def clean_word(word: str) -> str:
    """Strip surrounding punctuation from a single token."""
    return word.strip(string.punctuation)


def tokenize(sentence: str) -> list[str]:
    """Split a sentence into punctuation-free, non-empty words."""
    words: list[str] = []
    for raw in sentence.split():
        word = clean_word(raw)
        if word:
            words.append(word)
    return words


def get_word_lengths(sentence: str) -> list[int]:
    """Return the length of every word in the sentence, ignoring punctuation."""
    lengths: list[int] = [len(word) for word in tokenize(sentence)]
    return lengths


def length_histogram(sentence: str) -> dict[int, int]:
    """Count how many words share each length."""
    histogram: dict[int, int] = {}
    for length in get_word_lengths(sentence):
        histogram[length] = histogram.get(length, 0) + 1
    return histogram


def span(sentence: str) -> tuple[int, int]:
    """Return the shortest and longest word length in the sentence."""
    lengths = get_word_lengths(sentence)
    if not lengths:
        return (0, 0)
    return (min(lengths), max(lengths))


def summarize(sentence: str) -> dict[str, int]:
    """Build a small report of word statistics for one sentence."""
    lengths = get_word_lengths(sentence)
    shortest, longest = span(sentence)
    return {
        "words": len(lengths),
        "letters": sum(lengths),
        "shortest": shortest,
        "longest": longest,
    }


def format_report(sentence: str) -> list[str]:
    """Render the statistics and histogram of a sentence as text lines."""
    stats: dict[str, int] = summarize(sentence)
    lines = [f"{sentence!r}", f"  lengths: {get_word_lengths(sentence)}"]
    for key, value in stats.items():
        lines.append(f"  {key}: {value}")
    histogram = length_histogram(sentence)
    for length in sorted(histogram):
        bar: str = "#" * histogram[length]
        lines.append(f"  len {length}: {bar}")
    return lines


def main() -> None:
    samples: list[str] = [
        "Hello world, how are you?",
        "Python is great",
        "Well... that, my friend, is that!",
    ]
    for sentence in samples:
        for line in format_report(sentence):
