def normalize(text: str) -> str:
    """Keep only alphanumeric characters, folded to lower case."""
    return "".join(ch.lower() for ch in text if ch.isalnum())


def is_palindrome(text: str) -> bool:
    """Return True if text reads the same forwards and backwards."""
    cleaned = normalize(text)
    return cleaned == cleaned[::-1]


def kept_positions(text: str) -> list[int]:
    """Positions in the original text that survive normalization."""
    return [i for i, ch in enumerate(text) if ch.isalnum()]


def mismatch_offsets(text: str) -> list[int]:
    """Offsets in the normalized string whose mirror character differs."""
    cleaned = normalize(text)
    last = len(cleaned) - 1
    return [i for i in range(len(cleaned) // 2) if cleaned[i] != cleaned[last - i]]


def original_pair(text: str, offset: int) -> tuple[int, int]:
    """Map a normalized offset and its mirror back to original indices."""
    positions = kept_positions(text)
    return positions[offset], positions[len(positions) - 1 - offset]


def character_counts(text: str) -> dict[str, int]:
    """How often each normalized character occurs."""
    counts: dict[str, int] = {}
    for ch in normalize(text):
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def rearrangeable(text: str) -> bool:
    """True if the characters could be reordered into a palindrome."""
    odd = [count for count in character_counts(text).values() if count % 2]
    return len(odd) <= 1


def describe(text: str) -> str:
    """Build a one-line verdict for a single input string."""
    offsets = mismatch_offsets(text)
    if not offsets:
        return f"{text!r}: palindrome ({len(normalize(text))} significant chars)"

    left, right = original_pair(text, offsets[0])
    hint = " but its letters can be rearranged into one" if rearrangeable(text) else ""
    return (
        f"{text!r}: not a palindrome{hint}; {len(offsets)} mismatched pairs, "
        f"first is {text[left]!r} at index {left} != {text[right]!r} at index {right}"
    )


def main() -> None:
    samples = [
        "Racecar",
        "Hello, World!",
        "A man, a plan, a canal: Panama",
        "Taco cat?",
        "Never odd or evening",
    ]
    tally: dict[str, int] = {"palindromes": 0, "others": 0}
    for sample in samples:
        print(describe(sample))
        tally["palindromes" if is_palindrome(sample) else "others"] += 1
    print(f"summary: {tally['palindromes']} palindromes, {tally['others']} others")


if __name__ == "__main__":
    main()

